INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_3c944a8d9b17af3a80c8af', 'Cocktail glass', 'drink', 'A cocktail glass is a stemmed glass with an inverted cone bowl, mainly used to serve straight-up cocktails. The term cocktail glass is often used interchangeably with martini glass, despite their differing slightly.', 1, 5, 0, 'https://upload.wikimedia.org/wikipedia/commons/1/14/Cocktail-glass.jpg', 'drink', 0, 1, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'coupe', 'built', NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_3c944a8d9b17af3a80c8af', 0, 'cocktail glass', 'cocktail glass', 1, 'serving', 'pantry');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_3c944a8d9b17af3a80c8af', 0, 'A cocktail glass is a stemmed glass with an inverted cone bowl, mainly used to serve straight-up cocktails.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_3c944a8d9b17af3a80c8af', 1, 'Today, the glass is used to serve a variety of cocktails, such as the martini and its variations (Gibson, French martini, vodka martini, espresso martini, appletini), Manhattan, Brandy Alexander, pisco sour, Negroni, cosmopolitan, gimlet, and the grasshopper.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_dc8f551d445e271d929474', 'Gatorwine', 'drink', 'Gatorwine is a viral cocktail made up of red wine and Gatorade. The original recipe specifies using equal parts light blue (either Glacier Freeze or Cool Blue) gatorade and red wine "cheap, under 12 dollars", served from a chilled glass or on the rocks.', 1, 5, 0, NULL, 'drink', 0, 1, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'rocks', 'built', NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_dc8f551d445e271d929474', 0, 'one part gatorade zero cool blue', 'one part gatorade zero cool blue', 1, 'part', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_dc8f551d445e271d929474', 1, 'a barefoot pinot noir', 'a barefoot pinot noir', 1, 'part', 'pantry');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_dc8f551d445e271d929474', 0, 'The original recipe specifies using equal parts light blue (either Glacier Freeze or Cool Blue) gatorade and red wine "cheap, under 12 dollars", served from a chilled glass or on the rocks.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_dc8f551d445e271d929474', 1, 'Created by user GoatsNowhere, it was submitted to the YouTube channel Binging with Babish for the video titled Ranking Your STRANGEST Recipes | Best with Babish on Jul 30, 2024 where it was made with one part Gatorade Zero Cool Blue and a Barefoot pinot noir.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_0765ea124758d986aa05f6', 'Lanique', 'drink', 'Lanique is a strong 39% spirit liqueur made with Attar of Rose that is created by steam distilling thousands of rose petals. Lanique is often used in classic cocktails to add a rose flavour to them or due to its high alcohol strength as a drink in its own right with tonic or lemonade.', 1, 5, 0, NULL, 'drink', 0, 1, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'mug', 'built', NULL, NULL, 'unreviewed');
