INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_aa8f51bf0371ef953da172', 0, 'death in the afternoon (cocktail)', 'death in the afternoon cocktail', 1, 'serving', 'pantry');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_aa8f51bf0371ef953da172', 0, 'Hemingway''s original instructions were:

"Pour one jigger absinthe into a Champagne glass.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_aa8f51bf0371ef953da172', 1, 'Add iced Champagne until it attains the proper opalescent milkiness.');
