INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_96236efff92a7c18ecc9da', 'Kuchikamizake', 'drink', 'Kuchikamizake (口噛み酒; mouth-chewed sake) or kuchikami no sake (口噛みの酒) is a type of sake, rice-based brewed alcohol, produced by a process involving human saliva  as a fermentation starter. Kuchikamizake was one of the earliest types of Japanese alcoholic drinks.', 1, 5, 15, NULL, 'drink', 0, 1, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'rocks', 'fermented', NULL, NULL, 'unreviewed');
