INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_ab1cc69ab97c6918770492', 'Turf Cocktail', 'cocktail', 'Pre-Prohibition cocktail from Boothby''s 1908 World''s Drinks.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1908, 'The World''s Drinks and How to Mix Them (William Boothby, 1908)', 'San Francisco, USA', 'William "Cocktail" Boothby', NULL, 'A mixture of equal parts of Holland gin and any brand of vermouth,
with a few dashes of Orange bitters and a squeeze of lemon peel, is known
