INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_46977ae417699df9876b10', 1, 'Should one desire to brew a cocktail with one kind of vermouth, French vermouth should always be used, and a !ittle toddy-water may be added to it if the beverage is not to be dry.');
