INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_76c15703c957b7e4f6c9ae', 0, 'NEW ORLEANS STYLE.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_76c15703c957b7e4f6c9ae', 1, 'Into a small mixing-glass place a cube of sugar and a small piece of lemon skin (not lime skin) about twice as large as you would use for a cocktail; now add about two tablespoonfuls of boiling water and muddle well with a bar spoon until all the oil has been boiled out of the rind and the sugar has been dissolved; then add a jigger of good whiskey, and shake the whole up in a shaker containing two or three lumps of ice until enough ice has dissolved to make the drink large enough to fill a small cut bar-glass, into which you then strain it; then with a fruit fork put the lemon skin in the drink; grate a little nutmeg on top and you will then have compounded a nectar fit for the gods.');
