INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a5fda7d8a70497cd4ca850', 0, 'Friend of my soul, this goblet sip, ''Twill chase a pensive tear, ''Tis not as sweet as woman''s lip But oh! ''tis more sincere;');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a5fda7d8a70497cd4ca850', 1, 'Like her, elusive dream, ''Twill steal away the mind, But unlike affection''s dream It leaves no sting behind.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a5fda7d8a70497cd4ca850', 2, 'Germans and Saxons used to rlrink their wine and beer from horns unpro vided with handles or feet so that the horn had to be emptied by each ~rinker. "Pledging a health" is a Saxon memento.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a5fda7d8a70497cd4ca850', 3, 'The drinking horn bad to be raised in both hands and the drinker''s pledge stood beside him with sword drawn in order that no one should stab him while drinking.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a5fda7d8a70497cd4ca850', 4, 'When drinking healths as many cups were drunk as tbere·were letters in the name of the person complimented.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a5fda7d8a70497cd4ca850', 5, 'French statistics show that France exports four times as much wine as the vineyards of the country produce.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a5fda7d8a70497cd4ca850', 6, 'American statistics show that more California wines and brandies are shipped to .l!''rench ports than to all other shipping points combined.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a5fda7d8a70497cd4ca850', 7, 'These undisputed facts show that the American people are buying Cali fornia wines under French labels every day, proving conclusively the truth of P.');
