INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_646b71961b8fb25396a412', 'Bishop a la Prusse', 'cocktail', 'Pre-Prohibition drink from Tom Bullock''s 1917 manual.', 1, 3, 15, NULL, 'cocktail', 1, 1, 1917, 'The Ideal Bartender (Tom Bullock, 1917)', 'St. Louis, USA', 'Tom Bullock', 'Head bartender at the St. Louis Country Club, Tom Bullock was the first African-American author of a cocktail book. Published in 1917 with a foreword by George Herbert Walker, grandfather of President George H.W. Bush.', 'BISHOP A LA PRUSSE

Before a Fire or in a Hot Oven roast 6 large Oranges until they are of a

light brown color, and then place them in a deep dish and scatter over

them 1/2 lb. of Granulated Sugar and pour on 1 pint of Port or Claret

Wine. Then cover the dish and set aside for 24 hours before the time to

serve. When about ready for the service, set the dish in boiling water;

press the Juice from the Oranges with a large spoon or wooden potato

masher and strain the Juice through a fine seive or cheese cloth. Then

boil 1 pint of Port or Claret and mix it with the Strained Juice. Serve

in stem Claret glasses while warm. A little Nutmeg on top improves the

drink, but should not be added unless requested by customer or guest.', NULL, NULL, 'wine', 'built_hot', 'grated nutmeg', 18, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_646b71961b8fb25396a412', 0, 'Port or Claret Wine', 'port or claret wine', 1, 'pint', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_646b71961b8fb25396a412', 1, 'Port or Claret', 'port or claret', 1, 'pint', 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_646b71961b8fb25396a412', 0, 'Before a Fire or in a Hot Oven roast 6 large Oranges until they are of a light brown color, and then place them in a deep dish and scatter over them 1/2 lb.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_646b71961b8fb25396a412', 1, 'of Granulated Sugar and pour on 1 pint of Port or Claret Wine.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_646b71961b8fb25396a412', 2, 'Then cover the dish and set aside for 24 hours before the time to serve.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_646b71961b8fb25396a412', 3, 'When about ready for the service, set the dish in boiling water;');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_646b71961b8fb25396a412', 4, 'press the Juice from the Oranges with a large spoon or wooden potato masher and strain the Juice through a fine seive or cheese cloth.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_646b71961b8fb25396a412', 5, 'Then boil 1 pint of Port or Claret and mix it with the Strained Juice.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_646b71961b8fb25396a412', 6, 'Serve in stem Claret glasses while warm.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_646b71961b8fb25396a412', 7, 'A little Nutmeg on top improves the drink, but should not be added unless requested by customer or guest.');
