INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_4b354eb19461452a692479', 'Clover Club Cocktail', 'cocktail', 'Pre-Prohibition cocktail from Tom Bullock''s 1917 manual.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1917, 'The Ideal Bartender (Tom Bullock, 1917)', 'St. Louis, USA', 'Tom Bullock', 'Head bartender at the St. Louis Country Club, Tom Bullock was the first African-American author of a cocktail book. Published in 1917 with a foreword by George Herbert Walker, grandfather of President George H.W. Bush.', 'CLOVER CLUB COCKTAIL

Fill large Bar glass 1/2 full Fine Ice.



1/2 pony Raspberry Syrup.



1/2 jigger Dry Gin.



1/2 jigger French Vermouth.



White of 1 Egg.



Shake well; strain into Cocktail glass and serve.', NULL, 'Original uses raw whole egg; use pasteurized egg for modern preparation.', 'cocktail', 'shaken', NULL, 14, 'unreviewed');
