INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_bb056c3dbfceeddb719caf', 'Club House Claret Punch', 'cocktail', 'Pre-Prohibition drink from Tom Bullock''s 1917 manual.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1917, 'The Ideal Bartender (Tom Bullock, 1917)', 'St. Louis, USA', 'Tom Bullock', 'Head bartender at the St. Louis Country Club, Tom Bullock was the first African-American author of a cocktail book. Published in 1917 with a foreword by George Herbert Walker, grandfather of President George H.W. Bush.', 'CLUB HOUSE CLARET PUNCH

Fill large Bar glass 3/4 full Shaved Ice.



4 dashes Gum Syrup.



1 teaspoonful Lemon Juice.



1 teaspoonful Orange Juice.



2 jiggers Claret.



Shake; strain into tall, thin glass; fill up with Apollinaris or

Seltzer; dress with Fruit and serve.', NULL, NULL, 'highball', 'shaken', NULL, 14, 'unreviewed');
