INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_91b5660e872f5d69a88b4a', 'Crimean Cup a la Marmora (for a Party of 10)', 'cocktail', 'Pre-Prohibition drink from Tom Bullock''s 1917 manual.', 10, 3, 0, NULL, 'cocktail', 1, 1, 1917, 'The Ideal Bartender (Tom Bullock, 1917)', 'St. Louis, USA', 'Tom Bullock', 'Head bartender at the St. Louis Country Club, Tom Bullock was the first African-American author of a cocktail book. Published in 1917 with a foreword by George Herbert Walker, grandfather of President George H.W. Bush.', 'CRIMEAN CUP A LA MARMORA (for a party of 10)

Into a small Punch bowl pour:



1 pint Orgeat Syrup.



2 jiggers Jamaica Rum.



2 jiggers Maraschino.



2-1/2 jiggers Brandy.



2 tablespoonfuls Bar Sugar.



1 quart Champagne.



1 quart Plain Soda.



Stir well; pack the bowl in Fine Ice, and when cold serve in fancy Stem

glasses.', NULL, NULL, 'champagne', 'stirred', NULL, 14, 'unreviewed');
