INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_adb83f55a02ddf365bf95e', 'Currant Shrub', 'cocktail', 'Old-fashioned vinegar/fruit shrub from Bullock''s 1917 manual.', 1, 10, 15, NULL, 'cocktail', 1, 1, 1917, 'The Ideal Bartender (Tom Bullock, 1917)', 'St. Louis, USA', 'Tom Bullock', 'Head bartender at the St. Louis Country Club, Tom Bullock was the first African-American author of a cocktail book. Published in 1917 with a foreword by George Herbert Walker, grandfather of President George H.W. Bush.', 'CURRANT SHRUB

For mixing use a porcelain-lined or agate vessel, and put in:



1-1/2 lbs. Cut Loaf Sugar.



1 quart Currant Juice



Place vessel on the fire and let it boil slowly for 10 minutes, and skim

well while boiling. Then remove vessel from fire and add 1/2 gill of

Brandy to every pint of Shrub. Bottle and cork securely. This drink is

served by simply pouring a little of the Syrup into Ice Water, as any

drink from Fruit Syrup is prepared. The basis preparation for all Shrubs

or Small Fruits, such as Cherries, Raspberries, etc., is prepared in the

same way as directed for Currant Shrub, varying the quantity of Sugar

used to suit the kind of Fruit.', NULL, NULL, 'bar', 'built_hot', 'berries, cherry', 18, 'unreviewed');
