INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_fb4112ee284239c8ba0564', 'Garden Punch (2-1/2 Gallon Mixture for a Party of 50)', 'cocktail', 'Large-format punch from Bullock''s bar at the St. Louis Country Club.', 50, 3, 0, NULL, 'cocktail', 1, 1, 1917, 'The Ideal Bartender (Tom Bullock, 1917)', 'St. Louis, USA', 'Tom Bullock', 'Head bartender at the St. Louis Country Club, Tom Bullock was the first African-American author of a cocktail book. Published in 1917 with a foreword by George Herbert Walker, grandfather of President George H.W. Bush.', 'GARDEN PUNCH (2-1/2 gallon mixture for a party of 50)

Place a good size block of Ice in a large Punch bowl.



4 jiggers Lemon Juice.



1-1/2 lbs. Bar Sugar.



2 jiggers Orange Juice.



1-1/2 jiggers green Chartreuse.



1 quart Brandy.



6 Quarts Tokay or Sweet Catawba Wine.



2 quarts Claret Wine.



Stir well; ladle into Stem glasses, and decorate each glass with Fruit

before serving.', NULL, NULL, 'punch_bowl', 'stirred', NULL, 12, 'unreviewed');
