INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_873729399078576cb6e51d', 'Mint Julep--Kentucky Style', 'cocktail', 'Bullock''s celebrated julep — Roosevelt''s drink at the St. Louis Country Club.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1917, 'The Ideal Bartender (Tom Bullock, 1917)', 'St. Louis, USA', 'Tom Bullock', 'Head bartender at the St. Louis Country Club, Tom Bullock was the first African-American author of a cocktail book. Published in 1917 with a foreword by George Herbert Walker, grandfather of President George H.W. Bush.', 'MINT JULEP--Kentucky Style

Use a large Silver Mug.



Dissolve one lump of Sugar in one-half pony of Water.



Fill mug with Fine Ice.



Two jiggers of Old Bourbon Whiskey.



Stir well; add one boquet of Mint and serve.



Be careful and not bruise the Mint.', NULL, NULL, 'julep', 'stirred', 'mint sprig', 28, 'unreviewed');
