INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_6fb03336ce2f946bcd01b0', 'Punch a la Romaine (for a Party of 16)', 'cocktail', 'Large-format punch from Bullock''s bar at the St. Louis Country Club.', 16, 3, 0, NULL, 'cocktail', 1, 1, 1917, 'The Ideal Bartender (Tom Bullock, 1917)', 'St. Louis, USA', 'Tom Bullock', 'Head bartender at the St. Louis Country Club, Tom Bullock was the first African-American author of a cocktail book. Published in 1917 with a foreword by George Herbert Walker, grandfather of President George H.W. Bush.', 'PUNCH A LA ROMAINE (for a party of 16)

1 bottle Champagne.



1 bottle Rum.



2 tablespoons Dr. Siegert''s genuine Angostura Bitters.



10 Lemons.



3 sweet Oranges.



2 pounds Powdered Sugar.



10 fresh Eggs.



Dissolve the Sugar in the Juice of the Lemons and Oranges adding the

Rind of 1 Orange.



Strain through a Sieve into a bowl and add by degrees the whites of the

Eggs beaten to a froth.



Place the bowl on Ice till cold, then stir in the Rum and Wine until

thoroughly mixed. Serve in fancy Stem glasses.', NULL, 'Original uses raw whole egg; use pasteurized egg for modern preparation.', 'champagne', 'stirred', NULL, 12, 'unreviewed');
