INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_a54cd8af71df58cacd224d', 'Tokay Punch', 'cocktail', 'Pre-Prohibition drink from Tom Bullock''s 1917 manual.', 1, 3, 15, NULL, 'cocktail', 1, 1, 1917, 'The Ideal Bartender (Tom Bullock, 1917)', 'St. Louis, USA', 'Tom Bullock', 'Head bartender at the St. Louis Country Club, Tom Bullock was the first African-American author of a cocktail book. Published in 1917 with a foreword by George Herbert Walker, grandfather of President George H.W. Bush.', 'TOKAY PUNCH

Out of 6 pounds of Tokay Grapes, select one pound to be put into the

Punch last. Now make a boiling Syrup of three pounds of Sugar and one

quart of boiling Water and pour this over the remaining five pounds of

Grapes. When partly cold rub it through a sieve, leaving skins and seeds

behind. Then add the Juice of two Oranges and two Lemons and one quart

of St. Julien Claret, 1 jigger of Angostura Bitters.



Then strain and freeze.



Before serving add 1 pint of good Brandy and an Italian Meringue Paste

of six Egg whites, colored a nice red and drop in the remaining Grapes.', NULL, 'Original uses raw whole egg; use pasteurized egg for modern preparation.', 'punch', 'built_hot', NULL, 12, 'unreviewed');
