INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_b00e4b0c6b8b36f86eb760', 7, 'Gradually add remaining 1/4 cup sugar, beating to stiff peaks');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_b00e4b0c6b8b36f86eb760', 8, 'Fold yolk mixture and whipped cream into egg whites');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_b00e4b0c6b8b36f86eb760', 9, 'Serve immediately');
