INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_0630598867842f511b2566', 'Egg-Nog - Classic Cooked', 'cocktail', 'Punch / Party Drink — served in a pitcher', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/quxsvt1468875505.jpg', 'mocktail', 0, 0, NULL, 'TheCocktailDB', NULL, NULL, NULL, NULL, NULL, NULL, 'pitcher', 'stirred', NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_0630598867842f511b2566', 0, 'Egg', 'egg', 6, 'piece', 'dairy');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_0630598867842f511b2566', 1, 'Sugar', 'sugar', 0.25, 'cup', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_0630598867842f511b2566', 2, 'Salt', 'salt', 0.25, 'tsp', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_0630598867842f511b2566', 3, 'Milk', 'milk', 1, 'qt', 'dairy');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_0630598867842f511b2566', 4, 'Vanilla extract', 'vanilla extract', 1, 'tsp', 'pantry');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0630598867842f511b2566', 0, 'In large saucepan, beat together eggs, sugar and salt, if desired');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0630598867842f511b2566', 1, 'Stir in 2 cups of the milk');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0630598867842f511b2566', 2, 'Cook over low heat, stirring constantly, until mixture is thick enough to coat a metal spoon and reaches 160 degrees F');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0630598867842f511b2566', 3, 'Remove from heat');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0630598867842f511b2566', 4, 'Stir in remaining 2 cups milk and vanilla');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0630598867842f511b2566', 5, 'Cover and regfigerate until thoroughly chilled, several hours or overnight');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0630598867842f511b2566', 6, 'Just before serving, pour into bowl or pitcher');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0630598867842f511b2566', 7, 'Garnish or add stir-ins, if desired');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0630598867842f511b2566', 8, 'Choose 1 or several of: Chocolate curls, cinnamon sticks, extracts of flavorings, flavored brandy or liqueur, fruit juice or nectar, ground nutmeg, maraschino cherries, orange slices, peppermint sticks or candy canes, plain brandy, run or whiskey, sherbet or ice-cream, whipping cream, whipped');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0630598867842f511b2566', 9, 'Serve immediately');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_89d22dd4b4e5312bfef3d8', 'Empellón Cocina''s Fat-Washed Mezcal', 'cocktail', 'Cocktail — served in a beer glass', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/osgvxt1513595509.jpg', 'cocktail', 0, 1, NULL, 'TheCocktailDB', NULL, NULL, NULL, NULL, NULL, NULL, 'pint', 'shaken', '5 drops habanero tincture', 26, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_89d22dd4b4e5312bfef3d8', 0, 'Mezcal', 'mezcal', 2, 'oz', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_89d22dd4b4e5312bfef3d8', 1, 'Chocolate liqueur', 'chocolate liqueur', 0.75, 'oz', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_89d22dd4b4e5312bfef3d8', 2, 'Coffee liqueur', 'coffee liqueur', 0.5, 'oz', 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 0, 'To ensure that your pork fat is just as delicious as theirs, here’s their adobo marinade and what to do with it (you’ll also need a rack of ribs):');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 1, '4 ancho chiles, 8 guajillo chiles and 4 chipotle chiles, plus 4 cloves roasted garlic, half a cup of cider vinegar, a quarter teaspoon of Mexican oregano, 1 teaspoon of ground black pepper, a whole clove, a quarter teaspoon of ground cinnamon and a half teaspoon of ground cumin');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 2, 'Toast the dried chiles and soak in water for at least an hour until they are rehydrated');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 3, 'Drain and discard the soaking liquid');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 4, 'Combine the soaked chiles with the remaining ingredients and purée until smooth');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 5, 'Cold smoke a rack of baby back pork ribs by taking a large hotel pan with woodchips on one side and charcoal on the other');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 6, 'Place another, smaller, pan with pork ribs, above the charcoal/woodchip pan');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 7, 'Ignite the charcoal, being careful to not ignite the woodchips');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 8, 'Cover both pans with foil and allow to smoke for 10-15 minutes, until desired level of smoke is achieved, then coat with adobo marinade and wrap in tin foil prior to placing ribs in a 300 degree oven for 7 hours');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 9, 'When the ribs have cooled, strain off the fat and use for the infusion');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 10, 'If you’re having a hard time coming up to the same kind of volume of fat, make up the balance with pork lard from a butcher');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 11, 'To get the same depth of flavor without the ribs, heat up the fat in a pot with a few spoons of the marinade');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 12, 'Once you’ve got your tub of seasoned pork fat in cooled liquid form, pour equal amounts of Ilegal Joven mezcal and fat into a sealable container');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 13, 'Seal the container and give it a really good shake, then put it in the freezer overnight');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 14, 'When the whole thing is separated and congealed, pour it through a fine mesh chinoise');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 15, 'If you don’t have a chinoise, try a fine mesh strainer, or if you don’t have one of those, try spooning off most of the fat');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 16, 'There will be some beads of orange fat left in the strained mezcal: run that through a few layers of cheesecloth (or coffee filters in a pinch) to get rid of the last of it');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 17, 'The mezcal is now ready for drinking, straight-up or in a cocktail');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 18, 'Habanero tincture');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 19, 'Slice habaneros and add 2 ounces Ilegal Joven mezcal');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 20, 'Allow to sit overnight or until desired level of heat is achieved');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 21, 'Cocktail');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 22, 'Combine mezcal and chocolate liqueur in a mixing glass with ice and stir for 45 seconds');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 23, 'Strain into chilled coupe');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 24, 'Carefully "sink" the coffee liqueur down the inside of the coupe over a spoon');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_89d22dd4b4e5312bfef3d8', 25, 'Garnish with 5 drops habanero tincture');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_7f03bf738ed76a54c3bda5', 'Frosé', 'cocktail', 'Cocktail — served in a cocktail glass', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/b4cadp1619695347.jpg', 'cocktail', 0, 1, NULL, 'TheCocktailDB', NULL, NULL, NULL, NULL, NULL, NULL, 'coupe', 'shaken', NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_7f03bf738ed76a54c3bda5', 0, 'Rose', 'rose', 25, 'oz', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_7f03bf738ed76a54c3bda5', 1, 'Sugar', 'sugar', 0.5, 'cup', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_7f03bf738ed76a54c3bda5', 2, 'Strawberries', 'strawberries', 8, 'oz', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_7f03bf738ed76a54c3bda5', 3, 'Lemon Juice', 'lemon juice', 2, '-3 oz', 'produce');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7f03bf738ed76a54c3bda5', 0, 'Step 1');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7f03bf738ed76a54c3bda5', 1, 'Pour rosé into a 13x9" pan and freeze until almost solid (it won''t completely solidify due to the alcohol), at least 6 hours');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7f03bf738ed76a54c3bda5', 2, 'Step 2');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7f03bf738ed76a54c3bda5', 3, 'Meanwhile, bring sugar and ½ cup water to a boil in a medium saucepan; cook, stirring constantly, until sugar dissolves, about 3 minutes');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7f03bf738ed76a54c3bda5', 4, 'Add strawberries, remove from heat, and let sit 30 minutes to infuse syrup with strawberry flavor');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7f03bf738ed76a54c3bda5', 5, 'Strain through a fine-mesh sieve into a small bowl (do not press on solids); cover and chill until cold, about 30 minutes');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7f03bf738ed76a54c3bda5', 6, 'Step 3');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7f03bf738ed76a54c3bda5', 7, 'Scrape rosé into a blender');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7f03bf738ed76a54c3bda5', 8, 'Add lemon juice, 3½ ounces strawberry syrup, and 1 cup crushed ice and purée until smooth');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7f03bf738ed76a54c3bda5', 9, 'Transfer blender jar to freezer and freeze until frosé is thickened (aim for milkshake consistency), 25–35 minutes');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7f03bf738ed76a54c3bda5', 10, 'Step 4');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7f03bf738ed76a54c3bda5', 11, 'Blend again until frosé is slushy');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7f03bf738ed76a54c3bda5', 12, 'Divide among glasses');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7f03bf738ed76a54c3bda5', 13, 'Step 5');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7f03bf738ed76a54c3bda5', 14, 'Do Ahead: Rosé can be frozen 1 week ahead');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_b65faa7896f6d5e739528a', 'Frappé', 'cocktail', 'Coffee / Tea — served in a highball glass', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/vqwryq1441245927.jpg', 'mocktail', 0, 0, NULL, 'TheCocktailDB', NULL, NULL, NULL, NULL, NULL, NULL, 'highball', 'blended', NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_b65faa7896f6d5e739528a', 0, 'Coffee', 'coffee', 0.5, 'cup', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_b65faa7896f6d5e739528a', 1, 'Milk', 'milk', 0.5, 'cup', 'dairy');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_b65faa7896f6d5e739528a', 2, 'Sugar', 'sugar', 1, '-2 tsp', 'pantry');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_b65faa7896f6d5e739528a', 0, 'Mix together');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_b65faa7896f6d5e739528a', 1, 'Blend at highest blender speed for about 1 minute');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_b65faa7896f6d5e739528a', 2, 'Pour into a glass and drink with a straw');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_b65faa7896f6d5e739528a', 3, 'Notes: This works best if everything is cold (if you make fresh coffee, mix it with the milk and let it sit in the fridge for 1/2 hour');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_b65faa7896f6d5e739528a', 4, 'If it is not frothy, add more milk, or even just some more milk powder');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_b65faa7896f6d5e739528a', 5, 'The froth gradually turns to liquid at the bottom of the glass, so you will find that you can sit and drink this for about 1/2 hour, with more iced coffee continually appearing at the bottom');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_b65faa7896f6d5e739528a', 6, 'Very refreshing');
