INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_27d27f47fa3bba05a37f44', 0, 'Tip the cherry juice, orange peel, chilli, cinnamon sticks, cloves and ginger into a large saucepan');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_27d27f47fa3bba05a37f44', 1, 'Simmer for 5 mins, then turn off the heat');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_27d27f47fa3bba05a37f44', 2, 'Leave to cool, then chill for at least 4 hrs, or up to 2 days – the longer you leave it the more intense the flavours');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_27d27f47fa3bba05a37f44', 3, 'If serving to young children, take the chilli out after a few hours');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_27d27f47fa3bba05a37f44', 4, 'When you’re ready to serve, pour the juice into a jug');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_27d27f47fa3bba05a37f44', 5, 'Serve in glass bottles or glasses and pop a straw in each');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_27d27f47fa3bba05a37f44', 6, 'If you''re adding vodka, do so at this stage');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_27d27f47fa3bba05a37f44', 7, 'Dangle a fangs sweet from each glass');
