INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_58c9c663d753062d59e789', 0, 'Rub the rim of the glass with the lime slice to make the salt stick to it');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_58c9c663d753062d59e789', 1, 'Take care to moisten only the outer rim and sprinkle the salt on it');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_58c9c663d753062d59e789', 2, 'The salt should present to the lips of the imbiber and never mix into the cocktail');
