INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_d09284a181475bc2d4ead3', 'Mint Julep', 'cocktail', 'Ordinary Drink — served in a collins glass', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/squyyq1439907312.jpg', 'cocktail', 0, 1, 1803, 'TheCocktailDB', 'American South, USA', NULL, 'Rooted in 18th-century Virginia as a morning medicinal, the julep entered print in 1803 and was defined with bourbon, sugar, and mint by the 1830s. Senator Henry Clay helped popularize it in Washington, and Churchill Downs made it the official drink of the Kentucky Derby in 1938. It is the South''s most storied cocktail.', NULL, NULL, NULL, 'collins', 'built', 'mint', 31, 'unreviewed');
