INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_737141f64bf8f086de6653', 'Pisco Sour', 'cocktail', 'IBA New Era Drinks — Cocktail — served in a cocktail glass', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/tsssur1439907622.jpg', 'cocktail', 0, 1, 1922, 'TheCocktailDB', 'Lima, Peru', NULL, 'Created by American bartender Victor Vaughen Morris at his Morris Bar in Lima around 1922, adapting the Whiskey Sour to Peru''s native pisco grape brandy. Mario Bruiget later refined the recipe with egg white and Angostura bitters. Peru and Chile still feud over ownership of both the spirit and the drink.', NULL, NULL, NULL, 'coupe', 'shaken', 'bitters', 21, 'unreviewed');
