INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_558f3edb115cbe7074440b', 'Ramos Gin Fizz', 'cocktail', 'Cocktail — served in a highball glass', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/967t911643844053.jpg', 'cocktail', 0, 1, 1888, 'TheCocktailDB', 'New Orleans, USA', NULL, 'Invented by Henry C. Ramos at his Imperial Cabinet Saloon in New Orleans in 1888, requiring a notoriously long 12-minute shake to emulsify cream, egg white, and orange flower water. During Mardi Gras, Ramos employed dozens of shaker boys working in relay. Governor Huey Long famously flew a New Orleans bartender to New York to teach it.', NULL, NULL, NULL, 'highball', 'shaken', NULL, 9, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_558f3edb115cbe7074440b', 0, 'Gin', 'gin', 1.53, 'oz', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_558f3edb115cbe7074440b', 1, 'Lemon Juice', 'lemon juice', 1.02, 'oz', 'produce');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_558f3edb115cbe7074440b', 2, 'Sugar Syrup', 'sugar syrup', 1.02, 'oz', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_558f3edb115cbe7074440b', 3, 'Cream', 'cream', 2.04, 'oz', 'dairy');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_558f3edb115cbe7074440b', 4, 'Egg White', 'egg white', 1, 'piece', 'dairy');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_558f3edb115cbe7074440b', 5, 'Vanilla extract', 'vanilla extract', 2, 'drop', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_558f3edb115cbe7074440b', 6, 'Soda Water', 'soda water', 0.68, 'oz', 'pantry');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_558f3edb115cbe7074440b', 0, 'Prepare all the ingredients on the counter to be able to work well and quickly, especially the cream and egg white');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_558f3edb115cbe7074440b', 1, 'Pour all the ingredients into a shaker');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_558f3edb115cbe7074440b', 2, 'Shake vigorously for 1 minute: cream and egg white must be mixed perfectly, so don''t rush');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_558f3edb115cbe7074440b', 3, 'Now open the shaker and put some ice and shake for 1-2 minutes');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_558f3edb115cbe7074440b', 4, 'It depends on how long you can resist!');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_558f3edb115cbe7074440b', 5, 'Pour into a highball glass, add a splash of soda and garnish to taste');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_558f3edb115cbe7074440b', 6, 'Ramos Gin Fizz was once drunk as an invigorating drink or even as a breakfast, try it as an aperitif and after dinner and you will discover a little gem now lost');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_155e4b9f4fe8807539f90e', 'Royal Gin Fizz', 'cocktail', 'Ordinary Drink — served in a highball glass', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/pe1x1c1504735672.jpg', 'cocktail', 0, 1, NULL, 'TheCocktailDB', NULL, NULL, NULL, NULL, NULL, NULL, 'highball', 'shaken', NULL, 29, 'unreviewed');
