INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_895410c0ef864c2aa8cf42', 'Stinger', 'cocktail', 'IBA Unforgettables — Ordinary Drink — served in a cocktail glass', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/2ahv791504352433.jpg', 'cocktail', 0, 1, 1890, 'TheCocktailDB', 'New York City, USA', NULL, 'A late 19th-century American after-dinner drink of cognac and white creme de menthe, shaken or stirred over ice. It appears in William Boothby''s 1908 World''s Drinks and was the favorite of characters from Reggie Van Gleason to James Bond in Diamonds Are Forever. Its minty bite gave it the name.', NULL, NULL, NULL, 'coupe', 'stirred', NULL, 22, 'unreviewed');
