INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_895410c0ef864c2aa8cf42', 0, 'Pour in a mixing glass with ice, stir and strain into a cocktail glass');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_895410c0ef864c2aa8cf42', 1, 'May also be served on rocks in a rocks glass');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_3d7b15741e9a5a35037cb9', 'Sazerac', 'cocktail', 'IBA Unforgettables — Ordinary Drink — served in a old-fashioned glass', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/vvpxwy1439907208.jpg', 'cocktail', 0, 1, 1850, 'TheCocktailDB', 'New Orleans, USA', NULL, 'Born in New Orleans around 1850 at the Sazerac Coffee House, where apothecary Antoine Peychaud''s proprietary bitters were mixed with Sazerac-de-Forge cognac. After the 1873 phylloxera blight wiped out French vineyards, bartenders swapped cognac for rye whiskey. It is often cited as America''s first branded cocktail.', NULL, NULL, NULL, 'rocks', 'stirred', 'lemon peel', 29, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_3d7b15741e9a5a35037cb9', 0, 'Ricard', 'ricard', 1, 'tsp', 'pantry');
