INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_9fe4f411efeb41855ce6f0', 'Jersey Sunset', 'cocktail', NULL, 1, 3, 0, NULL, 'cocktail', 1, 1, 1908, 'Jack''s Manual (J.A. Grohusko, 1908)', 'New York, USA', NULL, NULL, 'JERSEY   SUNSET
Into  a  straight  champagne  glass  put  a  scant  teaspoonful
of  sugar  with  enough  water  to  dissolve.  Add  a  twist  of
lemon  or  lime  peel  and  half  a  whiskey  glass  of  line  Old  Mon-
mouth Applejack.  Now  put  in  enough  broken  ice  to  cool,
fill  with  water  and  finish  with  a  dash  or  two  of  Angostura
bitters,  which  should  not  be  stirred  in,  but  be  allowed  to
drop  slowly  through  the  amber  mixture,  imparting  to  it  the
sunset  hues  that  probably  suggested  its  name.
In  winter,  instead  of  ice,  hot  water  is  used,  making  a
most  genial   drink — A   Hot  Sunset.', NULL, NULL, 'coupe', 'stirred', NULL, NULL, 'unreviewed');
