INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_a5c33ced46d467c93b5bb0', 'Old Oxford College Mulled Ale', 'cocktail', NULL, 1, 3, 0, NULL, 'cocktail', 1, 1, 1908, 'Jack''s Manual (J.A. Grohusko, 1908)', 'New York, USA', NULL, NULL, 'OLD    OXFORD     COLLEGE     MULLED     ALE
Take  i  lb.  Cinnamon,  \  11).  Cloves,  put  both  into  a
saucepan  with  two  quarts  of  water,  put  it  over  the  fire  till
it  boils,  then  let  it  simmer  for  an  hour,  then  strain  it  oft
into  a  jug.  and  when  cold  put  the  liquid  into  a  bottle  and
well  cork  down.
When  making  Mulled  ale,  add  one  wineglass  of  the
liquid  to  every  quart  of  Bass  &  Co.''s  Barley  wine  or  Strong
Ale,  adding  a  little  ginger  and  loaf  sugar  to  taste.  Heat  the
ale  over  a  brisk,  fire,  but  be  sure  not  to  let  it  boil,  as  that
alters  the  flavor,  but  take  it  off  just  before  it  boils.
Add  a  few  slices  of  lemon,  and  a  wine-glass  of  gin  to
every  quart.', NULL, NULL, 'wine', NULL, NULL, NULL, 'unreviewed');
