INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_f36b1a489bf989955ab4f0', 'Punch A La Romaine', 'cocktail', NULL, 1, 3, 0, NULL, 'cocktail', 1, 1, 1908, 'Jack''s Manual (J.A. Grohusko, 1908)', 'New York, USA', NULL, NULL, 'PUNCH  A  LA   ROMAINE
1   bottle   champagne
1  bottle  rum
2  tablespoons  Angostura  bitters
10  lemons
3  sweet  oranges
2  pounds  powdered  sugar
10  fresh  eggs.
For  a  party  of  15.
Dissolve  the  sugar  in  the  juice  of  the  lemons  and
oranges,  adding  the  rind  of  one  orange,  strain  through  a  sieve
into  a  bowl,  and  add  by  degrees  the  whites  of  the  eggs,
beaten  to  a  froth.  Place  the  bowl  on  ice  till  cold,  then  stir
in  the  rum  and  wine  until  thoroughly  mixed.  Serve  in  fancy
stem  glass.', NULL, NULL, 'coupe', 'stirred', NULL, NULL, 'unreviewed');
