INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_1f4f7a93e49b3d6bc8e0d1', 1, 'Dr. Siegert''s Genuine Angostura bitters, one', 'dr siegerts genuine angostura bitters one', 2, 'tbsp', 'bar');
