INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_442bc8bddba3d75bd1267a', '24k nightmare', 'shot', 'The 24k Nightmare shot is a potent member of the layered shooter family, known for its strong, bold flavors. This intense drink combines Goldschl_ger''s cinnamon heat, J_germeister''s herbal complexity, Rumple Minze''s peppermint chill, and Bacardi 151''s high-proof kick. It likely emerged in the modern bar scene, catering to thrill-seekers looking for a powerful, memorable shot.', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/yyrwty1468877498.jpg', 'cocktail', 0, 1, NULL, 'HuggingFace: yujinyang/cocktails_436', NULL, NULL, NULL, NULL, NULL, NULL, 'shot glass', NULL, NULL, NULL, 'unreviewed');
