INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_07ff3aeb7aebb2072a4cd9', '3 wise men', 'shot', 'Three wise men is a drink consisting of three types of whiskey with brand names that are each named after a man (ordinarily Johnnie Walker, Jack Daniel and Jim Beam). The three named men are the "wise men" in the name of the drink, which is an allusion to the Biblical Magi. Several variations exist that include other ingredients or substitute tequila or rum for some of the whiskey.', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/wxqpyw1468877677.jpg', 'cocktail', 0, 1, NULL, 'HuggingFace: yujinyang/cocktails_436', NULL, NULL, NULL, NULL, NULL, NULL, 'collins glass', NULL, NULL, NULL, 'unreviewed');
