INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_741941ae847731d2e6bd33', 'autodafe', 'ordinary drink', 'Autodafe is appealing average cocktail at 1 standard drinks. best with lunch. Just fill glass with ice cubes then add shot of vodka and pour in lime juice.', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/7dkf0i1487602928.jpg', 'cocktail', 0, 1, NULL, 'HuggingFace: yujinyang/cocktails_436', NULL, NULL, NULL, NULL, NULL, NULL, 'highball glass', NULL, NULL, NULL, 'unreviewed');
