INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_477feb10e7961e92f5ba26', 'frose', 'cocktail', 'Fros_ is a mixed drink made from ros_ wine frozen to a slush, with strawberries, vodka, and lemon juice.', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/b4cadp1619695347.jpg', 'cocktail', 0, 1, NULL, 'HuggingFace: yujinyang/cocktails_436', NULL, NULL, NULL, NULL, NULL, NULL, 'cocktail glass', NULL, NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_477feb10e7961e92f5ba26', 0, 'rose', 'rose', 750, 'ml', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_477feb10e7961e92f5ba26', 1, 'sugar', 'sugar', 1, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_477feb10e7961e92f5ba26', 2, 'strawberries', 'strawberries', 8, 'oz', 'produce');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_477feb10e7961e92f5ba26', 3, 'lemon juice', 'lemon juice', 2, NULL, 'produce');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_477feb10e7961e92f5ba26', 0, 'Step 1 Pour ros_ into a 13x9" pan and freeze until almost solid (it won''t completely solidify due to the alcohol), at least 6 hours');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_477feb10e7961e92f5ba26', 1, 'Step 2 Meanwhile, bring sugar and '' cup water to a boil in a medium saucepan');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_477feb10e7961e92f5ba26', 2, 'cook, stirring constantly, until sugar dissolves, about 3 minutes');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_477feb10e7961e92f5ba26', 3, 'Add strawberries, remove from heat, and let sit 30 minutes to infuse syrup with strawberry flavor');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_477feb10e7961e92f5ba26', 4, 'Strain through a fine-mesh sieve into a small bowl (do not press on solids)');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_477feb10e7961e92f5ba26', 5, 'cover and chill until cold, about 30 minutes');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_477feb10e7961e92f5ba26', 6, 'Step 3 Scrape ros_ into a blender');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_477feb10e7961e92f5ba26', 7, 'Add lemon juice, 3'' ounces strawberry syrup, and 1 cup crushed ice and pur_e until smooth');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_477feb10e7961e92f5ba26', 8, 'Transfer blender jar to freezer and freeze until fros_ is thickened (aim for milkshake consistency), 25''35 minutes');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_477feb10e7961e92f5ba26', 9, 'Step 4 Blend again until fros_ is slushy');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_477feb10e7961e92f5ba26', 10, 'Divide among glasses');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_477feb10e7961e92f5ba26', 11, 'Step 5 Do Ahead: Ros_ can be frozen 1 week ahead');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_d3756e9992b030e9061f53', 'frappe', 'coffee / tea', 'The Frappe, a simple blend of coffee, milk, and sugar, belongs to the Coffee Cocktail family. Originating in Greece in the early 20th century, it''s a refreshing, iced beverage popularized by the Nescaf? brand, providing a delightful jolt of caffeine.', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/vqwryq1441245927.jpg', 'drink', 0, 0, NULL, 'HuggingFace: yujinyang/cocktails_436', NULL, NULL, NULL, NULL, NULL, NULL, 'highball glass', NULL, NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_d3756e9992b030e9061f53', 0, 'coffee', 'coffee', 1, NULL, 'drinks');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_d3756e9992b030e9061f53', 1, 'milk', 'milk', 1, NULL, 'dairy');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_d3756e9992b030e9061f53', 2, 'sugar', 'sugar', 1, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d3756e9992b030e9061f53', 0, 'Mix together');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d3756e9992b030e9061f53', 1, 'Blend at highest blender speed for about 1 minute');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d3756e9992b030e9061f53', 2, 'Pour into a glass and drink with a straw');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d3756e9992b030e9061f53', 3, 'Notes: This works best if everything is cold (if you make fresh coffee, mix it with the milk and let it sit in the fridge for 1/2 hour');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d3756e9992b030e9061f53', 4, 'If it is not frothy, add more milk, or even just some more milk powder');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d3756e9992b030e9061f53', 5, 'The froth gradually turns to liquid at the bottom of the glass, so you will find that you can sit and drink this for about 1/2 hour, with more iced coffee continually appearing at the bottom');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d3756e9992b030e9061f53', 6, 'Very refreshing');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_04075d4a53ae8520f35b8f', 'planter_ punch', 'cocktail', 'Planter Punch is a rum-based Jamaican punch cocktail. Its name, literally meaning "planter''s punch," is said to have originated in the 19th century, when it was created by a planter''s wife for her workers on a Jamaican plantation.', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/jn6o251643844541.jpg', 'cocktail', 0, 1, NULL, 'HuggingFace: yujinyang/cocktails_436', NULL, NULL, NULL, NULL, NULL, NULL, 'highball glass', NULL, NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_04075d4a53ae8520f35b8f', 0, 'dark rum', 'dark rum', 4.5, 'cl', 'bar');
