INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_04075d4a53ae8520f35b8f', 2, 'pineapple juice', 'pineapple juice', 3.5, 'cl', 'produce');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_04075d4a53ae8520f35b8f', 3, 'grenadine', 'grenadine', 1, 'cl', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_04075d4a53ae8520f35b8f', 4, 'sugar syrup', 'sugar syrup', 1, 'cl', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_04075d4a53ae8520f35b8f', 5, 'angostura bitters', 'angostura bitters', 4, 'drops', 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_04075d4a53ae8520f35b8f', 0, 'Squeeze an orange and strain the juice');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_04075d4a53ae8520f35b8f', 1, 'Put all the ingredients in a shaker filled with ice and shake for at least 12 seconds');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_04075d4a53ae8520f35b8f', 2, 'Strain into a highball glass and decorate with a pineapple wedge or fruit of your choice');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_0d6c0e3e1580c85110c7fe', 'Best Lemonade', 'beverages', 'This is from one of my  first Good House Keeping cookbooks.  You must use a *zester* in order to avoid getting any of that bitter rind, and when you zest the lemons, zest them onto some sugar from the recipe (the sugar will ''catch'' all of the oils).  I also advise you from personal experience to use only the best skinned lemons for the best flavor.', 4, 30, 5, 'https://img.sndimg.com/food/image/upload/w_555,h_416,c_fit,fl_progressive,q_95/v1/img/recipes/40/picJ4Sz3N.jpg', 'drink', 0, 0, NULL, 'HuggingFace: AkashPS11/recipes_data_food.com', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_0d6c0e3e1580c85110c7fe', 0, 'sugar', 'sugar', 1.5, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_0d6c0e3e1580c85110c7fe', 1, 'lemons, rind of', 'lemons rind of', 1, NULL, 'produce');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_0d6c0e3e1580c85110c7fe', 2, 'lemon, zest of', 'lemon zest of', 1.5, NULL, 'produce');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_0d6c0e3e1580c85110c7fe', 3, 'fresh water', 'fresh water', 3, NULL, 'drinks');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_0d6c0e3e1580c85110c7fe', 4, 'fresh lemon juice', 'fresh lemon juice', 0, NULL, 'produce');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0d6c0e3e1580c85110c7fe', 0, 'Into a 1 quart Jar with tight fitting lid, put sugar and lemon peel, or zest;  add 1 1/2 cups very hot water (not from tap!). With lid fitted firmly, shake jar until sugar is dissolved.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0d6c0e3e1580c85110c7fe', 1, 'Add lemon juice. Refrigerate until chilled.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0d6c0e3e1580c85110c7fe', 2, 'To Serve: Into each 12-ounce glass, over ice cubes, pour 1/4 cup of the lemon syrup.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0d6c0e3e1580c85110c7fe', 3, 'Then add chilled club soda or, if you prefer, water.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0d6c0e3e1580c85110c7fe', 4, 'Stir to mix well.');
