INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_85e92a8051af2b9a62e976', 0, 'Combine espresso, milk, sugar and pectin in a pitcher or covered container.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_85e92a8051af2b9a62e976', 1, 'Stir or shake until sugar is dissolved.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_85e92a8051af2b9a62e976', 2, 'Chill and serve cold.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_85e92a8051af2b9a62e976', 3, 'NOTES :');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_85e92a8051af2b9a62e976', 4, 'To make the "Mocha" variety, add a pinch (1/16 teaspoon) of cocoa powder to the mixture before combining.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_85e92a8051af2b9a62e976', 5, 'To fake espresso with a drip coffee maker and standard grind of coffee:');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_85e92a8051af2b9a62e976', 6, 'Use 1/3 cup ground coffee and 1 cup of water.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_85e92a8051af2b9a62e976', 7, 'Brew once then run coffee through machine again, same grounds.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_85e92a8051af2b9a62e976', 8, 'Makes about 1/2 cup fresh espresso to use in the above recipe.');
