INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_2c7eb152b9b0a0f7506271', 13, '(1 quart) sterilized canning jar with lid and ring', '1 quart sterilized canning jar with lid and ring', 1, NULL, 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_2c7eb152b9b0a0f7506271', 14, 'white sugar', 'white sugar', 1, 'tablespoon', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_2c7eb152b9b0a0f7506271', 15, 'salt', 'salt', 1, 'teaspoons', 'pantry');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2c7eb152b9b0a0f7506271', 0, 'Gather the ingredients.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2c7eb152b9b0a0f7506271', 1, 'Process tomatoes, onion, 3 tablespoons plus 1/2 teaspoon celery, carrot, beet, green bell pepper, and garlic through a juicer.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2c7eb152b9b0a0f7506271', 2, 'Stir together vegetable juices, water, lemon juice, 1 1/4 teaspoons sugar, horseradish, Worcestershire sauce, and black pepper in a large pot. Bring to a boil and cook until flavors blend, about 20 minutes. Meanwhile, sterilize the jar and lid in boiling water for at least 5 minutes.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2c7eb152b9b0a0f7506271', 3, 'Ladle juice into the jar. Stir 1 tablespoon sugar and salt into juice. Wipe the rim of the jar with a moist paper towel to remove any residue. Top with the lid and screw on the ring.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2c7eb152b9b0a0f7506271', 4, 'Process juice in a pressure canner at 10 pounds of pressure for 35 minutes.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2c7eb152b9b0a0f7506271', 5, 'Remove the jar from the pressure canner and place onto a cloth-covered or wooden surface until cool. Press the center of the lid with a finger to ensure the lid does not move up or down. Remove the ring for storage and store in a cool, dark area.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_643a22f0acacd5fd8d6e54', 'Ginger-Turmeric Herbal Tea', 'drink', 'This ginger turmeric tea is a tasty alternative to supplements if you have trouble including anti-inflammatory spices in your diet. I believe this tea is popular in Okinawa, Japan. Turmeric is also used for medicinal purposes in India. Remember that turmeric stains; I make this tea in an old mason jar, wrapped in an old tea towel!', 2, 5, 15, NULL, 'cocktail', 0, 1, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_643a22f0acacd5fd8d6e54', 0, 'water', 'water', 2, 'cups', 'drinks');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_643a22f0acacd5fd8d6e54', 1, 'ground turmeric', 'ground turmeric', 0, 'teaspoon', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_643a22f0acacd5fd8d6e54', 2, 'chopped fresh ginger', 'chopped fresh ginger', 0, 'teaspoon', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_643a22f0acacd5fd8d6e54', 3, 'ground cinnamon', 'ground cinnamon', 0, 'teaspoon', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_643a22f0acacd5fd8d6e54', 4, 'honey', 'honey', 1, 'tablespoon', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_643a22f0acacd5fd8d6e54', 5, 'lemon wedge', 'lemon wedge', 1, NULL, 'produce');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_643a22f0acacd5fd8d6e54', 0, 'Gather all ingredients.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_643a22f0acacd5fd8d6e54', 1, 'Bring water to a boil in a small saucepan; add turmeric, ginger, and cinnamon.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_643a22f0acacd5fd8d6e54', 2, 'Reduce heat to medium-low and simmer for 10 minutes.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_643a22f0acacd5fd8d6e54', 3, 'Strain tea into a large glass.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_643a22f0acacd5fd8d6e54', 4, 'Stir in honey and serve with lemon wedge.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_b4673f7aca9eb97cf5ab0b', 'Grateful Dead Cocktail', 'drink', 'This Grateful Dead drink made with vodka, rum, tequila, gin, and raspberry liqueur is considered the sweeter cousin of the Long Island Iced Tea. Like that drink, this cocktail packs a considerable punch!', 1, 5, 0, NULL, 'cocktail', 0, 1, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
