INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_18e8d72d7ab5e8be335ec0', 2, 'chopped mango', 'chopped mango', 2, 'cups', 'produce');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_18e8d72d7ab5e8be335ec0', 3, 'water', 'water', 1, 'cup', 'drinks');
