INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_18e8d72d7ab5e8be335ec0', 5, 'ice', 'ice', 2, 'cups', 'drinks');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_18e8d72d7ab5e8be335ec0', 0, 'To make the simple syrup: Combine sugar and water in a saucepan over medium-high heat. Bring to a boil and stir until sugar has dissolved. Remove from heat and allow to cool.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_18e8d72d7ab5e8be335ec0', 1, 'To make the mango lemonade: Combine mango and 1 cup water in a blender or food processor until smooth. Pour mango through a strainer into a pitcher. Stir in lemon juice and simple syrup. Mix well.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_18e8d72d7ab5e8be335ec0', 2, 'Add ice to the pitcher and serve.');
