INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ef9125af9869e956176701', 0, 'Heat 3/4 cup sugar and 1/2 cup water in a small saucepan over medium heat. Cook and stir until sugar has dissolved, about 2 minutes. Let cool.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ef9125af9869e956176701', 1, 'Place blackberries and remaining 2 tablespoons of sugar in a blender. Blend until smooth.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ef9125af9869e956176701', 2, 'Combine simple syrup, blended blackberries, remaining 4 cups of water, and lemon juice. Place a fine-mesh sieve over a pitcher and pour lemonade into the pitcher; discard solids. Serve over ice.');
