INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7b396f1bd94a94deee4893', 0, 'Place watermelon in a blender; blend until smooth. Pour through a fine mesh strainer to remove seeds and pulp.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7b396f1bd94a94deee4893', 1, 'Pour watermelon juice into ice cube tray; place in freezer until frozen, about 3 hours.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7b396f1bd94a94deee4893', 2, 'Place 4 cups of frozen watermelon cubes, tequila, lime juice, and sugar into a blender; pulse until smooth.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_e94bd42aa03b65fb96df34', 'Spicy Watermelon Margarita', 'drink', 'This spicy watermelon margarita is a delicious blend of fresh watermelon, tequila, and jalapeno slices for a fruity, spicy-sweet, thoroughly refreshing summer cocktail!', 1, 10, 0, NULL, 'cocktail', 0, 1, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
