INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_e94bd42aa03b65fb96df34', 5, 'orange-flavored liqueur (such as Cointreau)', 'orange-flavored liqueur such as cointreau', 0, 'fluid ounce', 'bar');
