INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_e94bd42aa03b65fb96df34', 7, 'jalapeño slice, plus more for garnish', 'jalapeo slice plus more for garnish', 1, 'thin slice', 'drinks');
