INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_e94bd42aa03b65fb96df34', 0, 'Puree watermelon in a blender. Wipe the rim of a margarita glass with a lime wedge; dip rim in salt.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_e94bd42aa03b65fb96df34', 1, 'In a cocktail shaker half-filled with ice, add tequila, orange liqueur, lime juice, jalapeño, and 2 ounces of the watermelon puree. Shake until very cold.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_e94bd42aa03b65fb96df34', 2, 'Strain into prepared glass. Garnish with watermelon wedge and jalapeño slice.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_62b0d27ce8ab01d48f6323', 'Watermelon Lemonade', 'drink', 'Watermelon lemonade is a light and refreshing summer drink made with pureed watermelon and homemade lemonade. Garnish with a watermelon slice if you like. ', 12, 10, 5, NULL, 'drink', 0, 0, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
