INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_9a3646aa67d476acf86643', 0, 'Gather all ingredients.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_9a3646aa67d476acf86643', 1, 'Combine sugar and 1 cup water in a small saucepan. Stir to dissolve sugar while mixture comes to a boil. Set aside to cool slightly.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_9a3646aa67d476acf86643', 2, 'Meanwhile, roll lemons around on your counter to soften. Cut in half crosswise, and squeeze into a liquid measuring cup. Add pulp to the juice, but discard any seeds. Continue juicing until you have 1 1/2 cups fresh juice and pulp.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_9a3646aa67d476acf86643', 3, 'Pour 7 cups ice-cold water into a pitcher. Stir in lemon juice and pulp, then add simple syrup to taste. Add ice.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_1ee2d1569d8850c32861e3', 'Pineapple Mango Coconut Smoothie', 'drink', 'Our Coconut Almond Blend gives this fruit smoothie a great tropical flavor.', 2, 5, 0, NULL, 'drink', 0, 0, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
