INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_1ee2d1569d8850c32861e3', 2, 'fresh, frozen, or juice-packed pineapple chunks', 'fresh frozen or juice-packed pineapple chunks', 1, 'cup', 'produce');
