INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ee2d1569d8850c32861e3', 0, 'Puree all ingredients in a blender until smooth.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_754b6d2fea758155c8a595', 'State Fair Lemonade', 'drink', 'This lemonade recipe is for real, authentic, vintage lemonade —the kind you might enjoy on a hot summer day at one of those stands at the state fair. Most of us make lemonade just out of lemon juice, but as you may know, the oils in the lemon peel contain a tremendous amount of flavor, and once you drink this, you won''t want to go back to drinking it how you used to.', 6, 15, 5, NULL, 'drink', 0, 0, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_754b6d2fea758155c8a595', 0, 'lemons', 'lemons', 6, NULL, 'produce');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_754b6d2fea758155c8a595', 1, 'white sugar', 'white sugar', 1, 'cups', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_754b6d2fea758155c8a595', 2, 'cold water', 'cold water', 5, 'cups', 'drinks');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_754b6d2fea758155c8a595', 0, 'Wash lemons and peel off all the zest using a vegetable peeler; set peeled lemons aside. Add lemon zest to a bowl and cover with sugar; toss to combine. Cover and let sit for a minimum of 2 hours, or up to overnight.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_754b6d2fea758155c8a595', 1, 'Bring water to a boil in a pot over high heat; turn off heat and pour in lemon-sugar mixture. Stir and let sit until sugar is completely dissolved, about 5 minutes.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_754b6d2fea758155c8a595', 2, 'Pour through a mesh strainer back into the same bowl and discard the zest. Let cool to room temperature, 20 to 30 minutes.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_754b6d2fea758155c8a595', 3, 'Cut lemons in half and squeeze juice into the bowl. Pour lemonade into a serving pitcher; cover and chill thoroughly before serving over ice, at least 2 hours.');
