INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_2fc8bdb84a943211d14368', 11, 'carbonated water (Optional)', 'carbonated water optional', 2, 'cups', 'drinks');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2fc8bdb84a943211d14368', 0, 'Gather all ingredients.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2fc8bdb84a943211d14368', 1, 'Mix red wine, brandy, triple sec, lemonade concentrate, orange juice, lemon juice, and sugar together in a bowl. Add orange, lemon and lime slices, and maraschino cherries.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2fc8bdb84a943211d14368', 2, 'Serve immediately over ice, or refrigerate 8 hours to overnight for best flavor. For a fizzy sangria, add club soda just before serving.');
