INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_978d408ed430742ffbb3c7', 0, 'Place 9 cups of watermelon cubes in a blender; blend on high until very smooth. Strain juice through a mesh strainer into a large pitcher.');
