INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_b80a7d67c5f7df75bdf489', 1, 'Run a wedge of lime along the rim of each of four pint glasses. Spread kosher salt onto a flat plate; press glass rims into salt to coat. Fill glass with ice and pour margarita over the ice. Garnish with cucumber slice.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_437cba8dd1729b892f6146', 'Pickled Jalapeño Margarita', 'drink', 'The easiest jalapeño margarita recipe you''ll ever make! It doesn''t require any muddling or infusing, just a splash of pickled jalapeño juice. It''s spicy, so a little bit of juice goes a long way. Garnish with a slice of fresh jalapeño if you like.', 1, 5, 0, NULL, 'cocktail', 0, 1, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
