INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_1d2e634c9a1aa31323bf47', 'Hurricane Cocktail', 'drink', 'The ingredients in this hurricane cocktail include rum, passion fruit, and lime. It''s a sweet, boozy concoction popular in America''s favorite party town: New Orleans.', 1, 5, 0, NULL, 'cocktail', 0, 1, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
