INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7eda7819399faccc441699', 0, 'Mix strawberries and 1/4 cup sugar together in a bowl; set aside for juices to release from strawberries, 5 to 10 minutes.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7eda7819399faccc441699', 1, 'Bring 1 cup water to a boil in a small saucepan; add 3/4 cup sugar. Cook and stir sugar mixture until sugar is dissolved, about 5 minutes. Remove saucepan from heat and cool simple syrup to room temperature.');
