INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_5dfc017b58675928491d9b', 'Classic Frozen Strawberry Margarita', 'drink', 'This strawberry margarita recipe is easy to make at home with fresh strawberries, lime juice, tequila, and triple sec blended with ice for a fruity and refreshing variation on a classic frozen margarita. Perfect for summer parties!', 1, 10, 0, NULL, 'cocktail', 0, 1, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
