INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_2f43965e3a133af752cefc', 'The Perfect Margarita', 'drink', 'This is the best margarita recipe I know! It has the perfect ratio of white tequila, high-quality triple sec, and freshly squeezed lime juice for the best-tasting margarita every time. ', 1, 10, 0, NULL, 'cocktail', 0, 1, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
