INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2f43965e3a133af752cefc', 1, 'Moisten the rim of a glass with a lime wedge. Sprinkle salt onto a plate. Lightly dip the moistened rim into the salt.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2f43965e3a133af752cefc', 2, 'Place a large ice cube in the glass and freeze the prepared glass until ready to serve.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2f43965e3a133af752cefc', 3, 'Fill a cocktail shaker with fresh ice. Add tequila, triple sec, and lime juice. Cover and shake vigorously until the outside of the shaker has frosted.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2f43965e3a133af752cefc', 4, 'Strain margarita into the chilled glass and garnish with a slice of lime.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_2cce32452de4739f097d5d', 'Pineapple Margarita', 'drink', 'This pineapple margarita gives a traditional margarita a tropical twist! Garnish with a pineapple wedge for a fun, fruity cocktail. ', 1, 5, 0, NULL, 'cocktail', 0, 1, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
