INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_2cce32452de4739f097d5d', 6, '2 lime wedges', '2 lime wedges', 0, NULL, 'produce');
