INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2cce32452de4739f097d5d', 0, 'Fill a cocktail shaker half-full with ice. Add pineapple juice, tequila, triple sec, and lime juice to the shaker. Seal and shake vigorously until outside is frosted, 10 to 15 seconds.');
