INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_625bfc9f3c8a5630bcdfe0', 'Strawberry Basil Margarita', 'drink', 'I created this strawberry basil margarita one night to use up some summer strawberries and some of my basil. What a refreshing and delicious summer drink. Try it and see!', 2, 5, 0, NULL, 'cocktail', 0, 1, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
