INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_52c9a64f2ca205f1e4db34', 3, 'vanilla ice cream', 'vanilla ice cream', 8, 'scoops', 'dairy');
