INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_52c9a64f2ca205f1e4db34', 0, 'Stir drink mix, lemon-lime soda, and white cranberry juice together in a large punch bowl. Taste, and stir in sugar to your liking.');
