INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_115752661d5959f7398c75', 'Party Punch', 'drink', 'Guests love this party punch that''s easy to make with fruit punch, orange juice, and ginger ale. We love to make this delicious drink for family gatherings — my sisters, brother, and I even had it served at our weddings! Add sliced fruit if desired.', 24, 5, 0, NULL, 'drink', 0, 0, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_115752661d5959f7398c75', 0, 'fruit punch, chilled', 'fruit punch chilled', 1, '(2 liter) bottle', 'bar');
