INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_115752661d5959f7398c75', 1, 'Combine fruit punch and orange juice in a punch bowl.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_115752661d5959f7398c75', 2, 'Slowly pour ginger ale down the side of the bowl to retain carbonation.');
