INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_299a66a9b08561225c5e4e', 'Shower Sherbet Punch', 'drink', 'This refreshing sherbet punch recipe is great for bridal and baby showers. You just can''t get enough! It''s a very versatile recipe —use different flavors such as lemon-lime, orange, strawberry, or even a combo.', 15, 5, 0, NULL, 'drink', 0, 0, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
