INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_869b0753ec45e27386127f', 1, 'frozen banana, peeled and chopped', 'frozen banana peeled and chopped', 1, 'unknown', 'produce');
