INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_24eb44cc14e78b4e83b9c0', 0, 'Pour cream and half-and-half into an electric blender and blend on low speed until it begins to thicken. Add sugar and vanilla extract and mix for about 30 seconds. Add blueberries, strawberries, raspberries, and blackberries. Blend until smooth, adding milk if necessary to make blending easier.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_6e1c7e74ccfd85a2b42956', 'Fresh, Homemade Apple Juice', 'drink', 'This apple juice recipe is super easy and requires no juicer! My mother had this creative way of using the leftover apple cores and peels (from baking pies) to make homemade apple juice. To anyone with a sensitive palate, the distinct and almost bitter taste of store-bought apple juice can be a little strong at times. This homemade juice is lighter and pleasantly sweet without the kick. ', 5, 10, 35, NULL, 'drink', 0, 0, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_6e1c7e74ccfd85a2b42956', 0, 'water', 'water', 5, 'cups', 'drinks');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_6e1c7e74ccfd85a2b42956', 1, 'peels and cores from red apples - seeds removed', 'peels and cores from red apples - seeds removed', 3, NULL, 'produce');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_6e1c7e74ccfd85a2b42956', 2, 'white sugar', 'white sugar', 0, 'cup', 'pantry');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6e1c7e74ccfd85a2b42956', 0, 'Gather all ingredients.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6e1c7e74ccfd85a2b42956', 1, 'Combine water with apple peels and cores in a saucepan. Bring to a boil, then reduce the heat and simmer, stirring occasionally, until the apple flavor and color have permeated the water, about 30 minutes.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6e1c7e74ccfd85a2b42956', 2, 'Strain apple juice into a mixing bowl; discard all solids. Stir in sugar until dissolved. Allow to cool for 30 minutes before drinking.');
