INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fc6a4b5f0ed05fad088918', 0, 'To each pound of fruit free from stalks allow half a pound of sifted sugar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fc6a4b5f0ed05fad088918', 1, 'Mash the fruit well');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fc6a4b5f0ed05fad088918', 2, 'Place in a skillet and add to each pound of fruit three-quarters of a pint of water');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fc6a4b5f0ed05fad088918', 3, 'Simmer gently for half an hour');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fc6a4b5f0ed05fad088918', 4, 'Strain through a jelly bag');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fc6a4b5f0ed05fad088918', 5, 'Bottle');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fc6a4b5f0ed05fad088918', 6, 'If required to be kept for any length of time, a wineglass of brandy to each quart of syrup must be added to prevent fermentation');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fc6a4b5f0ed05fad088918', 7, 'All fruit drinks are improved by the addition of a small quantity of lemon juice');
