INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5eeb2aa54eeff4665c7420', 0, 'Put ginger, lemon peel and juice, cream of tartar, loaf sugar, and syrup of ginger into a large pan');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5eeb2aa54eeff4665c7420', 1, 'Add boiling water and stir well');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5eeb2aa54eeff4665c7420', 2, 'When cool add yeast spread upon a piece of toasted bread');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5eeb2aa54eeff4665c7420', 3, 'Stir well, cover with a cloth, and leave in a warm place for twenty-four hours');
