INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5eeb2aa54eeff4665c7420', 6, 'Store in a cool place');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5eeb2aa54eeff4665c7420', 7, 'It will be ready for use in three or four days');
