INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a17d8684440c1faf028db8', 2, 'Strain through a bag or sieve');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a17d8684440c1faf028db8', 3, 'Sweeten with icing sugar to taste');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a17d8684440c1faf028db8', 4, 'This drink is very refreshing when quite cold');
