INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0eeb1f4bf98156fb2e7fb6', 0, 'Put lemon juice, lemon rind, sugar, pineapple, cloves, coriander seeds, and cinnamon into a clean pitcher');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0eeb1f4bf98156fb2e7fb6', 1, 'Add brandy, rum, arrack, and green tea');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0eeb1f4bf98156fb2e7fb6', 2, 'Add boiling water last');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0eeb1f4bf98156fb2e7fb6', 3, 'Cork down to prevent evaporation');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0eeb1f4bf98156fb2e7fb6', 4, 'Allow to steep for at least six hours');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0eeb1f4bf98156fb2e7fb6', 5, 'Add a quart of hot milk and juice of two lemons');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0eeb1f4bf98156fb2e7fb6', 6, 'Mix and filter through a jelly-bag');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0eeb1f4bf98156fb2e7fb6', 7, 'When punch has passed bright, put it away in tight-corked bottles');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0eeb1f4bf98156fb2e7fb6', 8, 'Ice for drinking');
