INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_6c431b18022dc2492c170b', 3, 'Cognac brandy', 'cognac brandy', 1, 'pint', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_6c431b18022dc2492c170b', 4, 'Jamaica rum', 'jamaica rum', 1, 'pint', 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6c431b18022dc2492c170b', 0, 'Select three dozen lemons with smooth coats and not too thin rinds');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6c431b18022dc2492c170b', 1, 'Peel lemons with sharp knife into large earthen vessel, preserving cells with essential oil');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6c431b18022dc2492c170b', 2, 'Add two pounds of lump sugar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6c431b18022dc2492c170b', 3, 'Stir peel and sugar together with oar-shaped wood for nearly half an hour');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6c431b18022dc2492c170b', 4, 'Pour boiling water into vessel and stir well until sugar completely dissolved');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6c431b18022dc2492c170b', 5, 'Cut and squeeze lemons, strain juice from kernels');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6c431b18022dc2492c170b', 6, 'Place kernels in separate jug and pour boiling water upon them');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6c431b18022dc2492c170b', 7, 'Strain liquid and add');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6c431b18022dc2492c170b', 8, 'Throw in half the lemon juice');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6c431b18022dc2492c170b', 9, 'When kernels are free from transparent coating, strain and add their liquor');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6c431b18022dc2492c170b', 10, 'Taste sherbet and apply more acid or sugar as required');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6c431b18022dc2492c170b', 11, 'Measure sherbet and add to every three quarts one pint Cognac brandy and one pint Jamaica rum');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6c431b18022dc2492c170b', 12, 'Stir spirit in well');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6c431b18022dc2492c170b', 13, 'Bottle immediately');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6c431b18022dc2492c170b', 14, 'Keep in cold cellar or tank until required');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_5c890c9338ea5ac5201d95', 'Punch Jelly', 'cocktail', 'Orange, lemon, or calf''s-foot jelly can be converted into punch jelly by omitting a portion of acid. Agreeable refreshment on a cold night, but should be used in moderation', 1, 3, 0, NULL, 'mocktail', 1, 0, 1862, 'The bar-tenders'' guide :', NULL, NULL, NULL, NULL, NULL, NULL, 'rocks', 'built', NULL, NULL, 'unreviewed');
