INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5c890c9338ea5ac5201d95', 0, 'Make a good bowl of punch a la Ford');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5c890c9338ea5ac5201d95', 1, 'Dissolve isinglass in a quarter pint of water');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5c890c9338ea5ac5201d95', 2, 'To every pint of punch add the isinglass mixture');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5c890c9338ea5ac5201d95', 3, 'Pour into punch whilst quite hot');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5c890c9338ea5ac5201d95', 4, 'Fill moulds, taking care that they are not disturbed until jelly is completely set');
