INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7548ac8de44165ac2e4e5c', 1, 'This is sherbet, and must be well mingled');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7548ac8de44165ac2e4e5c', 2, 'Add old Jamaica rum in one part rum to five of sherbet');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7548ac8de44165ac2e4e5c', 3, 'Cut a couple of limes in two');
