INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5237f3b8c83d998d0eb6a6', 0, 'Thinly peel lemons and place rind in bowl with sugar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5237f3b8c83d998d0eb6a6', 1, 'Macerate well for a minute or two to extract flavor');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5237f3b8c83d998d0eb6a6', 2, 'Squeeze juice of lemons onto this');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5237f3b8c83d998d0eb6a6', 3, 'Add two bottles soda-water and stir well until sugar dissolves');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5237f3b8c83d998d0eb6a6', 4, 'Pour in syrup of orgeat');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5237f3b8c83d998d0eb6a6', 5, 'Whip mixture well with egg-whisk to whiten composition');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5237f3b8c83d998d0eb6a6', 6, 'Add brandy, rum and maraschino');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5237f3b8c83d998d0eb6a6', 7, 'Strain whole into punch-bowl');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5237f3b8c83d998d0eb6a6', 8, 'Just before serving add champagne which should be well iced');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5237f3b8c83d998d0eb6a6', 9, 'While adding champagne, stir well with ladle to make creamy and mellow');
