INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ffbbde10f56c99104a9288', 0, 'Grind all substantial articles');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ffbbde10f56c99104a9288', 1, 'Add 6 gallons of water at 144 degrees Fahrenheit');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ffbbde10f56c99104a9288', 2, 'Stir well, let stand for 1.5 hours');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ffbbde10f56c99104a9288', 3, 'Draw off the liquor');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ffbbde10f56c99104a9288', 4, 'Repeat the same operation with 3 gallons for the 2nd and 3rd time');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ffbbde10f56c99104a9288', 5, 'Mix the liquors and boil');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ffbbde10f56c99104a9288', 6, 'Clarify with the white of 1 or 2 eggs');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ffbbde10f56c99104a9288', 7, 'Cool as quickly as possible to 50 degrees Fahrenheit');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ffbbde10f56c99104a9288', 8, 'Add 0.5 lb of yeast');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ffbbde10f56c99104a9288', 9, 'Fill up in casks when fermentation is over');
