INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_785695758170d8bf4216a4', 1, 'Peel the 2 lemons, which you must add to the mixture, and squeeze in the juice');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_785695758170d8bf4216a4', 2, 'Break the sugar; dissolve it in water, and put it into the jar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_785695758170d8bf4216a4', 3, 'Let it stand for a fortnight');
