INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2678bfd811724192966fba', 0, 'Macerate 3 ounces of sliced pineapple, 6 grains of vanilla, 1 grain of ambergris (rubbed with a little sugar) in 1 pint of the strongest pale brandy for a few hours');
