INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2678bfd811724192966fba', 2, 'Strain through a jelly bag, squeezing the bag so as to get all the liquid');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2678bfd811724192966fba', 3, 'Add 1 pint of lemon juice, 1 bottle of lemon syrup, 1 bottle of claret or port wine, and 0.5 lb of sugar dissolved in 1.5 pint of boiling water');
