INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d3aeeec5ca9db6e57d0be0', 3, 'Add four pounds of loaf-sugar, and five cloves and two leaves of mace tied up in a piece of linen, likewise two quarts of water');
