INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d3aeeec5ca9db6e57d0be0', 5, 'Skim well, fill into bottles, and keep for the punch');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d3aeeec5ca9db6e57d0be0', 6, 'Mix three-fourths of a quart of green tea, one pint of cognac, one quart of old Jamaica rum, one bottle of champagne, and a cup of chartreuse well sweetened to taste with the syrup');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d3aeeec5ca9db6e57d0be0', 7, 'Pour it into a punch-bowl');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d3aeeec5ca9db6e57d0be0', 8, 'Add a big lump of ice, three oranges cut in slices, and three lemons without the seeds');
