INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_08c7c1723a94ab488287ab', 0, 'Choisissez les raisins rouges de meilleure qualité, les plus mûrs');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_08c7c1723a94ab488287ab', 1, 'Faites-les couler dans un fouloir en ajoutant du sucre');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_08c7c1723a94ab488287ab', 2, 'Cueillez le raisin Souzac et Touriga bien mûr');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_08c7c1723a94ab488287ab', 3, 'Foulez-le légèrement et séparez la rafle');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_08c7c1723a94ab488287ab', 4, 'Jetez le liquide et les pellicules dans des grands baquets');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_08c7c1723a94ab488287ab', 5, 'Foulez tout très-bien avec les pieds');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_08c7c1723a94ab488287ab', 6, 'Ajoutez la cassonade (30 kg pour 3 pipes)');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_08c7c1723a94ab488287ab', 7, 'Lorsque le premier vin est fait, décuvez-le et mêlez les deux ensemble');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_08c7c1723a94ab488287ab', 8, 'Au mois de décembre, ajoutez peu à peu de l''alcool à 32° Cartier jusqu''à 25 litres par pipe, en différents jours');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_08c7c1723a94ab488287ab', 9, 'Quand l''esprit se combine avec le vin (au mois de mai), soutirez le vin');
