INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_4ad3b9b7e2314078884397', 0, 'Choisissez le muscat cultivé dans les terrains plats convenables, bien mûr');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_4ad3b9b7e2314078884397', 1, 'Ôtez la plupart des feuilles');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_4ad3b9b7e2314078884397', 2, 'Laissez les ceps exposés au soleil quelques jours');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_4ad3b9b7e2314078884397', 3, 'Laissez le raisin se faner');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_4ad3b9b7e2314078884397', 4, 'Cueillez-le et foulez-le légèrement');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_4ad3b9b7e2314078884397', 5, 'Ôtez la rafle');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_4ad3b9b7e2314078884397', 6, 'Jetez le liquide et ses pellicules dans une cuve');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_4ad3b9b7e2314078884397', 7, 'Laissez fermenter très-peu pour conserver le bouquet');
