INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_dec698977fa66ddb661899', 3, 'Put berries into open vessel and cover with liquid');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_dec698977fa66ddb661899', 4, 'Infuse for seven or eight days');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_dec698977fa66ddb661899', 5, 'Press out liquor and keep separately or combine as desired');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_dec698977fa66ddb661899', 6, 'Put juice into appropriate cask');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_dec698977fa66ddb661899', 7, 'Add 1 gallon of malt spirits to every 20 gallons of elder juice to preserve');
