INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ea43e5eef0a6dffd8ec80', 0, 'Mettre tous ingrédients ensemble');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ea43e5eef0a6dffd8ec80', 1, 'Bien remuer avec cuillere ou bâton');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ea43e5eef0a6dffd8ec80', 2, 'Passer dans chausse bien nette');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ea43e5eef0a6dffd8ec80', 3, 'Continuer de passer jusqu''à devenir clair');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ea43e5eef0a6dffd8ec80', 4, 'Passer peu à peu pour clarifier plus vite');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ea43e5eef0a6dffd8ec80', 5, 'Quand bien clair et transparent, faire couler sur cruche ou vaisseau');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ea43e5eef0a6dffd8ec80', 6, 'Couvrir embouchure d''étamine, linge ou autre');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ea43e5eef0a6dffd8ec80', 7, 'Enfoncer dans milieu d''embouchure');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ea43e5eef0a6dffd8ec80', 8, 'Jeter poudre de musc et ambre sur étamine en passant');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ea43e5eef0a6dffd8ec80', 9, 'Garder ainsi 1 an et plus sans corruption');
