INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2e085c2ab1bc0b2fe58fd1', 0, 'Bien écrafer fruits ensemble ou l''un après l''autre');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2e085c2ab1bc0b2fe58fd1', 1, 'Presser et passer au travers d''un gros tamis');
