INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_ed3a69f2f3d4c0babbcf15', 0, 'Eau de pluie', 'eau de pluie', 24, 'pintes', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_ed3a69f2f3d4c0babbcf15', 1, 'Miel', 'miel', 3, 'pintes', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_ed3a69f2f3d4c0babbcf15', 2, 'Racine d''Angelique concassée', 'racine dangelique concasse', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_ed3a69f2f3d4c0babbcf15', 3, 'Grains de Moutarde concassés', 'grains de moutarde concasss', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ed3a69f2f3d4c0babbcf15', 0, 'Faire bouillir l''eau et le miel ensemble dans une chaudière de cuivre sur petit feu de charbon, en remuant continuellement de crainte qu''il ne brûle au fond');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ed3a69f2f3d4c0babbcf15', 1, 'Écumer proprement');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ed3a69f2f3d4c0babbcf15', 2, 'Tester la cuisson avec un œuf frais: il doit flotter sur le côté pour indiquer la parfaite cuisson');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ed3a69f2f3d4c0babbcf15', 3, 'Verser à travers un linge dans des vaisseaux de bois de chêne neufs');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ed3a69f2f3d4c0babbcf15', 4, 'Descendre un linge clair ou étamine cousu en forme de boyau contenant racine d''angelique concassée et grains de moutarde concassés (1/100 de la quantité d''hydromel)');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ed3a69f2f3d4c0babbcf15', 5, 'Exposer au grand soleil pendant les jours caniculaires, laissant la bonde ouverte');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ed3a69f2f3d4c0babbcf15', 6, 'Laisser bouillir une seconde fois au soleil');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ed3a69f2f3d4c0babbcf15', 7, 'Retirer le linge et bondonner bien le vaisseau');
