INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_c7095b6c3baac92b1a0521', 0, 'Make several incisions in the rind of a lemon and stick cloves in the incisions');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_c7095b6c3baac92b1a0521', 1, 'Roast the lemon by a slow fire');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_c7095b6c3baac92b1a0521', 2, 'Put small but equal quantities of cinnamon, cloves, mace, all-spice, and a race of ginger into a saucepan with half a pint of water');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_c7095b6c3baac92b1a0521', 3, 'Let it boil until reduced one half');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_c7095b6c3baac92b1a0521', 4, 'Boil one bottle of port wine and burn a portion of the spirit out of it by applying a lighted paper to the saucepan');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_c7095b6c3baac92b1a0521', 5, 'Put the roasted lemons and spice into the wine');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_c7095b6c3baac92b1a0521', 6, 'Stir it up well and let it stand near the fire ten minutes');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_c7095b6c3baac92b1a0521', 7, 'Rub a few knobs of sugar on the rind of a lemon and put the sugar into a bowl');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_c7095b6c3baac92b1a0521', 8, 'Add the juice of half a lemon to the sugar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_c7095b6c3baac92b1a0521', 9, 'Pour the wine upon it, grate some nutmeg into it, sweeten it to your taste, and serve it up with the lemon and spice floating in it');
