INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_4d812d75ff96c9f65fe0ab', 0, 'Extract the juice from the peeling of one lemon by rubbing loaf sugar on it, or cut the peeling extremely thin and pound it in a mortar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_4d812d75ff96c9f65fe0ab', 1, 'Cut two lemons into thin slices');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_4d812d75ff96c9f65fe0ab', 2, 'Put the whole into a jug with four glasses of calves-feet jelly in a liquid state and small quantities of cinnamon, mace, cloves, and all-spice');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_4d812d75ff96c9f65fe0ab', 3, 'Pour one quart of boiling water upon it');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_4d812d75ff96c9f65fe0ab', 4, 'Cover the jug close and let it stand a quarter of an hour');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_4d812d75ff96c9f65fe0ab', 5, 'Add one bottle of boiling hot white wine');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_4d812d75ff96c9f65fe0ab', 6, 'Grate half a nutmeg into it');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_4d812d75ff96c9f65fe0ab', 7, 'Stir it well together, sweeten it to your taste');
