INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_716f757a4efdd00a4123fb', 1, 'Let the mixture stand until it is quite cold');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_716f757a4efdd00a4123fb', 2, 'Pour a bottle of white wine into it');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_716f757a4efdd00a4123fb', 3, 'In summer season, place in a tub of ice');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_716f757a4efdd00a4123fb', 4, 'Make the Negus somewhat sweeter, as extreme cold detracts from the sweetness of liquors');
