INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_761d64f2bd68c9b89a760c', 0, 'Extract the juice from the rind of three lemons by rubbing loaf sugar on it');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_761d64f2bd68c9b89a760c', 1, 'Cut the peeling of two Seville oranges and two lemons extremely thin');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_761d64f2bd68c9b89a760c', 2, 'Extract the juice of four Seville oranges and ten lemons');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_761d64f2bd68c9b89a760c', 3, 'Put the above into a jug with six glasses of calves-feet jelly in a liquid state and stir well together');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_761d64f2bd68c9b89a760c', 4, 'Pour two quarts of boiling water on the mixture');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_761d64f2bd68c9b89a760c', 5, 'Cover the jug closely and place it near the fire for a quarter of an hour');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_761d64f2bd68c9b89a760c', 6, 'Strain the liquid through a sieve into a punch bowl or jug');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_761d64f2bd68c9b89a760c', 7, 'Sweeten it with a bottle of capillaire');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_761d64f2bd68c9b89a760c', 8, 'Add half a pint of white wine, a pint of French brandy, a pint of Jamaica rum, and a bottle of orange shrub');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_761d64f2bd68c9b89a760c', 9, 'Stir the mixture as the spirits are poured in');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_761d64f2bd68c9b89a760c', 10, 'Add loaf sugar gradually in small quantities if not sufficiently sweet, or a spoonful or two of capillaire');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_761d64f2bd68c9b89a760c', 11, 'Serve up either hot or cold');
