INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_3f715d6c1b6d82d9c42e65', 3, 'Pour into it gradually half a pint of lemon juice, stirring the mixture as it is poured in');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_3f715d6c1b6d82d9c42e65', 4, 'Add one quart of white brandy');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_3f715d6c1b6d82d9c42e65', 5, 'Strain it through a flannel bag or a fine hair sieve');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_3f715d6c1b6d82d9c42e65', 6, 'Bottle it off and if placed in a cool cellar it will keep ten days or a fortnight');
