INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a36e0449a005ad9d660cca', 0, 'Dissolve two pounds and a half of double refined sugar in one gallon of cold spring water');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a36e0449a005ad9d660cca', 1, 'Add to it a quarter of a pint of orange flower water');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a36e0449a005ad9d660cca', 2, 'Add the juice of twenty limes and eight pot oranges');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a36e0449a005ad9d660cca', 3, 'Stir it well together');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a36e0449a005ad9d660cca', 4, 'Pour one quart of boiling milk into it');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a36e0449a005ad9d660cca', 5, 'Add three quarts of white brandy and three quarts of orange brandy shrub');
