INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d8dbbd30298bae96049c8b', 0, 'Cut the peeling of six Seville oranges and six lemons extremely thin');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d8dbbd30298bae96049c8b', 1, 'Pound it in a stone mortar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d8dbbd30298bae96049c8b', 2, 'Add thereto a pint of brandy and let it remain about six hours');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d8dbbd30298bae96049c8b', 3, 'Squeeze the juice of six Seville oranges and eight lemons into it');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d8dbbd30298bae96049c8b', 4, 'Stir it well and pour into it three more pints of brandy, three pints of rum, and three quarts of water');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d8dbbd30298bae96049c8b', 5, 'Make two quarts of skimmed milk boiling hot');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d8dbbd30298bae96049c8b', 6, 'Grate a nutmeg into it');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d8dbbd30298bae96049c8b', 7, 'Mix it gradually with the other ingredients');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d8dbbd30298bae96049c8b', 8, 'Add a sufficient quantity of fine loaf sugar to sweeten it, (about two pounds)');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d8dbbd30298bae96049c8b', 9, 'Stir it till the sugar is dissolved');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d8dbbd30298bae96049c8b', 10, 'Let the mixture stand twelve hours, then strain it through a flannel bag till it is quite clear');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d8dbbd30298bae96049c8b', 11, 'Bottle off and well cork; it will keep in any climate and for any length of time');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d8dbbd30298bae96049c8b', 12, 'The bottles must be perfectly dry');
