INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_101035bbca2948a37ecb2c', 0, 'Extract the juice from the peeling of one Seville orange and one lemon');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_101035bbca2948a37ecb2c', 1, 'Extract the juice of six Seville oranges and six lemons');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_101035bbca2948a37ecb2c', 2, 'Prepare with six glasses of calves-feet jelly in a liquid state and a sufficient quantity of loaf sugar, (about half a pound)');
