INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a4ad32ead19946cfb4331b', 0, 'Cut the rind off six lemons if large, eight if small');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a4ad32ead19946cfb4331b', 1, 'Squeeze out the juice and put the rind and the juice together');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a4ad32ead19946cfb4331b', 2, 'Add one quart of white brandy');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a4ad32ead19946cfb4331b', 3, 'Let it remain closely covered for three or four days');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a4ad32ead19946cfb4331b', 4, 'Squeeze the juice of six or eight additional lemons into two quarts of water');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a4ad32ead19946cfb4331b', 5, 'Put into it a sufficient quantity of double refined sugar to sweeten the whole');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a4ad32ead19946cfb4331b', 6, 'Boil it well and when quite cold, pour into it a bottle of sherry or madeira');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a4ad32ead19946cfb4331b', 7, 'Mix it well with the lemon and brandy');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a4ad32ead19946cfb4331b', 8, 'If sufficiently sweet, strain it through a flannel bag into a small cask');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a4ad32ead19946cfb4331b', 9, 'At the expiration of three months bottle it off');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a4ad32ead19946cfb4331b', 10, 'If the bottles are well corked and kept in a cool place, it will be fit to drink in a month');
