INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8dcf38c869af2402e2c4eb', 0, 'Combine one quart of cold water, the juice of six lemons and six pot oranges, and four glasses of calves-feet jelly in a liquid state');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8dcf38c869af2402e2c4eb', 1, 'Stir the whole well together');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8dcf38c869af2402e2c4eb', 2, 'Let it remain covered over for half an hour');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8dcf38c869af2402e2c4eb', 3, 'Strain it through a hair sieve');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8dcf38c869af2402e2c4eb', 4, 'Add to it one bottle of capillaire, two glasses of sherry, half a pint of brandy, and one bottle of orange shrub');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8dcf38c869af2402e2c4eb', 5, 'Put some pulverised sugar and ten fresh-laid hens'' eggs into a bowl');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8dcf38c869af2402e2c4eb', 6, 'Beat them well together');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8dcf38c869af2402e2c4eb', 7, 'Gradually unite the two mixtures by keeping the eggs well stirred as it is poured in');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8dcf38c869af2402e2c4eb', 8, 'Whip it with a whisk until a fine froth rises');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8dcf38c869af2402e2c4eb', 9, 'If sweet enough it is fit for immediate use');
