INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1d7ba851687a25c5d7317f', 0, 'Mix five drams of oil of nutmegs, five drams of oil of cassia, and three drams of oil of caraway in a quart of strong spirits of wine.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1d7ba851687a25c5d7317f', 1, 'Shake it well, and put it into a ten gallon cask with two gallons more of spirits of wine.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1d7ba851687a25c5d7317f', 2, 'Dissolve twenty pounds of lump sugar in hot water.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1d7ba851687a25c5d7317f', 3, 'Add the sugar solution to the spirit with a quarter of a pint of colouring, and fill up the cask with water.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1d7ba851687a25c5d7317f', 4, 'Fine it down with two ounces of alum dissolved in boiling water, and put into the goods hot.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1d7ba851687a25c5d7317f', 5, 'Add one ounce of salts of tartar, and stir the whole well together.');
