INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_352b27066714e4b4ee4d89', 0, 'Place a quart of strong ale or beer in a large bowl');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_352b27066714e4b4ee4d89', 1, 'Grate a little nutmeg into the bowl');
