INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_0e48d24116afd048db10e7', 'Koumiss from Cow''s Milk (Polubensky Method)', 'cocktail', 'Fermented cow''s milk preparation following Dr. Polubensky''s method', 1, 3, 0, NULL, 'mocktail', 1, 0, 1892, '1892 Drinks of the world.pdf', NULL, NULL, NULL, NULL, NULL, NULL, 'rocks', 'built', NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_0e48d24116afd048db10e7', 0, 'Fermented cow''s or mare''s milk, five days old', 'fermented cows or mares milk five days old', 1, 'bottle', 'dairy');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_0e48d24116afd048db10e7', 1, 'Warm milk at 90°F', 'warm milk at 90f', 1.5, 'tumbler', 'dairy');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_0e48d24116afd048db10e7', 2, 'Cane sugar', 'cane sugar', 0.5, 'ounce', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_0e48d24116afd048db10e7', 3, 'Skimmed cow''s milk', 'skimmed cows milk', 1, 'bottle', 'dairy');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0e48d24116afd048db10e7', 0, 'Pour a bottle of fermented cow''s or mare''s milk five days old into an oak churn');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0e48d24116afd048db10e7', 1, 'Add a tumbler and a half of warm milk (90°F) in which half an ounce of cane sugar has been dissolved');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0e48d24116afd048db10e7', 2, 'Add a bottle of skimmed cow''s milk');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0e48d24116afd048db10e7', 3, 'Beat the mixture for half an hour to prevent curdling');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0e48d24116afd048db10e7', 4, 'Let stand for three hours at room temperature (60°F)');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0e48d24116afd048db10e7', 5, 'Agitate for half an hour when a film appears on the surface');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0e48d24116afd048db10e7', 6, 'Add another bottle of skim milk and churn for an hour and a half until casein is well divided');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0e48d24116afd048db10e7', 7, 'Let stand for half an hour, add a fresh bottle of milk, and stir with short intervals until ready');
