INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_35178a72a10b4d390670d7', 0, 'Mettre l''eau dans une cafetière');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_35178a72a10b4d390670d7', 1, 'Faire bouillir l''eau sur un feu vif sans flamme');
