INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_18c222559e77cf307da304', 0, 'Quand l''eau vient à bouillir, jeter une pincée des quatre semences froides');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_18c222559e77cf307da304', 1, 'Faire prendre à l''eau sept ou huit bouillons');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_18c222559e77cf307da304', 2, 'Jeter le thé');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_18c222559e77cf307da304', 3, 'L''achever de même qu''avant');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_18c222559e77cf307da304', 4, 'Au lieu de sucre pour le prendre, mettre dans les tasses un peu de miel de Narbonne');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_18c222559e77cf307da304', 5, 'Cela ne vous échauffera point et est souverain pour la goutte et autres indispositions');
