INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_601be741688b3347e57a42', 0, 'Chocolat râpé ou découpé', 'chocolat rp ou dcoup', 0.67, 'once par prises', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_601be741688b3347e57a42', 1, 'Sucre', 'sucre', 0.67, 'once par prises', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_601be741688b3347e57a42', 2, 'Eau', 'eau', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_601be741688b3347e57a42', 0, 'Mettre de l''eau à proportion des prises qu''on veut faire dans une chocolatière');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_601be741688b3347e57a42', 1, 'Mettre sur le feu');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_601be741688b3347e57a42', 2, 'Dès que l''eau commence à bouillir, ajouter les deux tiers d''une once de chocolat râpé ou découpé et pareille quantité de sucre');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_601be741688b3347e57a42', 3, 'Laisser bouillir environ un demi-quart d''heure');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_601be741688b3347e57a42', 4, 'Remuer avec le moulinet dès qu''on a mis le chocolat et le sucre');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_601be741688b3347e57a42', 5, 'Le moulinet est une petite masse de bois dont la tête est diversement découpée et dentelée');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_601be741688b3347e57a42', 6, 'Après avoir retiré la chocolatière du feu, continuer à remuer jusqu''à bien faire mousser');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_601be741688b3347e57a42', 7, 'Verser la mousse dans le gobelet ou tasse d''abord');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_601be741688b3347e57a42', 8, 'Compléter avec le reste de la décoction');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_601be741688b3347e57a42', 9, 'Recommencer à remuer pour faire venir nouvelle mousse et remplir les autres tasses');
