INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_276dabe99dbb31ece47293', 0, 'Make several incisions in the rind of a lemon and stick cloves in the incisions');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_276dabe99dbb31ece47293', 1, 'Roast the lemon by a slow fire');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_276dabe99dbb31ece47293', 2, 'Put small but equal quantities of cinnamon, cloves, mace, and all-spice, and a race of ginger into a saucepan with half a pint of water');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_276dabe99dbb31ece47293', 3, 'Let it boil until reduced one half');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_276dabe99dbb31ece47293', 4, 'Boil one bottle of port wine and burn a portion of the spirit out of it by applying a lighted paper to the saucepan');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_276dabe99dbb31ece47293', 5, 'Put the roasted lemons and spice into the wine');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_276dabe99dbb31ece47293', 6, 'Stir it up well and let it stand near the fire ten minutes');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_276dabe99dbb31ece47293', 7, 'Rub a few knobs of sugar on the rind of a lemon and put the sugar into a bowl or jug with the juice of half a lemon');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_276dabe99dbb31ece47293', 8, 'Pour the wine upon it, grate some nutmeg into it, sweeten to taste, and serve with the lemon and spice floating in it');
