INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1c8f263f34c419e9349d34', 1, 'Cut the peeling of two Seville oranges and two lemons extremely thin');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1c8f263f34c419e9349d34', 2, 'Extract the juice of four Seville oranges and ten lemons');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1c8f263f34c419e9349d34', 3, 'Put the above into a jug with six glasses of calves-feet jelly in liquid state and stir well together');
