INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1c8f263f34c419e9349d34', 7, 'Sweeten it with a bottle of capillaire');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1c8f263f34c419e9349d34', 8, 'Add half a pint of white wine, a pint of French brandy, a pint of Jamaica rum, and a bottle of orange shrub');
