INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_e4ef28a3517b1a94165a32', 0, 'Dissolve two pounds and a half of double refined sugar in one gallon of cold spring water');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_e4ef28a3517b1a94165a32', 1, 'Add to it a quarter of a pint of orange flower water');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_e4ef28a3517b1a94165a32', 2, 'Add the juice of twenty limes and eight pot oranges');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_e4ef28a3517b1a94165a32', 3, 'Stir it well together');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_e4ef28a3517b1a94165a32', 4, 'Pour one quart of boiling milk into it');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_e4ef28a3517b1a94165a32', 5, 'Add three quarts of white brandy and three quarts of orange brandy shrub');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_e4ef28a3517b1a94165a32', 6, 'Strain it through a flannel bag or fine hair sieve');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_e4ef28a3517b1a94165a32', 7, 'Take out what is wanted for present use and bottle off the remainder');
