INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2b3ba906392de604d2ff70', 0, 'Cut the peeling of six Seville oranges and six lemons extremely thin');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2b3ba906392de604d2ff70', 1, 'Pound it in a stone mortar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2b3ba906392de604d2ff70', 2, 'Add thereto a pint of brandy and let it remain about six hours');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2b3ba906392de604d2ff70', 3, 'Squeeze the juice of six Seville oranges and eight lemons into it');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2b3ba906392de604d2ff70', 4, 'Stir it well and pour into it three more pints of brandy, three pints of rum, and three quarts of water');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2b3ba906392de604d2ff70', 5, 'Make two quarts of skimmed milk boiling hot');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2b3ba906392de604d2ff70', 6, 'Grate a nutmeg into it');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2b3ba906392de604d2ff70', 7, 'Mix it gradually with the other ingredients');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2b3ba906392de604d2ff70', 8, 'Add a sufficient quantity of fine loaf sugar to sweeten it, about two pounds');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2b3ba906392de604d2ff70', 9, 'Stir it till the sugar is dissolved');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2b3ba906392de604d2ff70', 10, 'Let the mixture stand twelve hours');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2b3ba906392de604d2ff70', 11, 'Strain it through a flannel bag till it is quite clear');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2b3ba906392de604d2ff70', 12, 'If bottled off and well corked, it will keep in any climate and for any length of time');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2b3ba906392de604d2ff70', 13, 'The bottles must be perfectly dry');
