INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fb0f4951b2c759c8a3d086', 0, 'Extract the juice from the peeling of one Seville orange and one lemon');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fb0f4951b2c759c8a3d086', 1, 'Extract the juice of six Seville oranges and six lemons');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fb0f4951b2c759c8a3d086', 2, 'Put the whole into a jug with six glasses of calves-feet jelly in liquid state and a sufficient quantity of loaf sugar, about half a pound');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fb0f4951b2c759c8a3d086', 3, 'Pour on it one quart of boiling water');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fb0f4951b2c759c8a3d086', 4, 'Add four glasses of brandy and stir it well together');
