INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_d146fae1bcd303e0008c24', 3, 'water', 'water', 2, 'quarts', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_d146fae1bcd303e0008c24', 4, 'double refined sugar', 'double refined sugar', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_d146fae1bcd303e0008c24', 5, 'sherry or madeira', 'sherry or madeira', 1, 'bottle', 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d146fae1bcd303e0008c24', 0, 'Cut the rind off six lemons if large, eight if small');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d146fae1bcd303e0008c24', 1, 'Squeeze out the juice and put the rind and the juice together');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d146fae1bcd303e0008c24', 2, 'Add one quart of white brandy and let it remain closely covered for three or four days');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d146fae1bcd303e0008c24', 3, 'Squeeze the juice of six or eight additional lemons into two quarts of water');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d146fae1bcd303e0008c24', 4, 'Put into it a sufficient quantity of double refined sugar to sweeten the whole');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d146fae1bcd303e0008c24', 5, 'Boil it well and when quite cold, pour into it a bottle of sherry or madeira');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d146fae1bcd303e0008c24', 6, 'Mix it well with the lemon and brandy');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d146fae1bcd303e0008c24', 7, 'If sufficiently sweet, strain it through a flannel bag into a small cask');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d146fae1bcd303e0008c24', 8, 'At the expiration of three months bottle it off');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d146fae1bcd303e0008c24', 9, 'If the bottles are well corked and kept in a cool place, it will be fit to drink in a month');
