INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8681b37d9ed1737e8b41f7', 0, 'Extract juice from lemon peelings by rubbing loaf sugar on them');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8681b37d9ed1737e8b41f7', 1, 'Cut two lemons into thin slices');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8681b37d9ed1737e8b41f7', 2, 'Cut lemon rind thin');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8681b37d9ed1737e8b41f7', 3, 'Put lemon juice, sliced lemons, rind, sugar, and brandy into a large jug');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8681b37d9ed1737e8b41f7', 4, 'Mix well together');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8681b37d9ed1737e8b41f7', 5, 'Pour one quart of cold spring water upon it');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8681b37d9ed1737e8b41f7', 6, 'Grate nutmeg into it');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8681b37d9ed1737e8b41f7', 7, 'Add white wine and a bottle of cider');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8681b37d9ed1737e8b41f7', 8, 'Sweeten to taste with capillaire or sugar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8681b37d9ed1737e8b41f7', 9, 'Put handful of balm and handful of borage in flower into it, stalk downwards');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8681b37d9ed1737e8b41f7', 10, 'Put jug into a tub of ice');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8681b37d9ed1737e8b41f7', 11, 'When it has remained there one hour it is fit for use');
