INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fec2f01fddbda452bab8ff', 0, 'Put one quart of cold water, the juice of six lemons and six pot oranges, and four glasses of calves-feet jelly in a liquid state into a container');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fec2f01fddbda452bab8ff', 1, 'Stir the whole well together and let it remain covered over for half an hour');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fec2f01fddbda452bab8ff', 2, 'Strain it through a hair sieve');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fec2f01fddbda452bab8ff', 3, 'Add to it one bottle of capillaire, two glasses of sherry, half a pint of brandy, and one bottle of orange shrub');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fec2f01fddbda452bab8ff', 4, 'Put some pulverised sugar and ten fresh-laid hens'' eggs into a bowl');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fec2f01fddbda452bab8ff', 5, 'Beat them well together');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fec2f01fddbda452bab8ff', 6, 'Gradually unite the two mixtures by keeping the eggs well stirred as it is poured in');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fec2f01fddbda452bab8ff', 7, 'Whip it with a whisk until a fine froth rises');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fec2f01fddbda452bab8ff', 8, 'If sweet enough it is fit for immediate use');
