INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_38f850ee445baef2089aff', 0, 'Extract the juice from the rind of three lemons by rubbing loaf sugar on it');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_38f850ee445baef2089aff', 1, 'Cut the peeling of two Seville oranges and two lemons extremely thin');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_38f850ee445baef2089aff', 2, 'Extract the juice of four Seville oranges and ten lemons');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_38f850ee445baef2089aff', 3, 'Put the above ingredients and six glasses of calves-feet jelly in a liquid state into a jug and stir well');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_38f850ee445baef2089aff', 4, 'Pour two quarts of boiling water on the mixture and cover the jug closely');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_38f850ee445baef2089aff', 5, 'Place it near the fire for a quarter of an hour');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_38f850ee445baef2089aff', 6, 'Strain the liquid through a sieve into a punch bowl or jug');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_38f850ee445baef2089aff', 7, 'Sweeten it with a bottle of capillaire');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_38f850ee445baef2089aff', 8, 'Add half a pint of white wine, a pint of French brandy, a pint of Jamaica rum, and a bottle of orange shrub');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_38f850ee445baef2089aff', 9, 'Stir the mixture as the spirits are poured in');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_38f850ee445baef2089aff', 10, 'If not sufficiently sweet, add loaf sugar gradually in small quantities or a spoonful or two of capillaire');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_38f850ee445baef2089aff', 11, 'Serve up either hot or cold');
