INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_52bdcb482024c200aa0880', 0, 'Cut the peeling of six Seville oranges and six lemons extremely thin');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_52bdcb482024c200aa0880', 1, 'Pound it in a stone mortar');
