INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_52bdcb482024c200aa0880', 7, 'Add a sufficient quantity of fine loaf sugar to sweeten it, about two pounds');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_52bdcb482024c200aa0880', 8, 'Stir it till the sugar is dissolved');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_52bdcb482024c200aa0880', 9, 'Let the mixture stand twelve hours');
