INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_9b9df5769523f0773cda79', 5, 'Boil it well and when quite cold pour into it a bottle of sherry or madeira');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_9b9df5769523f0773cda79', 6, 'Mix it well with the lemon and brandy');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_9b9df5769523f0773cda79', 7, 'If sufficiently sweet, strain it through a flannel bag into a small cask');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_9b9df5769523f0773cda79', 8, 'At the expiration of three months bottle it off');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_9b9df5769523f0773cda79', 9, 'If the bottles are well corked and kept in a cool place, it will be fit to drink in a month');
