INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_4974b4418a5fba8e1f11d6', 0, 'Mix one quart of cold water, the juice of six lemons and six pot oranges, and four glasses of calves-feet jelly in a liquid state');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_4974b4418a5fba8e1f11d6', 1, 'Stir the whole well together and let it remain covered over for half an hour');
