INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_4974b4418a5fba8e1f11d6', 3, 'Add to it one bottle of capillaire, two glasses of sherry, half a pint of brandy, and one bottle of orange shrub');
