INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_4974b4418a5fba8e1f11d6', 6, 'Whip it with a whisk until a fine froth rises');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_4974b4418a5fba8e1f11d6', 7, 'If sweet enough it is fit for immediate use');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_4974b4418a5fba8e1f11d6', 8, 'Should be drank as soon as it is made');
