INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1cef82250fa23f2825c7a0', 0, 'Make several incisions in the rind of a lemon and stick cloves in the incisions');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1cef82250fa23f2825c7a0', 1, 'Roast the lemon by a slow fire');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1cef82250fa23f2825c7a0', 2, 'Put small equal quantities of cinnamon, cloves, mace, and all-spice, and a race of ginger into a saucepan with half a pint of water');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1cef82250fa23f2825c7a0', 3, 'Boil until reduced one half');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1cef82250fa23f2825c7a0', 4, 'Boil one bottle of port wine');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1cef82250fa23f2825c7a0', 5, 'Burn a portion of the spirit out of it by applying a lighted paper to the saucepan');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1cef82250fa23f2825c7a0', 6, 'Put the roasted lemons and spice into the wine');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1cef82250fa23f2825c7a0', 7, 'Stir it up well and let it stand near the fire ten minutes');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1cef82250fa23f2825c7a0', 8, 'Rub a few knobs of sugar on the rind of a lemon and put the sugar into a bowl or jug with the juice of half a lemon');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1cef82250fa23f2825c7a0', 9, 'Pour the wine upon it');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1cef82250fa23f2825c7a0', 10, 'Grate some nutmeg into it');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1cef82250fa23f2825c7a0', 11, 'Sweeten to taste and serve up with the lemon and spice floating in it');
