INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0e8f4194bddb21fa2ad51e', 0, 'Cut peeling of six Seville oranges and six lemons extremely thin');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0e8f4194bddb21fa2ad51e', 1, 'Pound in stone mortar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0e8f4194bddb21fa2ad51e', 2, 'Add one pint brandy and let remain six hours');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0e8f4194bddb21fa2ad51e', 3, 'Squeeze juice of six Seville oranges and eight lemons into it');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0e8f4194bddb21fa2ad51e', 4, 'Stir well');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0e8f4194bddb21fa2ad51e', 5, 'Pour in three pints brandy, three pints rum, and three quarts water');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0e8f4194bddb21fa2ad51e', 6, 'Make two quarts skimmed milk boiling hot');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0e8f4194bddb21fa2ad51e', 7, 'Grate nutmeg into milk');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0e8f4194bddb21fa2ad51e', 8, 'Mix milk gradually with other ingredients');
