INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_394acc4897f8ae4e09a733', 'Between the sheets', 'cocktail', 'The between the sheets is a cocktail consisting of white rum (or other light rum), cognac, triple sec, and lemon juice. When made with gin, instead of rum and cognac, it''s called a "maiden''s prayer".', 1, 3, 0, 'https://upload.wikimedia.org/wikipedia/commons/b/bf/Between_The_Sheets_Cocktail.jpg', 'cocktail', 0, 1, 1930, 'IBA Official Cocktail (The Unforgettables)', 'Paris, France', NULL, 'Printed in Harry Craddock''s 1930 Savoy Cocktail Book and attributed to Harry MacElhone of Harry''s New York Bar in Paris. Brandy, rum, Cointreau, and lemon create a boozy Sidecar variant. The suggestive name made it a staple of the Jazz Age demimonde.', NULL, NULL, NULL, 'martini', 'shaken', NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_394acc4897f8ae4e09a733', 0, 'white rum', 'white rum', 1.01, 'oz', 'bar');
