INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_569e0fcb7aa7158adb0fe2', 'Boulevardier', 'cocktail', 'The boulevardier cocktail is an alcoholic drink composed of whiskey, sweet vermouth, and Campari. It originated as an obscure cocktail in late 1920s Paris, and was largely forgotten for 80 years, before being rediscovered in the late 2000s as part of the craft cocktail movement, rapidly rising in popularity in the 2010s as a variant of the negroni, and becoming an IBA official cocktail in 2020.', 1, 3, 0, 'https://upload.wikimedia.org/wikipedia/commons/f/ff/VTR_Happy_Hour_-_Boulevardier.jpg', 'cocktail', 0, 1, 1927, 'IBA Official Cocktail (The Unforgettables)', 'Paris, France', NULL, 'First printed in Harry McElhone''s 1927 Barflies and Cocktails, named for expatriate Erskine Gwynne''s Paris magazine The Boulevardier. Swapping the Negroni''s gin for bourbon produces a richer, wintry variant. It lay forgotten until the 2000s cocktail revival rediscovered it.', NULL, NULL, NULL, 'rocks', 'stirred', 'orange peel', NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_569e0fcb7aa7158adb0fe2', 0, 'bourbon or rye whiskey', 'bourbon or rye whiskey', 1.5, 'oz', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_569e0fcb7aa7158adb0fe2', 1, 'Campari', 'campari', 1, 'oz', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_569e0fcb7aa7158adb0fe2', 2, 'sweet vermouth', 'sweet vermouth', 1, 'oz', 'bar');
