INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_6f9c1939a644d0dd8d8f8e', 'Brandy crusta', 'cocktail', 'A brandy crusta is an IBA Official Cocktail made of brandy, Maraschino Luxardo, curaçao, fresh lemon juice, sugar syrup, and Angostura bitters. The cocktail, named for the crust of sugar on the rim, was invented by Joseph Santini, a bartender in New Orleans at his bar, Jewel of the South.', 1, 3, 0, 'https://upload.wikimedia.org/wikipedia/commons/0/00/15-09-26-RalfR-WLC-0306.jpg', 'cocktail', 0, 1, 1852, 'IBA Official Cocktail (The Unforgettables)', 'New Orleans, USA', NULL, 'Created by Joseph Santini at the Jewel of the South in New Orleans around 1852, featuring a dramatic sugar-rimmed glass lined with a full lemon peel. Brandy, orange liqueur, lemon, and bitters made it the first cocktail to use citrus juice. It is the direct ancestor of the Sidecar and Margarita.', NULL, NULL, NULL, NULL, 'shaken', NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_6f9c1939a644d0dd8d8f8e', 0, 'of Maraschino', 'of maraschino', 25, 'percent', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_6f9c1939a644d0dd8d8f8e', 1, 'brandy', 'brandy', 75, 'percent', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_6f9c1939a644d0dd8d8f8e', 2, 'Juice of one lemon', 'juice of one lemon', 0, NULL, 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6f9c1939a644d0dd8d8f8e', 0, 'Fill glass with ice.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6f9c1939a644d0dd8d8f8e', 1, 'Shake, strain in glass, and trim with fruit in season.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_77d788d05517168e719b11', 'Hanky panky', 'cocktail', 'The hanky panky is a cocktail made from gin, sweet vermouth, and Fernet-Branca. It is a variation on the sweet martini, or Martinez, made distinctive by the Fernet-Branca, a bitter Italian digestivo.', 1, 3, 0, 'https://upload.wikimedia.org/wikipedia/commons/2/23/Hanky_Panky_cocktail.jpg', 'cocktail', 0, 1, NULL, 'IBA Official Cocktail (The Unforgettables)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'shaken', NULL, NULL, 'unreviewed');
