INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_7c9dea0d341fd010ac7a68', 'Last word', 'cocktail', 'The Last Word is a  gin-based cocktail originating at the Detroit Athletic Club in the 1910s, shortly before the start of Prohibition. After a long period of obscurity, it enjoyed a renewed popularity in the cocktail renaissance of the 2000s after being discovered by bartender Murray Stenson of the Zig Zag Café in Seattle.', 1, 3, 0, 'https://upload.wikimedia.org/wikipedia/commons/4/43/The_Last_Word_cocktail_raised.jpg', 'cocktail', 0, 1, 1916, 'IBA Official Cocktail (The Unforgettables)', 'Detroit, USA', NULL, 'Debuted at the Detroit Athletic Club around 1916 and printed in Ted Saucier''s 1951 Bottoms Up. Equal parts gin, green Chartreuse, maraschino, and lime, it fell into obscurity until Seattle bartender Murray Stenson revived it in 2004. Its resurgence helped define the modern equal-parts craft cocktail era.', NULL, NULL, NULL, 'coupe', 'shaken', NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_7c9dea0d341fd010ac7a68', 0, 'Green Chartreuse', 'green chartreuse', 1, 'oz', 'bar');
