INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7c9dea0d341fd010ac7a68', 0, 'Shake with ice and strain into a cocktail glass');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_72269e8d6124237c37b11e', 'Martinez', 'cocktail', 'The Martinez is a classic cocktail that is widely regarded as the direct precursor to the Martini. It serves as the basis for many modern cocktails, and several different versions of the original exist.', 1, 3, 0, 'https://upload.wikimedia.org/wikipedia/commons/d/dc/Martinez_Cocktail.jpg', 'cocktail', 0, 1, 1884, 'IBA Official Cocktail (The Unforgettables)', 'California, USA', NULL, 'First printed in O.H. Byron''s 1884 Modern Bartender''s Guide and claimed by both Martinez, California and Jerry Thomas''s Occidental Hotel in San Francisco. Old Tom gin, sweet vermouth, maraschino, and bitters form the direct ancestor of the dry Martini. It bridges the 19th-century cocktail to the modern era.', NULL, NULL, NULL, 'coupe', 'stirred', 'cherry', NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_72269e8d6124237c37b11e', 0, 'Gin', 'gin', 1, 'oz', 'bar');
