INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_3e70327a0fe7fd43974a26', 'Vieux Carré', 'cocktail', 'The Vieux Carré is an IBA official cocktail made with rye whiskey, cognac, sweet vermouth, Bénédictine, and Peychaud''s bitters. It originated with Walter Bergeron, a bartender at the Carousel Bar in Hotel Monteleone, New Orleans.', 1, 3, 0, 'https://upload.wikimedia.org/wikipedia/commons/f/f8/Vieux_Carr%C3%A9_in_Tumbler.jpg', 'cocktail', 0, 1, NULL, 'IBA Official Cocktail (The Unforgettables)', NULL, NULL, NULL, NULL, NULL, NULL, 'martini', 'stirred', 'Orange zest and maraschino cherry', NULL, 'unreviewed');
