INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_dcd4cb9f7a642b4215fd5a', 'Black Russian', 'cocktail', 'The Black Russian is a cocktail of vodka and coffee liqueur. It contains 50 ml vodka and 20 ml coffee liqueur, per IBA specified ingredients.', 1, 3, 0, 'https://upload.wikimedia.org/wikipedia/commons/9/91/Black_Russian.jpg', 'cocktail', 0, 1, 1949, 'IBA Official Cocktail (Contemporary Classics)', 'Brussels, Belgium', NULL, 'Created in 1949 by Belgian bartender Gustave Tops at the Hotel Metropole in Brussels for Perle Mesta, US ambassador to Luxembourg. Vodka and Kahlua over ice was named for Cold War connotations, not Russian origin. It remains one of the simplest two-ingredient classics.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_dcd4cb9f7a642b4215fd5a', 0, 'vodka', 'vodka', 1, 'fluid ounces', 'bar');
