INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_660c00febd801836ec0b0a', 'Bloody Mary', 'cocktail', 'A Bloody Mary is a cocktail containing vodka, tomato juice, and other spices and flavorings including Worcestershire sauce, hot sauces, garlic, herbs, horseradish, celery, olives, pickled vegetables, salt, black pepper, lemon juice, lime juice and celery salt. Some versions of the drink, such as the "surf ''n'' turf" Bloody Mary, include shrimp and bacon as garnishes.', 1, 3, 0, 'https://upload.wikimedia.org/wikipedia/commons/1/1f/Bloody_Mary_Coctail_with_celery_stalk_-_Evan_Swigart.jpg', 'cocktail', 0, 1, 1921, 'IBA Official Cocktail (Contemporary Classics)', 'Paris, France', NULL, 'Invented by bartender Fernand Petiot at Harry''s New York Bar in Paris around 1921, combining newly available canned tomato juice with vodka. Petiot refined the spiced version at the King Cole Bar in New York''s St. Regis after 1934, where management briefly renamed it the Red Snapper. It became the archetypal brunch and hangover cocktail.', NULL, NULL, NULL, 'highball', 'stirred', 'Celery and lemon wedge (optional)', NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_660c00febd801836ec0b0a', 0, 'vodka', 'vodka', 1.52, 'oz', 'bar');
