INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_68717624af94344f77dc88', 'Champagne cocktail', 'cocktail', 'A champagne cocktail is an alcoholic cocktail made with sugar, Angostura bitters, champagne, brandy, and a maraschino cherry as a garnish. It is one of the IBA official cocktails.', 1, 3, 0, 'https://upload.wikimedia.org/wikipedia/commons/9/96/Champagne_cocktail_-_Portal%2C_Clerkenwell%2C_London_%284356768748%29_%28cropped%29.jpg', 'cocktail', 0, 1, 1855, 'IBA Official Cocktail (Contemporary Classics)', 'USA/France', NULL, 'Printed in Jerry Thomas''s 1862 guide but in use by the 1850s, featuring a sugar cube soaked in Angostura dropped into Champagne. The resulting slow bead of rising bitter bubbles makes it one of the simplest and oldest Champagne drinks. Humphrey Bogart orders it in Casablanca.', NULL, NULL, NULL, 'flute', 'stirred', NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_68717624af94344f77dc88', 0, 'sugar', 'sugar', 1, 'cube', 'pantry');
