INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_68717624af94344f77dc88', 1, 'Saturate a cube of sugar with fi''ve or six drnps of Angostura bitters, place the sugar in a champagne glass with sugar tongs, fill the glass with cold champagne, and serve.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_68717624af94344f77dc88', 2, 'Never stir or decorate ·this beverage.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_93e4ec5e5d5751003caf41', 'Piña colada', 'cocktail', 'The piña colada (; Spanish: piña [ˈpi.ɲa], "pineapple", and colada [ko.ˈla.ða], "strained") is a cocktail made with rum, cream of coconut, and pineapple juice, usually served either blended or shaken with ice. It may be garnished with either a pineapple wedge, maraschino cherry, or both.', 1, 3, 0, 'https://upload.wikimedia.org/wikipedia/commons/b/b2/Pi%C3%B1a_Colada.jpg', 'cocktail', 0, 1, NULL, 'IBA Official Cocktail (Contemporary Classics)', NULL, NULL, NULL, NULL, NULL, NULL, 'hurricane', 'blended', 'pineapple wedge + cherry', NULL, 'unreviewed');
