INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_beeed4445dbf3f6a4b7c7e', 'Singapore sling', 'cocktail', 'The Singapore sling is a gin-based sling cocktail from Singapore. This long drink was reputed to have been developed in 1915 by Ngiam Tong Boon (traditional Chinese: 嚴崇文; simplified Chinese: 严崇文; pinyin: Yán Chóngwén; Wade–Giles: Yen Ch''ung-wen), a bartender at the Long Bar in Raffles Hotel, Singapore.', 1, 3, 0, 'https://upload.wikimedia.org/wikipedia/commons/2/20/Singapore_Sling_and_peanuts_at_the_Raffles_Hotel_Long_Bar_in_Singapore.jpg', 'cocktail', 0, 1, 1915, 'IBA Official Cocktail (Contemporary Classics)', 'Singapore', NULL, 'Created around 1915 by bartender Ngiam Tong Boon at the Long Bar of Raffles Hotel in Singapore, disguising a gin sling in pink so ladies could appear to be drinking fruit juice. The original recipe was lost and later reconstructed with cherry brandy, Benedictine, and pineapple. It remains Singapore''s national cocktail.', NULL, NULL, NULL, 'hurricane', 'shaken', 'cherry + pineapple', NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_beeed4445dbf3f6a4b7c7e', 0, 'gin', 'gin', 1.5, 'oz', 'bar');
