INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_77bcd4c2afaf359f0fdf65', 'Bee''s knees', 'cocktail', 'A bees knees (or bee''s knees) is a Prohibition era cocktail made with gin, fresh lemon juice,  and honey. It is served shaken and chilled, often with a lemon twist.', 1, 3, 0, 'https://upload.wikimedia.org/wikipedia/commons/9/96/Bee%27s_Knees.jpg', 'cocktail', 0, 1, 1921, 'IBA Official Cocktail (New Era Drinks)', 'Paris, France', NULL, 'Emerged during Prohibition-era Paris around the early 1920s, when honey and lemon masked the burn of rough bathtub gin. The name is 1920s slang for something excellent. It typifies how Prohibition''s poor-quality spirits forced bartenders to invent flavor-camouflaging classics.', NULL, NULL, NULL, 'martini', 'shaken', 'Garnish with lemon peel', NULL, 'unreviewed');
