INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_7d4ed27dc5e4997d05013a', 'Chartreuse swizzle', 'cocktail', 'The Chartreuse swizzle is a tiki cocktail made with green Chartreuse, velvet falernum, pineapple juice, and lime juice. Invented in 2003 by American bartender Marcovaldo Dionysos of San Francisco cocktail bar Harry Denton''s Starlight Room, the cocktail has since emerged as a modern classic.', 1, 3, 0, 'https://upload.wikimedia.org/wikipedia/commons/5/54/Chartreuse_swizzle.jpg', 'cocktail', 0, 1, NULL, 'IBA Official Cocktail (New Era Drinks)', NULL, NULL, NULL, NULL, NULL, NULL, 'collins', 'stirred', NULL, NULL, 'unreviewed');
