INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_c4cb4b71ec0ee13275143f', 0, '| served = on the rocks: poured over ice | garnish = lime wedge | prep = in a hi', ' served on the rocks poured over ice garnish lime wedge prep in a highball glass', 0, NULL, 'bar');
