INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_3da83601f8a37692f99abf', 0, 'The International Bartenders Association prescribes that all ingredients should be shaken in a shaker tin and then strained into a chilled cocktail glass');
