INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_2d9e1f83fb67ef8d6543b6', 'Paper plane', 'cocktail', 'The paper plane is a whiskey-based cocktail created in 2008. In 2020 it was added to the International Bartenders Association''s (IBA) list of official cocktails as a new era drink.', 1, 3, 0, 'https://upload.wikimedia.org/wikipedia/commons/6/6d/Taub_Family_Outpost_-_June_11_2021_-_Sarah_Stierch_02.jpg', 'cocktail', 0, 1, 2008, 'IBA Official Cocktail (New Era Drinks)', 'New York City, USA', NULL, 'Created by Sam Ross in 2008 for The Violet Hour in Chicago, named after the M.I.A. song Paper Planes. Equal parts bourbon, Aperol, Amaro Nonino, and lemon produce a perfectly balanced modern sour. It became a template for the equal-parts amaro cocktails of the 2010s.', NULL, NULL, NULL, 'martini', 'shaken', NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_2d9e1f83fb67ef8d6543b6', 0, 'bourbon whiskey', 'bourbon whiskey', 1.01, 'oz', 'bar');
