INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_2d9e1f83fb67ef8d6543b6', 2, 'aperol', 'aperol', 1.01, 'oz', 'bar');
