INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2d9e1f83fb67ef8d6543b6', 0, 'Pour all ingredients into cocktail shaker, shake well with ice, strain into chilled cocktail glass');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_e495d6e545066860249139', 'Pisco punch', 'cocktail', 'Pisco punch is an alcoholic beverage made famous by Duncan Nicol at the Bank Exchange Saloon at the end of the 19th century, in San Francisco, California. The Bank Exchange Saloon was located on the southeast corner of the intersection of Montgomery and Washington Streets, in the Montgomery Block building, where the Transamerica Pyramid now stands.', 1, 3, 0, 'https://upload.wikimedia.org/wikipedia/commons/d/d5/Pisco_Punch.jpg', 'cocktail', 0, 1, 1890, 'IBA Official Cocktail (New Era Drinks)', 'San Francisco, USA', NULL, 'Invented by Duncan Nicol at the Bank Exchange Saloon in San Francisco in the 1890s, using Peruvian pisco, pineapple, lemon, and gum syrup. Nicol took the exact recipe to his grave and Prohibition closed the saloon in 1920. Modern versions are reconstructions from former patrons'' memories.', NULL, NULL, NULL, 'rocks', 'shaken', 'pineapple chunk', NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_e495d6e545066860249139', 0, 'pisco', 'pisco', 2, 'oz', 'bar');
