INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_3219556aa4271d52a5921e', 'Porn star martini', 'cocktail', 'The Pornstar Martini is a passion fruit-flavoured cocktail made with vanilla-flavoured vodka, Passoã, passion fruit purée, and vanilla sugar. It is traditionally accompanied by a chilled shot glass of champagne.', 1, 3, 0, 'https://upload.wikimedia.org/wikipedia/commons/a/ab/Porn_star_martini_cocktail.jpg', 'cocktail', 0, 1, NULL, 'IBA Official Cocktail (New Era Drinks)', NULL, NULL, NULL, NULL, NULL, NULL, 'martini', 'shaken', 'Passion fruit half and an accompanying shot glass of champagne', NULL, 'unreviewed');
