INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_f41fb33cd6fb20b753493d', 'Knickerbocker', 'cocktail', 'A 19th-century fancy drink-style drink from Jerry Thomas''s 1862 Bartenders Guide.', 1, 5, 0, NULL, 'cocktail', 1, 1, 1862, 'The Bon-Vivant''s Companion (Jerry Thomas, 1862)', 'New York, USA', NULL, 'Printed in Jerry Thomas''s 1862 Bar-Tender''s Guide, named for the old Dutch families of New York. Rum, orange curacao, raspberry syrup, and lemon make it one of the earliest American rum cocktails. It appears in nearly every major 19th-century bar manual.', '184. Knickerbocker. 

(Use small bar glass.) 

£ a lime, or lemon, squeeze out the juice, and put rind 
and juice in the glass. 

2 teaspoonfuls of raspberry syrup. 
1 wine-glass Santa Cruz rum. 

£ teaspoonful of Curacoa. 

Cool with shaved ice; shake up well, and ornament 
with berries in season. If this is not sweet enough, put in 
a little more raspberry syrup.', NULL, NULL, 'rocks', 'shaken', 'berries in season', 14, 'unreviewed');
