INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_95a2221c84e43e305793b1', 'Medford Bum Cocktail', 'cocktail', '1895 Kappeler cocktail, preserved verbatim from Modern American Drinks.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1895, 'Modern American Drinks (George Kappeler, 1895)', 'New York, USA', 'George J. Kappeler', NULL, 'Prepare same as Brandy Cocktail, using Med- ford rum in place of brandy. Two dashes gum-syrup, two dashes Peyschaud bitters, one dash orange bitters, half a jigger brandy, half a jigger French vermouth, a mixing- glass half-full fine ice. Mix, strain into cocktail- glass, add a maraschino cherry. Two lumps of ice in a small wine-glass, add three dashes gum-syrup, two dashes Angostura bitters, one pony brandy, one pony French ver- mouth. Mix, take out the ice, add a small piece twisted lemon-peel. A cocktail-glass half-full hard cider, one fresh egg ; season with pepper and salt. Serve.', NULL, 'Contains raw egg. Use pasteurized eggs or omit for food-safety.', 'coupe', 'stirred', 'twisted lemon peel', 32, 'unreviewed');
