INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_47849ddc41f9cff5788813', 0, 'Put into a glass pitcher one tablespoonful fine sugar, a little water - dissolve; add the juice of half a lemon, a few lumps of clear ice, half a pony white curagoa, half a pony brandy, one pint cider, one bottle plain soda, two slices of lemon, two of orange, one of cucumber-rind, a few lumps of clear ice; mix until cold.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_47849ddc41f9cff5788813', 1, 'Add a few sprigs of fresh mint on top, stems down.');
