INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_95e9bec8a4937c4b96155b', 'Brandy Float', 'cocktail', 'Historic 1895 drink from Kappeler''s Modern American Drinks.', 1, 4, 0, NULL, 'cocktail', 1, 1, 1895, 'Modern American Drinks (George Kappeler, 1895)', 'New York, USA', 'George J. Kappeler', NULL, 'Fill a pony-glass with brandy, put a thin whis- key-glass over it, rim down ; reverse the glasses, 64 MODERN AMERICAN DRINKS. holding them tightly together, so as to keep the brandy in the pony glass, then fill the whiskey- glass half -full seltzer and draw out the pony glass carefully so as to leave the brandy floating on top of seltzer.', NULL, NULL, 'cordial', 'layered', NULL, 40, 'unreviewed');
