INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_95e9bec8a4937c4b96155b', 0, 'Fill a pony-glass with brandy, put a thin whis- key-glass over it, rim down ; reverse the glasses, 64 MODERN AMERICAN DRINKS. holding them tightly together, so as to keep the brandy in the pony glass, then fill the whiskey- glass half -full seltzer and draw out the pony glass carefully so as to leave the brandy floating on top of seltzer.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_9aee0f17875b3db8957d49', 'Curacoa Float', 'cocktail', 'Historic 1895 drink from Kappeler''s Modern American Drinks.', 1, 4, 0, NULL, 'cocktail', 1, 1, 1895, 'Modern American Drinks (George Kappeler, 1895)', 'New York, USA', 'George J. Kappeler', NULL, 'Fill a pony-glass half -full maraschino, then fill with orange curagoa, be careful to keep the two cordials in separate layers.', NULL, NULL, 'cordial', 'layered', NULL, 40, 'unreviewed');
