INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_2c8c0089c56b91cca45fac', 'Absinthe Frappe, No. 2', 'cocktail', 'Historic 1895 drink from Kappeler''s Modern American Drinks.', 1, 5, 0, NULL, 'cocktail', 1, 1, 1895, 'Modern American Drinks (George Kappeler, 1895)', 'New York, USA', 'George J. Kappeler', NULL, 'A mixing-glass half -full fine ice ; add one pony of absinthe, one pony of water, one dash anisette; shake until ice forms on outside of shaker, strain into thin glass, add a squirt of seltzer. Brandy Punch Frappe\ Fill two mixing-glasses with fine ice; put into one of them one tablespoonful fine sugar, a little water, the juice of half a lemon, one jigger brandy. Turn the second glass on top of first ; leave there a moment, then turn the glasses so as to allow the liquid to flow from one glass into the other. Repeat this until the mixture is very cold ; strain into a fancy glass, trim with fruits in season. Coffee Frappe\ Dissolve one lump of sugar with one demi-tasse of cold coffee in a mixing-glass; add a few lumps of ice, one pony brandy. Shake well and strain into a fancy bar- glass. Brandy Frappe\ Take two mixing-glasses of the same size, fill them with fine shaven ice; pour into one of them one jigger brandy and a few dashes maraschino. Turn the second glass on top of first, then reverse the glasses several times, holding them together so as to allow the liquid to slowly flow from one glass to the other; when cold strain into fancy glass.', NULL, NULL, 'coupe', 'frappe', 'seasonal fruit', 25, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_2c8c0089c56b91cca45fac', 0, 'absinthe', 'absinthe', NULL, 'pony', 'bar');
