INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_7f9e86fa71c6c587d4dbf7', 'Gin Tea Punch', 'cocktail', '1895-era punch, served in ice with trim of fruit.', 1, 5, 2, NULL, 'cocktail', 1, 1, 1895, 'Modern American Drinks (George Kappeler, 1895)', 'New York, USA', 'George J. Kappeler', NULL, 'Grate off the yellow part of the rinds of six lemons into a punch-bowl, add one pound cut-loaf sugar, the juice of the six lemons, half a pint of boiling water ; mix well, add two quarts old Tom gin. Infuse one teaspoon ful coriander seeds in a pint of boiling green tea for twenty minutes, then add while hot to the mixture in the bowl, stir well and when cold strain, bottle, cork and seal. Keep in a cool place.', NULL, NULL, 'punch-bowl', 'hot-built', NULL, 12, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_7f9e86fa71c6c587d4dbf7', 0, 'cut-loaf sugar', 'cut-loaf sugar', NULL, 'pound', 'bar');
