INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7f9e86fa71c6c587d4dbf7', 0, 'Grate off the yellow part of the rinds of six lemons into a punch-bowl, add one pound cut-loaf sugar, the juice of the six lemons, half a pint of boiling water ; mix well, add two quarts old Tom gin.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7f9e86fa71c6c587d4dbf7', 1, 'Infuse one teaspoon ful coriander seeds in a pint of boiling green tea for twenty minutes, then add while hot to the mixture in the bowl, stir well and when cold strain, bottle, cork and seal.');
