INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_7ff0889548f072e9a81100', 'Lemon Sherbet', 'cocktail', 'Historic 1895 drink from Kappeler''s Modern American Drinks.', 1, 5, 2, NULL, 'cocktail', 1, 0, 1895, 'Modern American Drinks (George Kappeler, 1895)', 'New York, USA', 'George J. Kappeler', NULL, 'Use two quarts boiling water, eight lemons, the white of an egg, one quart sugar. Spread part of MODERN AMERICAN DRINKS. 115 the sugar on a board, and after wiping the lemons with a damp cloth roll them in the sugar to ex- tract the oil; then cut in halves, remove the seeds and squeeze out the juice. Boil all the sugar and water until clear. Remove the scum as it rises. Add the lemon-juice to the syrup, strain it and pour gradually on to the beaten white of an egg ; mix and freeze.', NULL, NULL, 'coupe', 'hot-built', NULL, NULL, 'unreviewed');
