INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_78a02fd9d0730b13373361', 3, 'Just before the punch is to be served add and mix into it one-half pint of old Jamaica rum and one pint of champagne for every two quarts of the sherbet.');
