INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_7f2c4d0b7f24716727334d', 'Pine Apple Sherbet', 'cocktail', 'Historic 1895 drink from Kappeler''s Modern American Drinks.', 1, 3, 0, NULL, 'cocktail', 1, 0, 1895, 'Modern American Drinks (George Kappeler, 1895)', 'New York, USA', 'George J. Kappeler', NULL, 'A pint and a half canned, or one large ripe pine- apple, a pint of fine sugar, a pint of water, one tablespoonful gelatin. Soak the gelatin one hour in cold water. Cut the hearts and eyes from the fruit, chop it fine, add the sugar and juice of fruit. Have half of the water hot, and dissolve the gela- tin in it, stir this and the cold water into the chopped pineapple and freeze.', NULL, NULL, 'coupe', 'stirred', NULL, NULL, 'unreviewed');
