INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_b6ce5dc5f31ae4f7076c91', 3, 'Four bottles of Champagne make a gallon, and this is generally sufficient for fifteen persons in a mixed party.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_65ead7e0d87098e9d370e9', 'Claret Punch', 'cocktail', '1878-era punch from the Criterion repertoire.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'Use large tumbler. One and a half tea-spoonful of sugar ; one slice of lemon ; two or three slices of orange. Fill the tumbler with chipped ice, and then pour in the claret. Shake well and ornament with fruit in season. Place a straw in the glass.', NULL, NULL, 'highball', 'shaken', 'lemon slice', 14, 'unreviewed');
