INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_2a41038098ea828bf7dc88', 'Criterion Milk Punch', 'cocktail', 'A house specialty of London''s Criterion Restaurant, where Engel presided.', 1, 5, 3, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'Put the following ingredients into a very clean pitclier>- The juice of three lemons, the rind 4)f two femcms; one feond of pow- dered sugar; one pineapple, peeled, sliced, and pounded ; six cloves ; twenty coriander seeds ; one small stick of cinnamon ; one pint of brandy ; one pint of rum ; one gill of arrack ; one cup of strong green tea; one quart of boiling water ; the boiling water to be added last. Cork this down to prevent evaporation, and allow these ingredients to steep for at least six hours, then add a quart of hot milk and the juice of two lemons. Mix and filter through a jelly bag, and when the punch has passed bright, bottle it and cork tightly. This punch should be iced for drinking.', NULL, NULL, 'highball', 'hot-built', NULL, 14, 'unreviewed');
