INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_3c41724baacb81708089b1', 'English Milk Punch', 'cocktail', '1878-era punch from the Criterion repertoire.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'This seductive drink is made in the following manner : — To two quarts of water add one quart of milk ; mix one quart of Jamaica rum with two quarts of French brandy, and put the spirit to tho milk, stirring it for a short time ; let it stand for an jiour, but do not suffer anyone of delicate appetite to see the melange in its present state, as the sight might create a distaste for the punch when perfected. Filter through blotting-paper into bottles, and should you Rnd that the liquid be cloudy, which it should not be, you may clarify it by adding a small portion of isinglass to each bottle. The above receipt will furnish you with half a dozen bottles of punch.', NULL, NULL, 'highball', 'stirred', NULL, 14, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_3c41724baacb81708089b1', 0, 'water', 'water', NULL, 'quarts', 'bar');
