INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_b715f3fa681da710a45257', 1, 're- fined sugar', 're- fined sugar', NULL, 'pounds', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_b715f3fa681da710a45257', 2, 'new milk', 'new milk', NULL, 'quarts', 'bar');
