INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7d933c6834dcad09f6688d', 0, 'For a Party oj Fifteen* Take the juice of ten lemons and two sweet oranges ; dissolve in it two pounds of powdered sugar, and add the thin rind of an orange; run this through a sieve, and stir in by degrees the whites of ten eggs beaten into a froth.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7d933c6834dcad09f6688d', 1, 'Put the bowl with the mix- ture into an ice pail, let it freeze a little, then stir briskly into it a bottle of Champagne and a bottle of Rum.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_005d65f9e53fc789221415', 'Tea Punch', 'cocktail', '1878-era punch from the Criterion repertoire.', 1, 5, 3, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'Make an infusion of the best green tea, an ounce to a quart of boiling water. Put before the fire a silver or other metal bowl to become quite hot, and then put into it — ^half pint of brandy ; half pint of rum ; quarter of a pound of lump sugar ; the juice of a large lemon. Set these a light and pour in the tea gradually, mixing it from time to time with a ladle. It will remain burning for some time, and is to be poured in that state into the glasses. In order to increase the flavour a few lumps of the sugar should be rubbed over the lemon peel. This punch may be made in a china bowl, but in that case the flame goes off more rapidly.', NULL, NULL, 'punch-bowl', 'hot-built', 'lemon peel', 14, 'unreviewed');
