INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_4aa33830b64bc16c9bfc97', 'Criterion Cocktail', 'cocktail', 'A house specialty of London''s Criterion Restaurant, where Engel presided.', 8, 3, 0, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'To make a splendid bottle of Criterion Cocktail, use the follow- ing ingredients : — Three-eighths of a bottle of brandy ; half a pint of water ; one liqueur glass of Boker''s bitters ; one wine glass of plain syrup ; half a liqueur glass of Benedictine. The author has always used this recipe in compounding the above beverage for connoisseurs. Whiskey and Gin Cocktails in bottles may be made by using the above recipe, substituting those liquors in place of brandy.', NULL, NULL, 'coupe', 'stirred', NULL, 32, 'unreviewed');
