INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_f24c9fc8ade28eb115c8f4', 4, 'Any kind of wine may be mulled, but port or claret are those usually selected for the purpose, and the latter requires a larger proportion of sugar.');
