INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_0b997c4c6d1ee8662c5129', 'Port Wine Negus', 'cocktail', 'Sweetened, spiced wine — a Victorian-era warmer.', 1, 5, 3, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'To every pint of port allow one quart of boiling watery quarter of a pound of loaf sugar ; one lemon ; grated nutmeg to taste. Put the wine in a jug ; rub some lumps of sugar (a quarter of a pound) on the lemon rind until all the yellow part of the skin is absorbed; then squeeze the juice and strain it; add the sugar and lemon juice to the port wine, with the grated nutmeg ; pour on the boiling water, cover the jug, and when the beverage has cooled a little, it will be ready for use. Negus may also be made of sherry or any other sweet wine, but it is more usually made of port. This beverage derives its name from Colonel Negus, who is said to have invented it.', NULL, NULL, 'wine', 'hot-built', 'grated nutmeg', 14, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_0b997c4c6d1ee8662c5129', 0, 'loaf sugar', 'loaf sugar', NULL, 'pound', 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0b997c4c6d1ee8662c5129', 0, 'To every pint of port allow one quart of boiling watery quarter of a pound of loaf sugar ; one lemon ; grated nutmeg to taste.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0b997c4c6d1ee8662c5129', 1, 'Put the wine in a jug ; rub some lumps of sugar (a quarter of a pound) on the lemon rind until all the yellow part of the skin is absorbed; then squeeze the juice and strain it; add the sugar and lemon juice to the port wine, with the grated nutmeg ; pour on the boiling water, cover the jug, and when the beverage has cooled a little, it will be ready for use.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0b997c4c6d1ee8662c5129', 2, 'Negus may also be made of sherry or any other sweet wine, but it is more usually made of port.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0b997c4c6d1ee8662c5129', 3, 'This beverage derives its name from Colonel Negus, who is said to have invented it.');
