INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_22ba09de926d01689475b7', 'Claret or Champagne Cup', 'cocktail', 'Wine or champagne cup, fruited and iced for entertaining.', 8, 3, 0, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'These drinks are highly appreciated in Russia, where for many years they have enjoyed a high reputation amongst the aristo- cracy of the Muscovite''s Empire. Proportions: — Three bottles of claret ; two-thirds of a pint of Curagoa ; one pint of sherry ; half-pint of brandy ; two wine glasses of syrup of rasp- berries ; three oranges, and one lemon cut in slices ; some sprigs of borage ; a small piece of rind of cucumber ; two bottles of German seltzer; three bottles of soda-water. Stir this together, and sweeten with Capillaire or pounded sugar until it ferments. Let it stand one hour ; strain it and ice it well, it is then ready for use. Serve in small glasses. The same for Champagne Cup-r-Champagne instead of claret ; Noyeau instead of raspberry.', NULL, NULL, 'punch-bowl', 'stirred', NULL, 12, 'unreviewed');
