INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_f59370cb224c3d671c43cf', 'Crimean Cup', 'cocktail', 'Wine or champagne cup, fruited and iced for entertaining.', 8, 3, 0, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'For a Party of Thirty, One quart of syrup of oranges ; one pint Otard brandy ; half a pint of Maraschino; half a pint of Jamaica rum; two bottles of Champagne ; two bottles of soda-water ; six ounces of sugar ; four medium sized lemons. Thinly peel the lemons, and place the rind in a bowl with the sugar. Macerate them well for a minute or two in order to extract the flavour from the lemons ; next squeeze the juice of the lemons upon this, add two bottles of soda-water, arid stir well till the sugar is dissolved ; pour in the syrup of oranges and whip the mixture well with an t%% whisk, in order to whiten the composition ; then add the brandy, rum and Maraschino. Strain the whole into a punch bowl and, just before serving, add the cham- pagne, which should be well iced. While adding the champagne stir well with ladle, this will render the Cup creamy and mellow. . 132 CRIMEAN CUP (A la Wyndham.) For a Party of Five, Thinly peel the rind of half an orange, put it into a bowl with a table-spoonful of crushed sugar, and macerate with the ladle for a minute or two ; then add one wine glass of Maraschino ; half a wine glass of Cognac ; the same of Cura^oa. Mix well together ; pour in two bottles of soda-water, and one of Champagne, during which time work it up and down with the punch ladle, and it is ready. A pound of pure ice is a great improvement', NULL, NULL, 'punch-bowl', 'stirred', NULL, 12, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_f59370cb224c3d671c43cf', 0, 'syrup of oranges', 'syrup of oranges', NULL, 'quart', 'bar');
