INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_f59370cb224c3d671c43cf', 8, 'Cognac', 'cognac', NULL, 'wine glass', 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_f59370cb224c3d671c43cf', 0, 'For a Party of Thirty, One quart of syrup of oranges ; one pint Otard brandy ; half a pint of Maraschino; half a pint of Jamaica rum; two bottles of Champagne ; two bottles of soda-water ; six ounces of sugar ; four medium sized lemons.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_f59370cb224c3d671c43cf', 1, 'Thinly peel the lemons, and place the rind in a bowl with the sugar.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_f59370cb224c3d671c43cf', 2, 'Macerate them well for a minute or two in order to extract the flavour from the lemons ; next squeeze the juice of the lemons upon this, add two bottles of soda-water, arid stir well till the sugar is dissolved ; pour in the syrup of oranges and whip the mixture well with an t%% whisk, in order to whiten the composition ; then add the brandy, rum and Maraschino.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_f59370cb224c3d671c43cf', 3, 'Strain the whole into a punch bowl and, just before serving, add the cham- pagne, which should be well iced.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_f59370cb224c3d671c43cf', 4, 'While adding the champagne stir well with ladle, this will render the Cup creamy and mellow. . 132 CRIMEAN CUP (A la Wyndham.) For a Party of Five, Thinly peel the rind of half an orange, put it into a bowl with a table-spoonful of crushed sugar, and macerate with the ladle for a minute or two ; then add one wine glass of Maraschino ; half a wine glass of Cognac ; the same of Cura^oa.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_f59370cb224c3d671c43cf', 5, 'Mix well together ; pour in two bottles of soda-water, and one of Champagne, during which time work it up and down with the punch ladle, and it is ready.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_f59370cb224c3d671c43cf', 6, 'A pound of pure ice is a great improvement');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_5147099c08b54c79122acb', 'Tom and Jerry', 'cocktail', '1878 Engel drink, preserved verbatim from American and Other Drinks.', 1, 5, 3, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'Use Punch-bowl for this mixture. Five pounds of powdered sugar ; twelve eggs ; half a small glass of Jamaica rum; one and a half tea-spoonful of ground cinnamon; half a tea-spoonful of ground cloves ; half a tea-spoonful of all-spice. Beat the white of the eggs to a stiff froth, and the yolks imtil they are as thin as water, then mix together and add spice and rum. Thicken with sugar until the mixture attains the consistency of a light batter. To SERVE OUT Tom and Jerry. Take a tumbler, and to one table-spoonful of the above mixture add one wine glass of brandy, and fill the glass with boiling water ; stir with a spoon, and grate a little nutmeg on top. Adepts in serving Tom and Jerry sometimes adopt a mixture of half brandy, quarter Jamaica rum, and quarter Santa Cruz rum, instead of brandy plain. This compound is usually mixed and kept in a bottle,, and a wine glass full is used to each tumbler of Tom and Jerry.', NULL, NULL, 'coupe', 'hot-built', 'grated nutmeg', 18, 'unreviewed');
