INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_022a5d5dcc85c32ad87f9e', 'Porter Cup', 'cocktail', 'Wine or champagne cup, fruited and iced for entertaining.', 8, 3, 0, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'Mix, in a tankard or covered jug, a bottle of porter, and an equal quantity of table-beer ; pour in a glass of brandy, a dessert- spoonful of syrup of ginger ; add three or four lumps of sugar and half a nutmeg grated. Cover it down and expose it to the cold for half an hour. Just before sending it to table, stir in a tea-spoonfu of carbonate of soda, and add the fresh cut rind of a cucumber.', NULL, NULL, 'punch-bowl', 'stirred', NULL, 12, 'unreviewed');
