INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_e9d6fab2ab2ffdbc8bb2bc', 'Italian Lemonade', 'cocktail', 'A 19th-century lemonade — refreshing and citrus-forward.', 1, 5, 3, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'Pare and press twenty-four lemons ; pour the juice on the peels and let it remain on them all night. In the morning add two pounds of loaf sugar, a quart of good sherry, and three quarts of boiling water. Mix well ; add a quart of boiling milk, and strain it through a jelly bag until clear. FANCY DRINKS. 59 145 CLARET CUP, or MULLED CLARET. Peel one lemon; add to it some white powdered sugar ; pour over one glass of sherry ; then add a bottle of Bordeaux, and sweeten to taste. One bottle of soda-water, and nutmeg if you like it For Cup, strain and ice it well ; for Mull, heat it and serve it hot', NULL, NULL, 'highball', 'hot-built', NULL, NULL, 'unreviewed');
