INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_accbdd6435f819b331b9ec', 'Black Stripe', 'cocktail', '1878 Engel drink, preserved verbatim from American and Other Drinks.', 1, 5, 3, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'Use small tumbler. One wine glass of Santa Cruz rum ; one table-spoonful of molasses. This drink can either be made in summer or winter. If in the former season, mix in one table-spoonful of water, and cool with chipped ice ; if in the latter, fill up the tumbler with boiling water. Grate a little nutmeg on top in either case.', NULL, NULL, 'coupe', 'hot-built', 'grated nutmeg', 18, 'unreviewed');
