INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_47f6a571582b05f47b01e1', 'Orgeat Lemonade', 'cocktail', 'A 19th-century lemonade — refreshing and citrus-forward.', 1, 3, 0, NULL, 'beverage', 1, 0, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'Use large tumbler. Half a wine glass of orgeat syrup ; the juice of half a lemon. Fill the tumbler one-third full of ice, and then fill up with water. Shake well, and ornament with berries in season.', NULL, NULL, 'highball', 'shaken', 'seasonal berries', NULL, 'unreviewed');
