INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5842902d4a9f96268b1e9c', 1, 'Strain the juice of the lemon and add it to the water, with sufficient white sugar to sweeten the whole nicely.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5842902d4a9f96268b1e9c', 2, 'When well mixed, put in the soda, stir well, and drink while the mixture is in an effervescing state.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_c86aff85c5ee2a5f89b0e6', 'Sherbet-', 'cocktail', '1878 Engel drink, preserved verbatim from American and Other Drinks.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'Eight ounces of carbonate of soda ; six ounces of tartaric acid ; two pounds of loaf sugar (finely powdered) ; three drachms of essence of lemon. Let the powder be very dry. Mix thoroughly, and keep them for use in a wide-mouthed bottle closely corked. Put two good-sized tea-spoonfuls into a tumbler, pour in half a pint of cold water, stir briskly, and drink off.', NULL, NULL, 'highball', 'stirred', NULL, NULL, 'unreviewed');
