INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_268048de15b194e47a04ed', 'Ginger Wine', 'cocktail', '1878 Engel drink, preserved verbatim from American and Other Drinks.', 8, 5, 3, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'Put twelve pounds of loaf sugar and six ounces of powdered ginger into six gallons of water, let it boil for an hour ; then beat up the whites of half a dozen eggs with a whisk, and mix them well with the liquor. When quite cold, put it into a barrel, with six lemons cut into slices and a cupful of yeast. Let it work for three days, then put in the bung. In a week''s time you may bottle it, and it will be ready for immediate use. TEMPERANCE DRINKS. 67', NULL, NULL, 'coupe', 'hot-built', NULL, 18, 'unreviewed');
