INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a25e93d9975319cbee852d', 0, 'It occurred to the Author of this little work, after a conversation with an Indian gentleman, to make a cocktail called in India a Swizzle, Take a small tumbler, half fill it with chipped ice ; then add one and a half liqueur glasses of Boker^s bitters ; half a wine glass of brandy ; and two or three drops of Noyeau to flavour and sweeten it.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a25e93d9975319cbee852d', 1, 'Now swizzle this concoction, with an Indian cane swizzle, to a froth ; drink through a strainer.');
