INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a25e93d9975319cbee852d', 3, 'An Indian likes a cocktail swizzled ; a North American, within the last few years, will not take one unless it is stirred with a spoon; a South American will have it shaken; an Englishman, who has travelled in America, is more particular than any one of the others until you find out his taste, and is most difficult to please.');
