INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_3eb6cb93d69115f25dad88', 'Coffee Cocktail', 'cocktail', 'Pre-Prohibition cocktail from the Hoffman House Bartender''s Guide (1905).', 1, 3, 0, NULL, 'cocktail', 1, 1, 1905, 'The Hoffman House Bartender''s Guide (Charles Mahoney, 1905)', 'New York, USA', 'Charles S. Mahoney', NULL, 'Use large bar glass.
Take one tcaspoonftil powdered white sugar.
One fresh egg.
One large wine-glass of port wine.
One pony of brandy.
Two or three lumps of ice.
Break the egg into the glass, put in the sugar,
and lastly the port wine, brandy and ice.
Shake up very thoroughly and strain into a
medium bar goblet. Grate a little nutmeg on top
before serving.
The name of this drink is a misnomer, as coffee
and bitters are not to be found among its ingredients,
but it looks like coffee when it has been properly con
cocted, and hence probably its name.', NULL, 'Original uses raw egg; use pasteurized egg for modern preparation.', 'rocks', 'shaken', 'grated nutmeg', 28, 'unreviewed');
