INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_2ea683bbc2122947d813c6', 'Brandy Crusta', 'cocktail', 'Historic 1904 drink from Frank Newman''s American Bar (Paris).', 1, 3, 0, NULL, 'cocktail', 1, 1, 1904, 'American Bar (Frank P. Newman, 1904)', 'Paris, France', 'Frank P. Newman', 'Created by Joseph Santini at the Jewel of the South in New Orleans around 1852, featuring a dramatic sugar-rimmed glass lined with a full lemon peel. Brandy, orange liqueur, lemon, and bitters made it the first cocktail to use citrus juice. It is the direct ancestor of the Sidecar and Margarita.', 'Verre n" 6
Prendre le verre n» 6, en sucrer les parois en passant
légèrement les bords extérieurs sur une tranche de citron,
tremper le verre dans le sucre en poudre, ce qui donne
une apparence de givre, couper un zeste de citron assez
long pour faire le tour de la paroi intérieure du verre,
une cerise dans le fond ensuite.
Prendre un gobelet en argent, remplir à moitié de glace
pilée :
3 traits d''angostura,
3 traits de marasquin,
3 traits de curaçao,
jus d''un quart de citron,
1 verre à liqueur de cognac.
Adapter un second gobelet, frapper fortement, passer
dans le verre préparé, servir.', NULL, NULL, 'rocks', 'shaken', 'lemon peel', 18, 'unreviewed');
