INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2ea683bbc2122947d813c6', 0, 'Verre n" 6 Prendre le verre n» 6, en sucrer les parois en passant légèrement les bords extérieurs sur une tranche de citron, tremper le verre dans le sucre en poudre, ce qui donne une apparence de givre, couper un zeste de citron assez long pour faire le tour de la paroi intérieure du verre, une cerise dans le fond ensuite.');
