INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6b5c882f9692388e20a273', 1, 'Adapter un gobelet en argent, bien ba''ftre, remplir le verre avec du Champagne, Bulteaux grand idéal, remuer doucement, garnir avec 2/2 tranches d/orange et quelques fruits de la saison, servir avec chalumeaux.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_abbe9ac1573ce47b5912f6', 'Champagne Cocktail', 'cocktail', 'Pre-Prohibition cocktail from Frank Newman''s Paris-American bar (1904).', 1, 3, 0, NULL, 'cocktail', 1, 1, 1904, 'American Bar (Frank P. Newman, 1904)', 'Paris, France', 'Frank P. Newman', 'Printed in Jerry Thomas''s 1862 guide but in use by the 1850s, featuring a sugar cube soaked in Angostura dropped into Champagne. The resulting slow bead of rising bitter bubbles makes it one of the simplest and oldest Champagne drinks. Humphrey Bogart orders it in Casablanca.', 'Verre n° 3
Prendre le verre n° 3, mettre un petit morceau de
glace :
1 zeste de citron,
3 traits d''angostura bitter.
Finir avec Champagne Bulteaux, remuer doucement,
servir avec chalumeaux.', NULL, NULL, 'flute', 'stirred', 'lemon peel', 12, 'unreviewed');
