INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_38b2db5ff4053da6f9cb10', 'Fruits Fizz', 'cocktail', 'Fizz from Newman''s American Bar (Paris, 1904).', 1, 3, 0, NULL, 'cocktail', 1, 1, 1904, 'American Bar (Frank P. Newman, 1904)', 'Paris, France', 'Frank P. Newman', NULL, 'Verre n» 7
Mettre dans le verre n» 7 quelques petits morceaux de
glace :
plusieurs tranches d''orange et d''ananas en pe
tits morceaux,
quelques fruits de la saison,
1 cuillerée à café de sirop de citron,
2 traits de cassis,
1 verre à liqueur de gin.
Remplir le verre avec du Champagne, remuer douce
ment avec une cuillère pour ne pas écraser les fruits, ser
vir avec une cuillère à café.', NULL, NULL, 'fizz', 'stirred', 'seasonal fruit', 12, 'unreviewed');
