INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_88301df545e0836fd5190c', 'Général Gordon''s Glaret Cup', 'cocktail', 'Historic 1904 drink from Frank Newman''s American Bar (Paris).', 1, 3, 0, NULL, 'cocktail', 1, 1, 1904, 'American Bar (Frank P. Newman, 1904)', 'Paris, France', 'Frank P. Newman', NULL, 'Pour 10 personnes
Préparer dans un bol en métal, une heure avant de ser
vir
Couper sur toute la longueur d''un concombre
2 zestes,
123 grammes de sucre en poudre,
1 bouteille de soda pour fondre le sucre,
le jus de 4 limons,
2 bouteille de bordeaux,
1/4 de bouteille de cherry-brandy,
1/4 de bouteille de cognac,
2 verres à madère de sirop de groseille,
2 verres à madère de curaçao.
Remuer, couper 5 tranches d''orange, 5 tranches de li
mon, 5 tranches de concombre, 250 grammes de fruits de
la saison, faire rafraîchir pendant une heure dans une
glacière, ou, à défaut, mettre le bol dans la glace pilée, re
muer tous les quarts d''heure sans écraser les fruits, reti
rer les zestes de concombre, ajouter, au moment de
servir, 1 bouteille de Champagne, Bulteaux 1893, servir.', NULL, NULL, 'rocks', 'stirred', 'cherry', 18, 'unreviewed');
