INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_485be3b981d0a76c9767fa', 'Mint Julep', 'cocktail', 'Mint julep from Newman''s American Bar (Paris, 1904).', 1, 3, 0, NULL, 'cocktail', 1, 1, 1904, 'American Bar (Frank P. Newman, 1904)', 'Paris, France', 'Frank P. Newman', 'Rooted in 18th-century Virginia as a morning medicinal, the julep entered print in 1803 and was defined with bourbon, sugar, and mint by the 1830s. Senator Henry Clay helped popularize it in Washington, and Churchill Downs made it the official drink of the Kentucky Derby in 1938. It is the South''s most storied cocktail.', 'Verre n" 9
Mettre dans le verre no 9:
1 cuillerée à café de sucre en poudre,
un peu d''eau pour fondre le sucre,
deux ou trois feuilles de menthe fraîche, les
écraser avec une cuillère-pilon, Jes retirer,
1 verre 1/2 à liqueur de cognac.
Remplir le verre de glace bien pilée, adapter un gobelet
en argent, frapper fortement, prendre une branche de
menthe fraîche, la piquer dans la glace au milieu du
verre, garnir d''une tranche d''orange coupée en quatre et
fruits de la saison, servir avec chalumeaux.', NULL, NULL, 'julep', 'shaken', 'orange slice', 22, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_485be3b981d0a76c9767fa', 0, 'sucre en poudre', 'sucre en poudre', 1, 'tsp', 'pantry');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_485be3b981d0a76c9767fa', 0, 'Verre n" 9 Mettre dans le verre no 9: 1 cuillerée à café de sucre en poudre, un peu d''eau pour fondre le sucre, deux ou trois feuilles de menthe fraîche, les écraser avec une cuillère-pilon, Jes retirer, 1 verre 1/2 à liqueur de cognac.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_485be3b981d0a76c9767fa', 1, 'Remplir le verre de glace bien pilée, adapter un gobelet en argent, frapper fortement, prendre une branche de menthe fraîche, la piquer dans la glace au milieu du verre, garnir d''une tranche d''orange coupée en quatre et fruits de la saison, servir avec chalumeaux.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_d4140b0b427af13af1031e', 'Mississipi punch', 'cocktail', 'Punch from Newman''s American Bar (Paris, 1904).', 1, 3, 0, NULL, 'cocktail', 1, 1, 1904, 'American Bar (Frank P. Newman, 1904)', 'Paris, France', 'Frank P. Newman', NULL, 'Verre 11° 7
Mettre dans le verre no 7:
le jus d''un demi-citron,
1/2 verre à liqueur de curaçao, "■
