INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_68bfe0befa584a6d1eccd3', 'Tom and Jerry', 'cocktail', 'Historic 1904 drink from Frank Newman''s American Bar (Paris).', 1, 3, 0, NULL, 'cocktail', 1, 1, 1904, 'American Bar (Frank P. Newman, 1904)', 'Paris, France', 'Frank P. Newman', 'Adapted by Jerry Thomas in the 1850s from a British egg-batter punch named for Pierce Egan''s 1820 book Life in London, Or the Day and Night Scenes of Jerry Hawthorn and his elegant friend Corinthian Tom. Hot milk or water is whipped into egg batter with rum and brandy. It is the quintessential American Christmas cocktail of the 19th century.', 'en grande quantité
6 livres de sucre en poudre,
1 litre de rhum Saint-James,
1 morceau de cannelle de 3 centimètres,
14 œufs bien frais,
1/2 cuillère à café d''épices,
1 verre à madère de cognac.
Prendre un grand bol dans lequel vous battez les blancs



d''œufs en neige et les jaunes à part jusqu''à ce qu''ils soient
liquides, ensuite mélanger ensemble, ajouter les épices
et le rhum, épaissir avec le sucre, jusqu''à ce que la mix
ture ait la consistance d''une pâte légère, prendre le verre
n° 3, mettre une cuillère à café de la mixture ci-dessus
remplir avec de l''eau bouillante, râper un peu de mus
cade, servir.', NULL, 'Original uses raw egg; use pasteurized egg for modern preparation.', 'rocks', 'built', NULL, 18, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_68bfe0befa584a6d1eccd3', 0, 'rhum saint-james', 'rhum saint-james', 1, 'liter', 'bar');
