INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_68bfe0befa584a6d1eccd3', 0, 'en grande quantité 6 livres de sucre en poudre, 1 litre de rhum Saint-James, 1 morceau de cannelle de 3 centimètres, 14 œufs bien frais, 1/2 cuillère à café d''épices, 1 verre à madère de cognac.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_68bfe0befa584a6d1eccd3', 1, 'Prendre un grand bol dans lequel vous battez les blancs d''œufs en neige et les jaunes à part jusqu''à ce qu''ils soient liquides, ensuite mélanger ensemble, ajouter les épices et le rhum, épaissir avec le sucre, jusqu''à ce que la mix ture ait la consistance d''une pâte légère, prendre le verre n° 3, mettre une cuillère à café de la mixture ci-dessus remplir avec de l''eau bouillante, râper un peu de mus cade, servir.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_6436ffaf87add969360382', 'Touch-me-not', 'cocktail', 'Historic 1904 drink from Frank Newman''s American Bar (Paris).', 1, 3, 0, NULL, 'cocktail', 1, 1, 1904, 'American Bar (Frank P. Newman, 1904)', 'Paris, France', 'Frank P. Newman', NULL, 'Verre n® 4
Prendre un gobelet en argent, mettre un peu de glace
pilée :
jus d''un quart de citron,
1/2 verre à liqueur de cassis, _
1/2 verre à liqueur de curaçao,
1 verre à liqueur de rhum.
Adapter un second gobelet, frapper fortement, passer
dans le verre n° 4, servir.', NULL, NULL, 'rocks', 'shaken', NULL, 18, 'unreviewed');
