INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_1ea3c8575ca6b3c90950e5', 'Vermouth Cocktail', 'cocktail', 'Pre-Prohibition cocktail from Frank Newman''s Paris-American bar (1904).', 1, 3, 0, NULL, 'cocktail', 1, 1, 1904, 'American Bar (Frank P. Newman, 1904)', 'Paris, France', 'Frank P. Newman', NULL, 'Verre no 5
Prendre le verre à mélange n° 1, mettre quelques mor
ceaux de glace :



3 traits d''angostura,
2 traits de curaçao.
Finir avec vermouth sec, remuer, passer dans le verre
n" b, servir avec un zeste de citron.', NULL, NULL, 'coupe', 'stirred', 'lemon peel', 28, 'unreviewed');
