INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ea3c8575ca6b3c90950e5', 0, 'Verre no 5 Prendre le verre à mélange n° 1, mettre quelques mor ceaux de glace : 3 traits d''angostura, 2 traits de curaçao.');
