INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0cc85cd7ca0252e381b1ad', 0, 'Verre n" 10 Prendre le verre n» 10, le remplir aux 3/4 de glace pi- lée : 2 traits de jus de citron, i cuillerée à café de sucre en poudre, 1/2 verre à liqueur de curaçao doux.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0cc85cd7ca0252e381b1ad', 1, 'Finir avec du rye ou bourbon-whisky et eau, quantités égales, adapter un gobelet en argent, frapper fortement, garnir de 2/2 tranches de citron et fruits de la saison, ver ser à la surface 3 gouttes de clierry-brandy (sans mélan ger), servir avec chalumeaux.');
