INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_39152b1bf721414ac8fb3e', 'Whisky Crusta', 'cocktail', 'Historic 1904 drink from Frank Newman''s American Bar (Paris).', 1, 3, 0, NULL, 'cocktail', 1, 1, 1904, 'American Bar (Frank P. Newman, 1904)', 'Paris, France', 'Frank P. Newman', NULL, 'Verre n" 6
Prendre le verre m 6, en sucrer les parois en passant
légèrement les bords extérieurs sur une tranche de citron,
tremper le verre dans le sucre en poudre, ce qui donne
une apparence de givre, couper un zeste de citron assez
long pour faire le tour de la paroi intérieure du verre,
mettre une cerise au fond, ensuite prendre un gobelet en
argent, remplir à moitié déglacé pilée :
3 traits d''angostura,
3 traits de marasquin.



pj -
3 traits de curaçao,
jus d''un quart de citron,
1 verra à liqueur de whisky.
Adapter un second gobelet, frapper fortement, passer
dans le verre préparé, servir.', NULL, NULL, 'coupe', 'shaken', 'lemon peel', 18, 'unreviewed');
