INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_81c72a91d899d2cfdcb939', 'Frappé coffee', 'drink', 'A frappé coffee, cold coffee, Greek frappé, or just frappé (Greek: φραπέ, frapé [fraˈpe]) is a Greek iced coffee drink generally made from spray-dried instant coffee, water, sugar, and milk. The word is often written frappe (without an accent).', 1, 5, 0, 'https://upload.wikimedia.org/wikipedia/commons/7/73/Cafe-frape-glas-holztisch-unscharf.jpg', 'drink', 0, 0, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'mug', 'built', NULL, NULL, 'unreviewed');
