INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_e6a31242580930a3dcd99a', 'Butter tea', 'drink', 'Butter tea, also known as bho jha or po cha (Tibetan: བོད་ཇ་, Wylie: bod ja, THL: bö ja, "Tibetan tea"), cha süma (Tibetan: ཇ་སྲུབ་མ་, Wylie: ja srub ma, THL: ja sup ma, "churned tea") in Standard Tibetan, sūyóu chá (酥油茶) in Mandarin Chinese, su ja (Tibetan script: སུ་ཇ, Wylie: suja, "churned tea") in Dzongkha, cha su-kan or gur gur cha in the Ladakhi language, and su chya or phe chya in the Sherpa language, is a drink of the people in the Himalayan regions of Nepal, Bhutan, India, Pakistan espe', 1, 5, 0, NULL, 'drink', 0, 0, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'mug', 'built', NULL, NULL, 'unreviewed');
