INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_a75da4029aa702464aa55c', 'Jun (drink)', 'drink', 'Jun, or xun, is a fermented drink similar to kombucha, differing only in that its base ingredients are green tea and honey instead of black tea and cane sugar. Jun is brewed by fermenting green tea (which has been sweetened with honey) with a symbiotic culture of bacteria and yeast (SCOBY).', 1, 5, 15, NULL, 'drink', 0, 0, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'mug', 'fermented', NULL, NULL, 'unreviewed');
