INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_046a7692acf0cc1bbbfcc9', 'Wassail', 'drink', 'The tradition of wassailing (also spelled wasselling) falls into two distinct categories: the house-visiting wassail and the orchard-visiting wassail. The house-visiting wassail, which traditionally occurs on the twelfth day of Christmastide known as Twelfth Night or Epiphany Eve (5 January), is the practice of people going door-to-door, singing and offering a drink from the wassail bowl in exchange for gifts; this practice still exists, but has largely been displaced by carol singing.', 1, 5, 0, NULL, 'drink', 0, 0, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'rocks', 'built', NULL, NULL, 'unreviewed');
