INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_9e6adb2898b47f7a0f63d9', 'Oliang', 'drink', 'Oliang (Thai: โอเลี้ยง, pronounced [ʔōːlía̯ŋ], also spelt oleang and olieng), commonly known as Thai iced coffee, is a popular Thai beverage. Oliang is prepared from a mixture of Robusta coffee grounds, brown sugar, and various grains and seeds like cardamom, corn, soybeans, rice, and sesame seeds.', 1, 5, 0, NULL, 'drink', 0, 0, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'mug', 'built', NULL, NULL, 'unreviewed');
