INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_f76952a3715c2b172b0e4e', 'Tao Bin', 'drink', 'Tao Bin (Thai: เต่าบิน, RTGS: Tao Bin, pronounced [tàw bin]) is a robotic barista and smart vending machine that dispenses a range of customized hot and cold beverages. Developed by Forth Vending, the machine uses a touchscreen interface and robotic arms to prepare drinks, which includes coffee, smoothies, protein shakes, and soft drinks.', 1, 5, 0, NULL, 'drink', 0, 0, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'mug', 'shaken', NULL, NULL, 'unreviewed');
