INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_a168f2dc372dc7e669148c', 'Teh tarik', 'drink', 'Teh tarik (lit. ''pulled tea''; Jawi: تيه تاريق‎) is a hot milk tea beverage most commonly found in restaurants, outdoor stalls, mamaks and kopitiams in Malaysia, Brunei, Indonesia, Singapore, and Thailand.', 1, 5, 0, NULL, 'drink', 0, 0, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'mug', 'blended', NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_a168f2dc372dc7e669148c', 0, 'a strong brew of black tea blended with condensed milk', 'a strong brew of black tea blended with condensed milk', 1, 'part', 'dairy');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a168f2dc372dc7e669148c', 0, 'Its name is derived from the process of repeatedly pouring the drink back and forth from one container into another (or "pulling") with arms extended during preparation, which helps to slightly cool the tea for consumption and gives it a frothy head.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a168f2dc372dc7e669148c', 1, 'It is made from a strong brew of black tea blended with condensed milk.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_1cbb445658ed9cff04edfb', 'Thai tea', 'drink', 'Thai tea (Thai: ชาไทย, RTGS: cha thai, pronounced [t͡ɕʰāː tʰāj]) is a Thai drink made from Ceylon black tea, milk, and sugar. Thai tea as consumed in Thailand is not typically brewed with spices, though many English language recipes inspired by Thai tea include ingredients such as star anise or cardamom to enhance the flavor.', 1, 5, 15, NULL, 'drink', 0, 0, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'mug', 'brewed', NULL, NULL, 'unreviewed');
