INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_980f9d097043cb0f93956e', 1, 'While all coffee drinks are based on either coffee or espresso, some drinks add milk or cream, some are made with steamed milk or non-dairy milks, or add water (like the americano).');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_47f13626a053394e7a58df', 'Sideritis', 'drink', 'Sideritis, also known as ironwort, mountain tea and shepherd''s tea, is a genus of flowering plants known for their use as herbal medicine, commonly as a herbal tea. They are abundant in Mediterranean regions, the Balkans, the Iberian Peninsula and Macaronesia, but can also be found in Central Europe and temperate Asia.', 1, 5, 0, NULL, 'drink', 0, 0, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'mug', 'built', NULL, NULL, 'unreviewed');
