INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_1a4737b7273960e1055e3a', 'Kabusecha', 'drink', 'Kabuse tea, or kabusecha (かぶせ茶) is a class of Japanese tea leaf. Kabuseru (かぶせる) literally means to cover or place on top, as a hat on a head, therefore kabuse tea is a tea leaf harvested from a tea plant that, for some period of time ranging from 2–25 days, has had a porous material draped over the plant while the young leaves are being produced.', 1, 5, 0, NULL, 'drink', 0, 0, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'mug', 'built', NULL, NULL, 'unreviewed');
