INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_eae3a32e40dd403c0c3c8e', 'Butterfly pea flower tea', 'drink', 'Butterfly pea flower tea, commonly known as blue tea, is a caffeine-free herbal beverage   made from decoction or infusion of the flower petals or whole flower of the Clitoria ternatea plant, alternatively known as butterfly pea, Aprajita, Asian pigeonwings, blue pea, Blue Tea Flowers, or Cordofan pea. Derived from a plant that is common to most South East Asian countries, butterfly pea flower tea has been brewed for centuries but only recently been introduced to tea drinkers outside the indigen', 1, 5, 15, NULL, 'drink', 0, 0, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'mug', 'brewed', NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_eae3a32e40dd403c0c3c8e', 0, 'alternatively known as butterfly pea', 'alternatively known as butterfly pea', 1, 'part', 'dairy');
