INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_3f0a78e96043ce5d4f828e', 'Coffeehouse culture of Baghdad', 'drink', 'The coffeehouse culture of Baghdad (Arabic: ثقافة المقهي البغدادية) is a set of traditions and social behaviors in old, local, or traditional Baghdadi coffeehouses in Baghdad, Iraq. Ever since their inception in the 1500s, cafés have acted as social forums and gathering grounds for friends and meetings for all ages as well as a gathering ground for intellectuals, thinkers, and personalities to discuss politics, art, literature, science, poetry, and other subjects that had a great impact on Iraq''', 1, 5, 0, NULL, 'drink', 0, 0, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'mug', 'built', NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_3f0a78e96043ce5d4f828e', 0, 'coffeehouse culture of baghdad', 'coffeehouse culture of baghdad', 1, 'serving', 'pantry');
