INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_44e80a5cfd3789b451b410', 'Isgelen tarag', 'drink', 'Isgelen tarag (Mongolian: исгэлэн тараг, ᠢᠰᠬᠦᠯᠡᠩ ᠲᠠᠷᠠᠭ, or kefir) is a yogurt drink made by the Mongolian people, most commonly by nomadic families. It often uses the milk of a mare, sheep, cows, the yak, camels (specifically, khormog), or of reindeer, depending on local traditions or availability.', 1, 5, 0, NULL, 'drink', 0, 0, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'rocks', 'built', NULL, NULL, 'unreviewed');
