INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_4c1f8828b03b5c6bb715f3', 'Momchilovtsi (drink)', 'drink', 'Momchilovtsi (Chinese: 莫斯利安; pinyin: Mòsīlì’ān) is a Chinese brand of drinkable yogurt produced by Bright Dairy & Food (光明乳业股份有限公司), a company in Shanghai. Made from Lactobacillus bulgaricus imported from Bulgaria, it was inspired by the yogurt in the village of Momchilovtsi, Bulgaria.', 1, 5, 0, NULL, 'drink', 0, 0, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'rocks', 'built', NULL, NULL, 'unreviewed');
