INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6d54bfca2d91bc53a11726', 0, 'Combine all herbs, nuts and spices with vodka in a 1 quart or larger aging container');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6d54bfca2d91bc53a11726', 1, 'Cap tightly and shake daily for 2 weeks');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6d54bfca2d91bc53a11726', 2, 'Strain through a fine muslin cloth or coffee filter, discarding solids');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6d54bfca2d91bc53a11726', 3, 'Clean out aging container');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6d54bfca2d91bc53a11726', 4, 'Place liquid back in container');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6d54bfca2d91bc53a11726', 5, 'Place sugar and water in saucepan and stir to combine over medium heat');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6d54bfca2d91bc53a11726', 6, 'When sugar is completely dissolved, set aside and let cool');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6d54bfca2d91bc53a11726', 7, 'When cool combine with food coloring and add to liqueur liquid');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6d54bfca2d91bc53a11726', 8, 'Cap and allow to age and mellow in a cool, dark place for one month');
