INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_01b8753c7c4bb46dad9945', 0, 'Pare very thinly the bright-colored rind from the oranges (no white)');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_01b8753c7c4bb46dad9945', 1, 'Blot the peel on paper towels to remove any excess oil');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_01b8753c7c4bb46dad9945', 2, 'Put peel in a 4 cup screw-top jar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_01b8753c7c4bb46dad9945', 3, 'Add 2 cups vodka');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_01b8753c7c4bb46dad9945', 4, 'Close jar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_01b8753c7c4bb46dad9945', 5, 'Store in a cool, dark place for 2 days or until the vodka has absorbed the flavor');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_01b8753c7c4bb46dad9945', 6, 'Remove peel and add remaining vodka');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_01b8753c7c4bb46dad9945', 7, 'Close jar and add remaining cup of vodka');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_01b8753c7c4bb46dad9945', 8, 'Close the jar and store in a cool dark place at least 1 month to age');
