INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_06d5114b0ad15aa1ce357f', 2, 'Place the sugar in a pot. Slowly melt it over medium heat, stirring, and cook until it reaches a light brown caramel');
