INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d0eeec57b4a92610f1f870', 0, 'Cut mangoes into 3 slices each—2 from either side of the seed and 1 with the seed in it');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d0eeec57b4a92610f1f870', 1, 'Pressure cook mangoes with one small cup of water. Turn off heat as soon as the pressure cooker whistles once');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d0eeec57b4a92610f1f870', 2, 'Open cooker after 5–7 minutes and leave to cool');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d0eeec57b4a92610f1f870', 3, 'Grind sugar and roasted cumin seeds using a food processor. If using chilli, grind that too');
