INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d0eeec57b4a92610f1f870', 5, 'When cool, squeeze pulp of mangoes into a blender using hands. Discard skin and seeds');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d0eeec57b4a92610f1f870', 6, 'Purée mango pulp until smooth');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d0eeec57b4a92610f1f870', 7, 'Add ground sugar, rock salt, roasted cumin seeds, chilli powder, and minced mint leaves. Blend well');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d0eeec57b4a92610f1f870', 8, 'Store in clean plastic or glass bottle. Refrigerate');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d0eeec57b4a92610f1f870', 9, 'To serve, add 4–5 teaspoons of the mango mixture to a glass of water. Enjoy!');
