INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_101553ffa8f3705d125dcd', 0, 'Pour water into a saucepan, add anise seeds, and bring to a boil over medium heat');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_101553ffa8f3705d125dcd', 1, 'Turn off the heat, cover, and leave to infuse for 30 minutes');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_101553ffa8f3705d125dcd', 2, 'Filter out the seeds');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_101553ffa8f3705d125dcd', 3, 'Add the sugar as desired, and bring to boil again over medium heat. Simmer until the syrup drips into a thin stream');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_101553ffa8f3705d125dcd', 4, 'Filter a second time');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_101553ffa8f3705d125dcd', 5, 'Let it cool and bottle. Serve with very cold sparkling or still water according to preference');
