INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_69edb3adc1a193f4e797ef', 5, 'Rose water', 'rose water', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_69edb3adc1a193f4e797ef', 0, 'Combine the water and cinnamon sticks in a saucepan. Bring to a boil');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_69edb3adc1a193f4e797ef', 1, 'Add the raisins to the boiling water, and simmer over low heat');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_69edb3adc1a193f4e797ef', 2, 'Sweeten drink to taste with sugar, and stir over very low heat to dissolve sugar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_69edb3adc1a193f4e797ef', 3, 'Remove from the heat, remove the cinnamon sticks, and let the drink completely cool down');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_69edb3adc1a193f4e797ef', 4, 'Flavour with orange blossom water and rose water');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_69edb3adc1a193f4e797ef', 5, 'Put the beverage in the refrigerator and serve very cold with or without raisins');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_ef4761f7d2bba3e47eef1b', 'Hlib Tmer (Algerian Date Milk)', 'drink', '| Beverages | Cuisine of Algeria', 1, 5, 0, NULL, 'mocktail', 0, 0, NULL, 'Wikibooks (CC-BY-SA 3.0)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_ef4761f7d2bba3e47eef1b', 0, 'camel milk', 'camel milk', 8.33, 'oz', 'dairy');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_ef4761f7d2bba3e47eef1b', 1, ', ripe dates', ' ripe dates', 7, 'plump', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_ef4761f7d2bba3e47eef1b', 2, 'A little bit of sugar', 'a little bit of sugar', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_ef4761f7d2bba3e47eef1b', 3, 'Water', 'water', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ef4761f7d2bba3e47eef1b', 0, 'Remove the seeds from the dates and check if there are any worms inside them');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ef4761f7d2bba3e47eef1b', 1, 'Boil the dates with water and sugar for a few minutes until you feel the dates are well-cooked');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ef4761f7d2bba3e47eef1b', 2, 'Turn off the heat, blend the date mixture, and strain it as well as possible');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ef4761f7d2bba3e47eef1b', 3, 'Pour the resulting date syrup into your cup of milk');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_5a26a9a839a7edb75d6a48', 'Gambian Baobab Juice (Bouye)', 'drink', '''''''Bouye juice'''''' is a delightful and creamy Gambian beverage made from the baobab fruit, which is native to the African continent. This refreshing drink is known for its rich and unique flavor, combining the natural sweetness of the baobab fruit with the creamy texture of evaporated milk.', 1, 5, 0, NULL, 'mocktail', 0, 0, NULL, 'Wikibooks (CC-BY-SA 3.0)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_5a26a9a839a7edb75d6a48', 0, 'baobab fruit pulp', 'baobab fruit pulp', 1, 'cup', 'produce');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_5a26a9a839a7edb75d6a48', 1, 'water', 'water', 4, 'cup', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_5a26a9a839a7edb75d6a48', 2, 'evaporated milk or condensed milk', 'evaporated milk or condensed milk', 1, 'cup', 'dairy');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_5a26a9a839a7edb75d6a48', 3, '¼ cup sugar (adjust according to taste)', ' cup sugar adjust according to taste', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_5a26a9a839a7edb75d6a48', 4, '½ teaspoon vitamin C powder (optional)', ' teaspoon vitamin c powder optional', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_5a26a9a839a7edb75d6a48', 5, 'Ice cubes', 'ice cubes', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_5a26a9a839a7edb75d6a48', 6, 'Fresh mint leaves', 'fresh mint leaves', 0, NULL, 'produce');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5a26a9a839a7edb75d6a48', 0, 'In a blender, combine the baobab fruit pulp and water. Blend on high speed until the mixture is smooth and well-combined');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5a26a9a839a7edb75d6a48', 1, 'Place a strainer or cheesecloth over a pitcher or jug, and pour the blended mixture through it. This will help remove any pulp or seeds, resulting in a smoother juice');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5a26a9a839a7edb75d6a48', 2, 'Add the evaporated milk or condensed milk to the pitcher, along with the sugar and vitamin C powder (if using). Stir well until the sugar is dissolved and the ingredients are thoroughly mixed');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5a26a9a839a7edb75d6a48', 3, 'Refrigerate the bouye juice for at least 1 hour to chill and allow the flavors to meld together');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5a26a9a839a7edb75d6a48', 4, 'Once chilled, give the juice a good stir before serving');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5a26a9a839a7edb75d6a48', 5, 'Pour the juice into glasses filled with ice cubes');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5a26a9a839a7edb75d6a48', 6, 'Garnish each glass with fresh mint leaves for added freshness and aroma');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5a26a9a839a7edb75d6a48', 7, 'Serve the bouye juice immediately and enjoy its refreshing and creamy goodness');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_2844ddb1e1054858e84b81', 'Kunun Tsamiya (Nigerian Powdered Millet and Tsamiya Drink)', 'cocktail', '''''''Kunun tsamiya'''''' is a drink common in northern Nigeria.', 1, 5, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikibooks (CC-BY-SA 3.0)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
