INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_2844ddb1e1054858e84b81', 2, 'millet', 'millet', 1, 'tier', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_2844ddb1e1054858e84b81', 3, 'A few pieces of dried pepper', 'a few pieces of dried pepper', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_2844ddb1e1054858e84b81', 4, 'water', 'water', 1, 'cup', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_2844ddb1e1054858e84b81', 5, 'Tamarind', 'tamarind', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_2844ddb1e1054858e84b81', 6, 'Sugar', 'sugar', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2844ddb1e1054858e84b81', 0, 'Grind together ginger, cloves, millet, and pepper until smooth, and transfer to a bowl. Mix in enough water to get a paste');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2844ddb1e1054858e84b81', 1, 'Combine the tamarind and water in a pot. Set on fire, and allow to boil for few minutes');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2844ddb1e1054858e84b81', 2, 'Slowly add the boiled water into the bowl of millet paste, stirring continuously so that it is lump-free and smooth');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2844ddb1e1054858e84b81', 3, 'Add sugar to taste and serve');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_8d15d45d455da261acff1f', 'Karkanji (Chadian Spiced Hibiscus Drink)', 'cocktail', '''''''Karkanji'''''' is an hibiscus drink from Chad and across the Sahel region. Known for its intense deep red color, it is made from dried hibiscus petals, spiced with ginger and cloves, and sweetened with sugar or honey to taste.', 1, 5, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikibooks (CC-BY-SA 3.0)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_8d15d45d455da261acff1f', 0, 'dried hibiscus (also known as roselle or sorrel) petals', 'dried hibiscus also known as roselle or sorrel petals', 1, 'cup', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_8d15d45d455da261acff1f', 1, '5 cups water', '5 cups water', 4, 'piece', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_8d15d45d455da261acff1f', 2, '3 tablespoons grated fresh ginger', '3 tablespoons grated fresh ginger', 2, 'piece', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_8d15d45d455da261acff1f', 3, 'Sugar, to taste (start with ½ cup)', 'sugar to taste start with cup', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_8d15d45d455da261acff1f', 4, 'cinnamon (optional)', 'cinnamon optional', 1, 'stick', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_8d15d45d455da261acff1f', 5, 'A few slices of lemon (optional)', 'a few slices of lemon optional', 0, NULL, 'produce');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8d15d45d455da261acff1f', 0, 'Rinse the dried hibiscus petals under cold water to remove any dust or debris');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8d15d45d455da261acff1f', 1, 'In a saucepan, bring the water to a boil');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8d15d45d455da261acff1f', 2, 'Add the rinsed hibiscus petals, grated ginger, cloves, and cinnamon stick. Stir well');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8d15d45d455da261acff1f', 3, 'Let the mixture boil for about 5–7 minutes, or until the water turns a rich deep red and the spices have released their aroma');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8d15d45d455da261acff1f', 4, 'Remove the saucepan from heat and let it steep for another 10 minutes for a stronger flavor');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8d15d45d455da261acff1f', 5, 'Strain the liquid using a sieve into a clean jug or bowl to remove the solids');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8d15d45d455da261acff1f', 6, 'Stir in sugar while the drink is still warm, adjusting to your preferred sweetness level');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8d15d45d455da261acff1f', 7, 'Allow the drink to cool completely. Refrigerate until chilled or serve over ice');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_dc48dd258f4282107b6b26', 'Kunun Aduwa (Nigerian Tiger Nut Milk)', 'cocktail', '''''''Kunun aduwa'''''' is a traditional Nigerian beverage made from tiger nuts (''''Cyperus esculentus''''), known locally as aduwa. It is popular in Northern Nigeria and enjoyed for its natural sweetness and health benefits.', 1, 5, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikibooks (CC-BY-SA 3.0)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_dc48dd258f4282107b6b26', 0, 'dried or fresh tiger nuts (aduwa)', 'dried or fresh tiger nuts aduwa', 2, 'cup', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_dc48dd258f4282107b6b26', 1, 'piece fresh ginger (optional)', 'piece fresh ginger optional', 1, 'small', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_dc48dd258f4282107b6b26', 2, '7 dates (dabino), pitted (optional, for extra sweetness)', '7 dates dabino pitted optional for extra sweetness', 5, 'piece', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_dc48dd258f4282107b6b26', 3, 'Water, as needed', 'water as needed', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_dc48dd258f4282107b6b26', 0, 'If using dried tiger nuts, soak them in water overnight to soften, then drain and rinse them');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_dc48dd258f4282107b6b26', 1, 'In a blender, combine the tiger nuts, ginger, and dates. Blend until smooth and creamy, adding water as needed to aid blending');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_dc48dd258f4282107b6b26', 2, 'Strain the blended mixture using a fine sieve or cheesecloth to separate the milk from the chaff');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_dc48dd258f4282107b6b26', 3, 'Chill in the refrigerator and serve cold');
