INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d4ae6ca3d3b6ae2fe9663f', 3, 'While the coffee is still boiling hot, pour it into a mug or, preferably, a stainless steel tumbler. While pouring the coffee, slowly raise the saucepan so the coffee falls into the mug from a height of about 1–1½ ft. This will cause the coffee to froth like espresso');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d4ae6ca3d3b6ae2fe9663f', 4, 'If desired, you can dip a teaspoon in the coffee and lightly spread a few drops of it over the froth in the mug');
