INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_be7ede824d6194d6d5d822', 'Nigerian Pito', 'cocktail', '''''''Pito'''''' is a local drink common in Nigeria. In Lagos specifically, pito is majorly hawked in the street in an earthen pot or drum to keep it chilled.', 1, 5, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikibooks (CC-BY-SA 3.0)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_be7ede824d6194d6d5d822', 0, 'Dried guinea corn (sorghum)', 'dried guinea corn sorghum', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_be7ede824d6194d6d5d822', 1, 'Sugar (optional)', 'sugar optional', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_be7ede824d6194d6d5d822', 0, 'Grind guinea corn into a powder');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_be7ede824d6194d6d5d822', 1, 'Transfer ground guinea corn into a wide bowl, add enough water to fully cover. Stir well with a spatula');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_be7ede824d6194d6d5d822', 2, 'Let the mixture rest until it settles into two phases. Drain the water away');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_be7ede824d6194d6d5d822', 3, 'Pour the guinea corn slurry into a pot and bring to a boil');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_be7ede824d6194d6d5d822', 4, 'After boiling, cool the mash and leave it to ferment for 1 day');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_be7ede824d6194d6d5d822', 5, 'Boil mixture again for a few minutes over medium heat');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_be7ede824d6194d6d5d822', 6, 'Set a sieve over a bowl, and pour the guinea corn mixture into it. Discard the solids');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_be7ede824d6194d6d5d822', 7, 'Stir in sugar if desired, and allow pito to cool');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_be7ede824d6194d6d5d822', 8, 'Serve cold over ice');
