INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_da27f7c0cbfda035dd31b1', 2, 'Bring the saucepan to a simmer over high heat, and simmer for around 15 minutes until tender');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_da27f7c0cbfda035dd31b1', 3, 'Drain the potatoes. Transfer to blender with the almonds, vanilla, maple syrup, and salt. Add the water, and blend until smooth on a high speed, adding more water as necessary');
