INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_aadab2e0a91396b3c79169', 0, 'extra-dark chocolate (should be 85% cocoa or more)', 'extra-dark chocolate should be 85 cocoa or more', 2, 'oz', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_aadab2e0a91396b3c79169', 1, '½ cup cornmeal', ' cup cornmeal', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_aadab2e0a91396b3c79169', 2, 'Very spicy chile peppers (e.g. habaneros)', 'very spicy chile peppers eg habaneros', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_aadab2e0a91396b3c79169', 3, 'Vanilla extract (or vanilla beans, but extract is more convenient)', 'vanilla extract or vanilla beans but extract is more convenient', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_aadab2e0a91396b3c79169', 4, 'Spices such as cloves, cinnamon, or annatto', 'spices such as cloves cinnamon or annatto', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_aadab2e0a91396b3c79169', 5, 'Honey or sugar', 'honey or sugar', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_aadab2e0a91396b3c79169', 6, 'Lots of ice', 'lots of ice', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_aadab2e0a91396b3c79169', 0, 'Toast cornmeal in dry skillet over medium-high heat, stirring frequently. When cornmeal turns a dark tan or light brown color, add 2 cups water, stir, and remove from heat. Let cornmeal soak in water overnight');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_aadab2e0a91396b3c79169', 1, 'Grind cornmeal in blender until it forms a smooth paste. Filter or strain the paste to remove the coarse corn mush. The goal is to make a smooth but thick gel to be used as an emulsifier and thickener. It may be possible to substitute something made of cornstarch instead. Discard the mush and set aside the strained gel');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_aadab2e0a91396b3c79169', 2, 'Bring 2 cups of water to a boil in a saucepan. Meanwhile, cut open the chili peppers and remove the seeds. Add the peppers to the boiling water and boil them until the amount of liquid is reduced to 1 cup. The liquid should be pale yellow and taste very spicy. Discard peppers and set aside liquid');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_aadab2e0a91396b3c79169', 3, 'Add chocolate and 1 cup water to saucepan. Stir frequently over medium heat until chocolate is melted. Slowly add cornmeal gel (you might want to decant it so that any settled lumps or grit remain at the bottom). Add vanilla, spices, and sweetener if desired. Slowly add pepper liquid until the desired spiciness is reached');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_aadab2e0a91396b3c79169', 4, 'Transfer mixture to blender, add lots of ice cubes, and blend until smooth and frothy');
