INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_1a54ddd32a82e91361fc9e', 'South Side Cocktail', 'cocktail', 'A ''''''south side'''''' or ''''''southside'''''' is an alcoholic beverage made with gin, lime juice, simple syrup and mint. A variant, the southside fizz, adds soda water.', 1, 5, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikibooks (CC-BY-SA 3.0)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
