INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ba58937be655e1639b7aa', 0, 'In a large pot, bring the water to a boil');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ba58937be655e1639b7aa', 1, 'Add the dried hibiscus petals to the boiling water and remove the pot from heat');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ba58937be655e1639b7aa', 2, 'Let the petals steep in the water for about 20–30 minutes, allowing them to release their flavor and color');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ba58937be655e1639b7aa', 3, 'Strain the liquid through a fine mesh strainer or cheesecloth, removing the hibiscus petals and collecting the infused liquid in a pitcher or jug');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ba58937be655e1639b7aa', 4, 'While the liquid is still warm, stir in the sugar until it dissolves completely. Adjust the amount of sugar according to your desired sweetness');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ba58937be655e1639b7aa', 5, 'Allow the liquid to cool to room temperature, and then refrigerate it for a few hours or until chilled');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ba58937be655e1639b7aa', 6, 'Once chilled, you can add the freshly squeezed lemon juice for an extra tangy flavor, if desired');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ba58937be655e1639b7aa', 7, 'Serve the wonjo bissap over ice cubes in glasses');
