INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_2d68ba22945c1a7f02c45e', 'Tschunk', 'cocktail', 'Club-Mate is a caffeinated carbonated mate-extract beverage made by the Loscher Brewery in Münchsteinach, Germany, which originated in 1924. Club-Mate has 20 mg of caffeine per 100 ml, sugar content of 5 g per 100 ml, and 20 kcal per 100 ml, which is lower than most energy drinks. Club-Mate is available in 0.33-litre and 0.5-litre bottles.', 1, 3, 0, 'https://upload.wikimedia.org/wikipedia/commons/2/2b/Tschunk_cropped.jpg', 'cocktail', 0, 1, NULL, 'Wikidata + Wikipedia', 'Germany', NULL, NULL, NULL, NULL, NULL, NULL, 'shaken', NULL, NULL, 'unreviewed');
