INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_6ac8ef13271e203dfd0982', 'Whisky and Coke', 'cocktail', 'Whiskey and Coke is a highball cocktail made by mixing whiskey, typically bourbon or Tennessee whiskey, with Coca-Cola or other colas. A popular version of the drink is Jack and Coke, where Jack Daniel''s brand of whiskey is used. The drink is especially popular in the American South. The drink is generally served with ice – sometimes in an old fashioned glass or a Collins glass, and sometimes in less-expensive containers such as Solo Cups. When bourbon is used, it is often called bourbon and Coke, or more generically, bourbon and cola.', 1, 3, 0, 'https://upload.wikimedia.org/wikipedia/commons/e/ed/Jack_Daniels_Lolla_Lemonade.JPG', 'cocktail', 0, 1, NULL, 'Wikidata + Wikipedia', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'shaken', NULL, NULL, 'unreviewed');
