INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_998e9729c8b7b248b13e09', 'Zurracapote', 'cocktail', 'Zurracapote is a popular Spanish alcoholic mixed drink, similar to sangría. It consists of red wine mixed with fruit such as peaches and lemons, sugar, and cinnamon. The concoction is then traditionally left to steep for several days, though some recipes call for the addition of other alcoholic beverages, juices, and fruit extracts. The result is a mild-to-medium alcoholic drink, similar to sangría.', 1, 3, 0, 'https://upload.wikimedia.org/wikipedia/commons/a/ad/Preparando_Zurracapote.jpg', 'cocktail', 0, 1, NULL, 'Wikidata + Wikipedia', 'Spain', NULL, NULL, NULL, NULL, NULL, NULL, 'shaken', NULL, NULL, 'unreviewed');
