INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_f22ab1f13d9be91b34eb49', 'Mint tea (herbal tea)', 'cocktail', 'Mint tea is a herbal tea made by infusing mint leaves in hot water. Mint tea can be brewed with fresh leaves, or with dehydrated leaves that have been dried to a moisture level of less than 10%. Mint tea made with peppermint leaves is called peppermint tea, and mint tea made with spearmint is called spearmint tea. There also exist teas that infuse peppermint and spearmint leaves. In Korea, traditional mint tea called bakha-cha (박하차) is made with East Asian wild mint leaves. In India, traditional mint tea called pudina chai is made by steeping spearmint or peppermint in hot chai.', 1, 3, 0, 'https://upload.wikimedia.org/wikipedia/commons/e/ed/Muntthee_02.JPG', 'cocktail', 0, 1, NULL, 'Wikidata + Wikipedia', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'shaken', NULL, NULL, 'unreviewed');
