INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_d0ee6ba733f014a6253a5c', 'Bacon martini', 'cocktail', 'A Bacon Martini, also known as bacontini, pig on the rocks or a bloody bacon martini, is a cocktail that consists of bacon-infused vodka served with a garnish that can include strips of bacon, bacon bits, or olives.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', NULL, NULL, NULL, NULL, NULL, NULL, 'martini', 'shaken', 'bacon, olive', 31, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_d0ee6ba733f014a6253a5c', 0, 'bacon vodka', 'bacon vodka', 1.69, 'oz', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_d0ee6ba733f014a6253a5c', 1, 'strip of bacon, olive', 'strip of bacon olive', 0, NULL, 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d0ee6ba733f014a6253a5c', 0, 'To make a bacon martini, the vodka needs to be prepared in advance through a process called fat washing');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d0ee6ba733f014a6253a5c', 1, 'This is done by soaking strips of cooked bacon in vodka and straining off the fat, similar to the process for marinating meat before cooking');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d0ee6ba733f014a6253a5c', 2, 'The drink is ready when the liquid becomes filmy and opaque');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d0ee6ba733f014a6253a5c', 3, 'At the Double Down Saloon in the East Village in New York City, the bacon martini is created by straining the bacon-infused vodka through shaken ice and serving it in a martini glass with a piece of bacon at the bottom, similar to the worm in a bottle of mezcal');
