INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_707cbb589ba0f16bb33cd9', 'Broken Spur (cocktail)', 'cocktail', 'The Broken Spur cocktail is a mixed drink with white port, vermouth, gin, egg yolk and a splash of anisette for flavor. The recipe is found in The Savoy Cocktail Book. Some recipes replace the anisette with Pernod. The cocktail is shaken with ice and served in a coupé glass garnished with a twist of lemon peel or dusted with freshly grated nutmeg.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', NULL, NULL, NULL, NULL, NULL, NULL, 'coupe', 'shaken', 'Lemon peel or freshly grated nutmeg', 20, 'unreviewed');
