INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_2469eb8549968a37de767c', 'Brooklyn (cocktail)', 'cocktail', 'The Brooklyn is one of five cocktails named for the boroughs of New York City, along with the Bronx, the Manhattan, the Queens and the Staten Island Ferry. It resembles a Manhattan, but with dry vermouth, Picon, and Maraschino. It largely fell into obscurity after the end of Prohibition, but experienced a resurgence in the 1990s.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', 'United States', NULL, NULL, NULL, NULL, NULL, 'martini', 'stirred', 'cherry', 26, 'unreviewed');
