INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_ef7da151509b8346c9664d', 0, 'blue wkd', 'blue wkd', 9.3, 'oz', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_ef7da151509b8346c9664d', 1, 'port', 'port', 1.69, 'oz', 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ef7da151509b8346c9664d', 0, 'The cocktail is made up of ruby port and Blue WKD');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ef7da151509b8346c9664d', 1, 'Though the owners of Vimto decided they would not manufacture an alcopop version, the company has encouraged its use as a mixer');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ef7da151509b8346c9664d', 2, 'Many establishments give the Cheeky Vimto other names in order to avoid breaching the trademark of the soft drink');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ef7da151509b8346c9664d', 3, 'A variation consisting of the port and WKD, without the Vimto, was described in Amy Winehouse''s biography as one of her beverages of choice');
