INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_68beccd1f278e0bad3c72b', 'Cremat', 'cocktail', 'Cremat or rom cremat (, Catalan for ''burnt (rum)''), also known as cremaet in Valencia, is an alcoholic cocktail of Catalan origin. Although many different recipes exist, the common elements to most of them are rum, sugar, spices (particularly cinnamon), lemon peel, and some form of coffee (usually roasted beans, but soluble instant coffee or brewed coffee are also used).', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'shaken', NULL, NULL, 'unreviewed');
