INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_2ae9166f15917fedfecdf9', 'Curaçao punch', 'cocktail', 'Curaçao punch is a cocktail that comes from Harry Johnson''s New and Improved Bartender''s Manual (1882), though a drink of that name was served in the Metropolitan Hotel in Washington, D.C. at least as early as 1867. Dale DeGroff, a notable bartender and author of The Craft of the Cocktail (Clarkson Potter, 2002), holds this to be his favorite forgotten potation.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'stirred', NULL, 21, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_2ae9166f15917fedfecdf9', 0, '(7 ml) sugar', '7 ml sugar', 0.5, 'tbsp', 'condiment');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_2ae9166f15917fedfecdf9', 1, 'or 3 dashes fresh lemon juice', 'or 3 dashes fresh lemon juice', 2, NULL, 'produce');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_2ae9166f15917fedfecdf9', 2, '(1/4 gill, 3 cl) soda water', '14 gill 3 cl soda water', 1, 'oz', 'beverage');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_2ae9166f15917fedfecdf9', 3, '(1/4 gill, 3 cl) brandy', '14 gill 3 cl brandy', 1, 'oz', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_2ae9166f15917fedfecdf9', 4, '(1/2 gill, 6 cl) orange curaçao', '12 gill 6 cl orange curaao', 2, 'oz', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_2ae9166f15917fedfecdf9', 5, '(1/4 gill, 3 cl) jamaican rum', '14 gill 3 cl jamaican rum', 1, 'oz', 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2ae9166f15917fedfecdf9', 0, 'Preparation involves combining the sugar, lemon juice, and soda water, dissolving the sugar, pouring the drink into a glass with finely-shaved or crushed ice and then adding the remaining ingredients');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2ae9166f15917fedfecdf9', 1, 'The drink is then stirred and may be garnished with a variety of fruits');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2ae9166f15917fedfecdf9', 2, '*1/2 tablespoon (7 ml) sugar (This indulged the major nineteenth-century sweet tooth-alter to taste.) *2 or 3 dashes fresh lemon juice (More of this can also compensate for the sweetness.) *1 ounce (1/4 gill, 3 cl) soda water *1 ounce (1/4 gill, 3 cl) brandy (Johnson calls for Martell cognac.) *2 ounce (1/2 gill, 6 cl) orange curaçao *1 ounce (1/4 gill, 3 cl) Jamaican rum (Dale suggests a full-bodied style of rum.)');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_2ea6f1298cc48daf7084ee', 'Damn the weather', 'cocktail', 'A damn the weather (or damn-the-weather) is a Prohibition Era cocktail made with Gin, sweet vermouth, orange juice, and a sweetener (either Triple Sec or Curaçao). It is served shaken and chilled, often with a slice of orange or other citrus fruit.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', NULL, NULL, NULL, NULL, NULL, NULL, 'martini', 'shaken', 'Slice of orange', NULL, 'unreviewed');
