INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_5c446649b76809959a1255', 'Fernet con coca', 'cocktail', 'Fernet con coca (, "Fernet and Coke"), also known as fernando, its diminutive fernandito (), or several other nicknames, is a long drink of Argentine origin consisting of the Italian amaro liqueur fernet and cola, served over ice. Although typically made with Fernet-Branca and Coca-Cola, several amaro brands have appeared in Argentina since its popularization, as well as ready-to-drink versions.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', 'Italy', NULL, NULL, NULL, NULL, NULL, 'rocks', 'stirred', NULL, 30, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_5c446649b76809959a1255', 0, 'fernet-branca', 'fernet-branca', 1.69, 'oz', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_5c446649b76809959a1255', 1, 'cola to top up', 'cola to top up', 0, NULL, 'beverage');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5c446649b76809959a1255', 0, 'Thumb|Fernet con coca is a simple, two-ingredient cocktail known for its gold-tinted foam and bittersweet taste');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5c446649b76809959a1255', 1, 'Fernet con coca is a long drink, usually served in a tall tumbler such as the highball');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5c446649b76809959a1255', 2, 'Simple in composition, the two-ingredient cocktail comprises just its eponymous ingredients and ice');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5c446649b76809959a1255', 3, 'The result is a black concoction with a "velvety", gold-tinted foam, and a complex and bittersweet taste that features competing and complementary flavors');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5c446649b76809959a1255', 4, 'The exact proportions of each ingredient are debated, and people prepare the cocktail according to personal taste');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5c446649b76809959a1255', 5, 'A popular measurement is three parts fernet and seven parts cola.{{Cite news |last=Ventura |first=Marco |url=http://www.branca.it/dati/pagine/Panorana_BrancaArgentina250412.pdf |title=A Buenos Aires c''è un conte filosofo che si è bevuto la crisi con un Fernet |date=April 25, 2012 |work=Panorama |pages=106–11 |language=it |access-date=June 16, 2020 |archive-url=https://web.archive.org/web/20131029195413/http://www.b');
