INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_2a74d3d432d8444b7195ef', 'Grasshopper (cocktail)', 'cocktail', 'A grasshopper is a sweet, mint-flavored, after-dinner alcoholic drink named for its green color, which comes from crème de menthe. Tujague''s, a bar in the French Quarter of New Orleans, Louisiana, claims its owner Philip Guichet invented the drink in 1918. The drink gained popularity during the 1950s and 1960s throughout the American South.', 1, 3, 0, NULL, 'cocktail', 0, 0, NULL, 'Wikipedia (CC-BY-SA)', 'United States', NULL, NULL, NULL, NULL, NULL, 'martini', 'shaken', NULL, NULL, 'unreviewed');
