INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_f297cedcca09b7effd8b88', 'Green Swizzle', 'cocktail', 'A Green Swizzle is an alcohol-containing cocktail of the sour family. It was popular in Trinidad at the beginning of the 20th century but got lost during the course of the Second World War. Today''s recipes usually constitute an often distinct divergence from the original.', 1, 3, 0, NULL, 'cocktail', 0, 0, NULL, 'Wikipedia (CC-BY-SA)', 'Caribbean', NULL, NULL, NULL, NULL, NULL, 'collins', 'shaken', NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_f297cedcca09b7effd8b88', 0, 'falernum, carypton', 'falernum carypton', 0, NULL, 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_f297cedcca09b7effd8b88', 0, 'As it''s typical for a swizzle, the ingredients are combined in a high, narrow, cooled glass which is then filled up with crushed ice');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_f297cedcca09b7effd8b88', 1, 'A swizzle stick is inserted into the filled glass and then rotated with the palms while at the same time the stick is slowly moved upwards and downwards');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_f297cedcca09b7effd8b88', 2, 'Thereby ingredients and ice are mixed while at the same time the glass is cooled down so quickly that it forms hoarfrost on the outside');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_f297cedcca09b7effd8b88', 3, 'The preparation method is the same for "forged" Green Swizzles with crème de menthe');
