INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_09deab8a08664d0b558d0d', 0, 'Anthony Burgess described its preparation as pouring doubles of gin, whisky, rum, port and brandy into a pint glass');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_09deab8a08664d0b558d0d', 1, 'A small bottle of stout is added and the drink is topped with champagne');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_09deab8a08664d0b558d0d', 2, 'According to Burgess, "it tastes very smooth, induces a somewhat metaphysical elation, and rarely leaves a hangover."');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_fd6f60a953f32c02679197', 'Hanky panky (cocktail)', 'cocktail', 'The hanky panky is a cocktail made from gin, sweet vermouth, and Fernet-Branca. It is a variation on the sweet martini, or Martinez, made distinctive by the Fernet-Branca, a bitter Italian digestivo. It was created by Ada "Coley" Coleman, head bartender at the Savoy Hotel, London.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', 'Italy', NULL, NULL, NULL, NULL, NULL, 'martini', 'stirred', 'Orange zest', 23, 'unreviewed');
