INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fd6f60a953f32c02679197', 0, 'Stirred over ice, strained into a chilled glass, garnished, and served up');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_a32211948f5e846ed5e53c', 'Harlem mugger (cocktail)', 'cocktail', 'A Harlem mugger is an alcoholic cocktail usually made with 1/2 oz vodka, 1/2 oz gin, 1/2 oz white rum, 1/2 oz tequila, and 3 oz Champagne, topped with cranberry juice. It is normally served straight up and garnished with a wedge of lime.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'shaken', NULL, NULL, 'unreviewed');
