INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_5e654e7c9104d4958ec9cf', 0, 'guinness stout, baileys irish cream, and jameson irish whiskey', 'guinness stout baileys irish cream and jameson irish whiskey', 0, NULL, 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5e654e7c9104d4958ec9cf', 0, 'The whiskey is floated on top of the Irish cream in a shot glass, and the shot glass is then dropped into the stout');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_a2a4fb1553be123715580c', 'Jack Rose (cocktail)', 'cocktail', 'A Jack Rose is a cocktail containing applejack, grenadine, and lemon or lime juice. It was popular in the 1920s and 1930s, notably appearing in Ernest Hemingway''s 1926 classic, The Sun Also Rises, in which Jake Barnes, the narrator, drinks a Jack Rose in the bar of the Hôtel de Crillon while awaiting the arrival of Lady Brett Ashley. It was also a favorite drink of author John Steinbeck.', 1, 3, 0, NULL, 'cocktail', 0, 0, NULL, 'Wikipedia (CC-BY-SA)', NULL, NULL, NULL, NULL, NULL, NULL, 'martini', 'shaken', 'lemon zest', NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_a2a4fb1553be123715580c', 0, 'applejack', 'applejack', 4, 'part', 'bar');
