INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_09fa5f8eae865588f81e63', 0, '* 2 ounces (1/2 gill, 6 cl) Scotch * 1/2 ounce (1/8 gill, 1.5 cl) Dark Jamaican rum * 1 teaspoon absinthe or pastis (Pernod, herbsaint, and richard all work) * 1/2 ounce (1/8 gill, 1.5 cl) Swedish Punsch * 1/2 ounce (1/8 gill, 1.5 cl) fresh lemon juice * 2 dashes orange bitters * Shake in an iced cocktail shaker, and strain into cocktail glass');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_09fa5f8eae865588f81e63', 1, '* Add a lemon twist');
