INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_982aa41b903bb9b9c2a3c9', 'Vieux Carré (cocktail)', 'cocktail', 'The Vieux Carré is an IBA official cocktail made with rye whiskey, cognac, sweet vermouth, Bénédictine, and Peychaud''s bitters. It originated with Walter Bergeron, a bartender at the Carousel Bar in Hotel Monteleone, New Orleans. The name is French for "old square”, in reference to the city''s French Quarter neighborhood. The drink is classified as one of the Unforgettables by the IBA.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', 'United States', NULL, NULL, NULL, NULL, NULL, 'martini', 'stirred', 'Orange zest and maraschino cherry', 26, 'unreviewed');
